  ui_story_5053_50530102_74_dialog_content = "อึ่ก...อึ่ก...",
  ui_story_5053_50530102_75_dialog_content = "มันไปไหนแล้ว",
  ui_story_5053_50530102_76_dialog_content = "คงหนีไปทางข้างนอก",
  ui_story_5053_50530102_77_dialog_content = "มันยอดเยี่ยมมาก ท่านชวาร์ตษ์!",
  ui_story_5053_50530102_78_dialog_content = "ไม่ว่ามันจะทรงพลังเพียงใด ทูตสวรรค์ก็ต้องบาดเจ็บสาหัส สงสัยจะไปได้ไกลมาก",
  ui_story_5053_50530102_79_dialog_content = "...",
  ui_story_5053_50530102_80_dialog_content = "คุณยังกังวลเกี่ยวกับ Dark Angel อยู่หรือเปล่า ลุง?",
  ui_story_5053_50530102_81_dialog_content = "เสียงของมัน... ไม่เป็นไร น้องสาวของฉันไม่มีวันเป็นสัตว์ประหลาดได้",
  ui_story_5053_50530102_82_dialog_content = "ใช้เวลาในการเสกของคุณ Jakine",
  ui_story_5053_50530102_83_dialog_content = "หึ... เออ! ในที่สุดทูตสวรรค์ที่เข้าไปยุ่งก็หายไปแล้ว ฉันจะพาทุกคนออกไปได้!",
  ui_story_5053_50530102_84_dialog_content = "โฆษณาชวนเชื่อ! โฆษณาชวนเชื่อ! โฆษณาชวนเชื่อ!",
  ui_story_5053_50530102_85_dialog_content = "ให้เรากลับสู่ความเป็นจริง!",
  ui_story_5053_50530102_86_dialog_content = "อะบราคาดาบร้า!",
  ui_story_5053_50530102_87_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530102_88_dialog_content = "ฉันไม่คิดว่ามันได้ผล ...",
  ui_story_5053_50530102_89_dialog_content = "ให้ฉันลองอีกครั้ง!",
  ui_story_5053_50530102_90_dialog_content = "โฆษณาชวนเชื่อ! โฆษณาชวนเชื่อ! โฆษณาชวนเชื่อ!",
  ui_story_5053_50530102_91_dialog_content = "ให้เรากลับสู่ความเป็นจริง! อะบราคาดาบร้า!",
  ui_story_5053_50530102_92_dialog_content = "แน่ใจนะว่าพูดถูก Jakine?",
  ui_story_5053_50530102_93_dialog_content = "แน่นอน! ทุกคนจับมือกัน? ขอเช็คหน่อย... เย้!",
  ui_story_5053_50530102_94_dialog_content = "ฉันคิดว่าครั้งที่แล้วมันไม่สำเร็จเพราะมันยุ่งเหยิงมากจนมือของเราเชื่อมโยงกันไม่ได้",
  ui_story_5053_50530102_95_dialog_content = "แต่ทำไมคราวนี้มันยังไม่ได้ผล?",
  ui_story_5053_50530102_96_dialog_content = "คุณได้ครอบครองคริสตัลสำหรับอาณาจักรนี้เมื่อคุณร่ายเวทย์ครั้งสุดท้าย ครั้งนี้เธอลืมแล้วเหรอ?",
  ui_story_5053_50530102_97_dialog_content = "เลขที่, <color=#FFB400>คุณต้องการมันเมื่อย้อนเวลาเท่านั้น</color>... นั่นคือเหตุฉุกเฉินที่ล้มเหลวโดยแม่ของฉันตั้งค่าไว้",
  ui_story_5053_50530102_98_dialog_content = "ไม่จำเป็นสำหรับการออกเดินทางมาตรฐานเช่นนี้!",
  ui_story_5053_50530102_99_dialog_content = "มีความเป็นไปได้อื่นอีกไหม?",
  ui_story_5053_50530102_100_dialog_content = "เว้นเสียแต่ว่า... <color=#FFB400>พวกเราทุกคนไม่ได้อยู่ที่นี่</color>.",
  ui_story_5053_50530102_101_dialog_content = "เธอหมายความว่าไง",
  ui_story_5053_50530102_102_dialog_content = "เนื่องจากความกังวลด้านความปลอดภัย บุคคลต้องเปิดใช้งานคริสตัลเพื่อเข้าไปข้างใน และทุกคนจะต้องอยู่พร้อมหน้ากันเพื่อออกจากปาร์ตี้ทั้งหมด",
  ui_story_5053_50530102_103_dialog_content = "แม้ว่าฉันจะทำผิดกฎนั้นโดยไม่ได้ตั้งใจเมื่อเราเข้ามา แต่ฉันก็ไม่สามารถทำอย่างนั้นได้เมื่อเราออกไป!",
  ui_story_5053_50530102_104_dialog_content = "พวกเราทุกคนอยู่ที่นี่ใช่ไหม? ฉันไม่ได้คิดถึงใครเลย...",
  ui_story_5053_50530102_105_dialog_content = "มีคนอื่นเข้ามาร่วมแจมกับเราไหม?",
  ui_story_5053_50530102_106_dialog_content = "หรือบางทีก่อนที่เราจะเข้าไปก็มีคนเข้ามาด้วยวิธีอื่น",
  ui_story_5053_50530102_107_dialog_content = "แต่ผู้กระตุ้นเสียชีวิตไปนานแล้ว เป็นไปไม่ได้ใช่ไหม?",
  ui_story_5053_50530102_108_dialog_content = "...",
  ui_story_5053_50530102_109_dialog_content = "นายท่าน ท่านมาด้วยตนเอง?!",
  ui_story_5053_50530102_110_dialog_content = "ฉันขอโทษที่ความไร้ความสามารถของเรารบกวนความสงบสุขของคุณ",
  ui_story_5053_50530102_111_dialog_content = "ไม่เป็นไร คุณบอกฉันได้ไหมว่าเกิดอะไรขึ้น",
  ui_story_5053_50530102_112_dialog_content = "แน่นอน. มีบุคคลที่ไม่รู้จักหลายคนบุกรุกเข้าไปในสวนและต่อสู้กับสัตว์ประหลาด",
  ui_story_5053_50530102_113_dialog_content = "ผู้บุกรุกคนหนึ่งดูและแต่งตัวเหมือนเจ้าหญิงเวโรนิกามาก แต่ฉันไม่แน่ใจ...",
  ui_story_5053_50530102_114_dialog_content = "เวโรนิก้า? ฉันเห็น. คุณทำงานได้ดี",
  ui_story_5053_50530201_1_dialog_content = "พวกคุณไม่อยากลองของว่างเหล่านี้เหรอ? ฉันจะทำให้มันเสร็จถ้าคุณไม่ทำ",
  ui_story_5053_50530201_2_dialog_content = "ไม่อยากจะเชื่อเลยว่าคุณยังอยู่ในอารมณ์นั้น",
  ui_story_5053_50530201_3_dialog_content = "เราเพิ่งต่อสู้ในสวนของเลดี้โจชัว ฉันไม่มีความคิดที่จะทำลายมันกับเธอ",
  ui_story_5053_50530201_4_dialog_content = "ผ่อนคลาย ผ่อนคลาย! ความเครียดทำให้เราไปไหนไม่ได้!",
  ui_story_5053_50530201_5_dialog_content = "ฉันอิจฉาคุณสำหรับการมองโลกในแง่ดีของคุณ",
  ui_story_5053_50530201_6_dialog_content = "โยชูวาไม่ใช่คนที่จะพบกับการลงโทษที่รุนแรง",
  ui_story_5053_50530201_7_dialog_content = "เนื่องจากเธอสั่งให้พาเรามาที่นี่และแม้แต่ให้ขนมด้วย ก็แสดงให้เห็นอย่างชัดเจนว่าเธอปฏิบัติต่อเราด้วยความเคารพ ไม่ใช่เป็นศัตรู",
