  ui_story_5053_50530201_9_dialog_content = "ถ้า <color=#FFB400>คนอื่น</color> ก็เคยอยู่ด้วย เราคงถูกจองจำไปแล้ว",
  ui_story_5053_50530201_10_dialog_content = "คนอื่น? คุณกำลังพูดถึงใคร",
  ui_story_5053_50530201_11_dialog_content = "...",
  ui_story_5053_50530201_12_dialog_content = "เขาหมายถึงฉันที่อายุน้อยกว่า",
  ui_story_5053_50530201_13_dialog_content = "คุณไม่ได้เป็นตัวของตัวเองมากนักลอร์ดชวาร์ตษ์",
  ui_story_5053_50530201_14_dialog_content = "A-ยังไงก็ตาม Lady Joshua แห่งโลกนี้มา",
