  ui_story_5053_50530201_23_dialog_content = "ใช้ได้! ตราบใดที่เรามีระบบป้องกันความผิดพลาดอยู่ในมือ เราก็สามารถย้อนกลับเพื่อซื้อเวลาให้ตัวเองได้!",
  ui_story_5053_50530201_24_dialog_content = "แม้ว่านั่นจะทำให้ Lumina หมดไปในการบำรุงรักษาโลก ดังนั้นเราจึงไม่สามารถทำตามอำเภอใจได้",
  ui_story_5053_50530201_25_dialog_content = "ลำดับความสำคัญสูงสุดของเราคือการตามหา Crystal of Eternal Memory เราควรพักเรื่อง Dark Angel ไว้ก่อน",
