  ui_story_5053_50530201_34_dialog_content = "ฉันจะเป็นใครได้อีก อัจฉริยะตัวน้อยที่รักของฉัน?",
  ui_story_5053_50530201_35_dialog_content = "...",
  ui_story_5053_50530201_36_dialog_content = "แน่ใจนะ จาคีน?",
  ui_story_5053_50530201_37_dialog_content = "แน่นอนฉันจะเป็น! เว้นแต่จะมีปัญหากับดวงตาของฉัน!",
