  ui_story_5053_50530201_40_dialog_content = "คุณยังดูเหมือนเดิมมากกับตอนที่เข้าร่วมกับอัศวิน เหมือนที่ฉันจำได้",
  ui_story_5053_50530201_41_dialog_content = "*ดม* นั่นสินะ... ก็เพราะ...",
  ui_story_5053_50530201_42_dialog_content = "เป็นเพราะ Forsakin ดัดแปลง Veronica... ร่างกายของ Mia และทำให้เธออายุ 13 ปีตลอดไป",
  ui_story_5053_50530201_43_dialog_content = "แต่เดี๋ยวก่อน ฉันเห็นด้วยตาของฉันเองว่าคุณ...",
