  ui_story_5053_50530201_46_dialog_content = "จากนั้นเธอก็ถูกส่งไปที่ห้องแล็บของอิลลูมินาเพื่อทำสิ่งที่เรียกว่า \"การรักษา\" ซึ่งเป็นกับดักที่ Eclipsites และผู้ทรยศตั้งขึ้น",
  ui_story_5053_50530201_47_dialog_content = "เพื่อช่วยเวโรนิกา โจชัวไปต่อสู้กับพวกเขาด้วยตัวเธอเอง",
  ui_story_5053_50530201_48_dialog_content = "การช่วยเหลือประสบความสำเร็จ แต่อย่างใด พวกเขาได้เพาะเมล็ดพันธุ์ในโจชัวด้วย...",
  ui_story_5053_50530201_49_dialog_content = "ต่อมาหลังจากทนทุกข์มามาก...",
  ui_story_5053_50530201_50_dialog_content = "เธอ <color=#FFB400>เลือกที่จะจบชีวิตตัวเอง</color>.",
