  ui_story_5053_50530201_52_dialog_content = "ชวาร์ตษ์ นี่คือวิธีที่คุณคุยกับภรรยาที่คุณไม่ได้เจอกันมา 12 ปี?!",
  ui_story_5053_50530201_53_dialog_content = "ไม่เป็นไร คาเลบ แดเนียลกำลังทำสิ่งที่ถูกต้องเพื่อปกป้องทุกคน",
