  ui_story_5053_50530201_74_dialog_content = "อ๊ากก...",
  ui_story_5053_50530201_75_dialog_content = "<color=#e8d9bb>แกล๊ง!</color>",
  ui_story_5053_50530201_76_dialog_content = "คริสตัลแห่งความทรงจำนิรันดร์...?",
  ui_story_5053_50530201_77_dialog_content = "คุณกำลังทำอะไร? เลขที่!!!",
  ui_story_5053_50530201_78_dialog_content = "ย้อนวันวานวันทองในอดีต...",
  ui_story_5053_50530201_79_dialog_content = "<color=#e8d9bb>แผละ!</color>",
  ui_story_5053_50530201_80_dialog_content = "คุณสบายดีไหม โจชัว เสียงดังอะไรเบอร์นั้น",
  ui_story_5053_50530201_81_dialog_content = "ทำไมคุณไม่ตอบ หยุดทำให้ฉันคลั่งไคล้ ฉันกำลังเข้ามา",
  ui_story_5053_50530201_82_dialog_content = "เจ-โจชัว...?",
  ui_story_5053_50530201_83_dialog_content = "<size=50>น้องสาว!!!</size>",
  ui_story_5053_50530201_84_dialog_content = "เมล็ดพันธุ์แบ่งฉันออกเป็น <color=#FFB400>สองบุคลิกที่แตกต่างกัน</color>.",
  ui_story_5053_50530201_85_dialog_content = "คนหนึ่งคือตัวฉันธรรมดา แต่อีกคนคือสัตว์ประหลาดที่บ้าคลั่งไร้เหตุผล",
  ui_story_5053_50530201_86_dialog_content = "เมื่อมันโตขึ้น มันเริ่มพยายามครอบครองฉันและทำร้ายคนรอบข้าง",
  ui_story_5053_50530201_87_dialog_content = "ฉันยอมไม่ได้ ฉันเลยเริ่มต่อสู้กับมัน",
  ui_story_5053_50530201_88_dialog_content = "การปะทะกันอย่างต่อเนื่องระหว่างบุคลิกภาพทำให้จิตใจของฉันแหลกสลายทุกวัน",
  ui_story_5053_50530201_89_dialog_content = "มันไม่ได้ส่งผลกระทบต่อมอนสเตอร์เลย มันจึงค่อย ๆ ได้เปรียบ...",
  ui_story_5053_50530201_90_dialog_content = "ฉันกำลังจะล้มลงและรู้ว่าฉันกำลังจะสูญเสีย",
  ui_story_5053_50530201_91_dialog_content = "ดังนั้นฉันจึงคิดวิธีแก้ปัญหาที่จะไม่ปล่อยให้ฉันชนะ แต่จะต้องเอาชนะสัตว์ประหลาดให้ได้—",
  ui_story_5053_50530201_92_dialog_content = "<color=#FFB400>และนั่นคือการกักขังเราทั้งคู่ไว้ใน Crystal of Eternal Memory</color>.",
  ui_story_5053_50530201_93_dialog_content = "ด้วยความปรารถนาที่จะตาย ฉันส่งตัวเองและสัตว์ประหลาดมายังโลกนี้",
  ui_story_5053_50530201_94_dialog_content = "เราเป็นหนึ่งเดียวกัน ตราบใดที่ฉันไม่จากไป มันต้องอยู่กับฉันที่นี่",
  ui_story_5053_50530201_95_dialog_content = "เราต่อสู้กันมานานแสนนาน",
  ui_story_5053_50530201_96_dialog_content = "หลังจากนาฬิกาบอกเวลาเที่ยงคืน เรากลายเป็นส่วนหนึ่งของโลกนี้ตั้งแต่เราทำผิดกฎ",
  ui_story_5053_50530201_97_dialog_content = "เราสูญเสียความทรงจำของเราและกลับมารวมกันอีกครั้งเพื่อเป็น Joshua ของโลกนี้ และเราได้หวนนึกถึงวันเดิมๆ ซ้ำแล้วซ้ำเล่าตลอดเวลานี้",
  ui_story_5053_50530201_98_dialog_content = "จนกว่าคุณจะมาถึง",
  ui_story_5053_50530201_99_dialog_content = "การมาของคุณปลุกความทรงจำของเรา",
  ui_story_5053_50530201_100_dialog_content = "สัตว์ประหลาดที่ตื่นขึ้นพยายามดิ้นรนและแยกตัวออกจากฉัน",
  ui_story_5053_50530201_101_dialog_content = "<color=#FFB400>เธอขโมยพลังทั้งหมดของฉันไป</color> และหนีไปโดยพยายามออกจากคริสตัล",
  ui_story_5053_50530201_102_dialog_content = "สถานการณ์เลวร้าย แต่คราวนี้...",
  ui_story_5053_50530201_103_dialog_content = "ฉันไม่ได้อยู่คนเดียวอีกต่อไป",
  ui_story_5053_50530201_104_dialog_content = "...",
  ui_story_5053_50530201_105_dialog_content = "ว- ช่างเป็นเรื่องราวที่น่าอัศจรรย์ยิ่งนัก... <color=#FFB400>ดาร์กแองเจิ้ลที่โจมตีเราคือเลดี้โจชัวอีกคน</color>?",
  ui_story_5053_50530201_106_dialog_content = "ทูตสวรรค์มืด? คุณตั้งชื่อมันว่า...? อย่างไรก็ตาม ใช่ คุณสามารถพูดแบบนั้นได้",
  ui_story_5053_50530201_107_dialog_content = "มีเพียง Joshua และฉันเท่านั้นที่เป็นองคมนตรีในการสนทนานั้น และรายละเอียดก็ตรงกันทุกประการ",
  ui_story_5053_50530201_108_dialog_content = "เป็นคุณจริงๆ โจชัว...",
  ui_story_5053_50530201_109_dialog_content = "เป็นเรื่องดีที่คุณเชื่อฉันในที่สุด",
  ui_story_5053_50530201_110_dialog_content = "โอ้แม่เจ้า...เจ้าจริง...",
  ui_story_5053_50530201_111_dialog_content = "ร้องไห้อีกแล้วนะตัวเล็ก",
  ui_story_5053_50530201_112_dialog_content = "ฉันไม่อยากจะเชื่อเลยว่าคุณจะอยู่ที่นี่ โจชัว ฉันมองหา...และไม่เคยพบคุณเลย...",
  ui_story_5053_50530201_113_dialog_content = "มันวิเศษมากที่ได้คุยกับคุณอีกครั้งหลังจากผ่านไป 12 ปี...",
  ui_story_5053_50530201_114_dialog_content = "(The Seed สองบุคลิก... ฟังดูคล้ายกับสิ่งที่เกิดขึ้นกับ Mia เลย)",
  ui_story_5053_50530201_115_dialog_content = "(บุคลิกของมีอาเป็นเพื่อนและพึ่งพาอาศัยกัน แต่เลดี้โจชัวกลับตรงกันข้าม)",
  ui_story_5053_50530201_116_dialog_content = "(เมล็ดพืชมีผลแตกต่างกันไปในแต่ละบุคคล)",
  ui_story_5053_50530201_117_dialog_content = "เมื่อพูดถึงเรื่องนี้ คุณพูดถึงบางสิ่งเมื่อสิบสองปีที่แล้ว",
  ui_story_5053_50530201_118_dialog_content = "ฉันอยู่ที่นี่มาสิบสองปีแล้วเหรอ?",
  ui_story_5053_50530201_119_dialog_content = "ถูกต้อง",
  ui_story_5053_50530201_120_dialog_content = "ไม่แปลกใจเลยว่าทำไมคุณถึงดูแตกต่างไปจากเดิมอย่างสิ้นเชิง แดเนียล",
  ui_story_5053_50530201_121_dialog_content = "ฉันคงจำคุณไม่ได้ถ้าไม่ใช่เพราะคนอื่นเรียกชื่อคุณ",
  ui_story_5053_50530201_122_dialog_content = "แต่เกิดอะไรขึ้นกับดวงตาและใบหน้าของคุณ?",
  ui_story_5053_50530201_123_dialog_content = "ฉันผ่านสงครามและความวุ่นวายมามากเกินกว่าจะนึกถึงต้นกำเนิดของแผลเป็นของฉันได้",
  ui_story_5053_50530201_124_dialog_content = "แต่ฉันยังจำวันที่เธอจากฉันไป และกริชบนหน้าอกของเธอช่างเหน็บหนาวเพียงใด...",
  ui_story_5053_50530201_125_dialog_content = "แดเนียล...",
  ui_story_5053_50530201_126_dialog_content = "พูดถึง ศพของ Lady Joshua ถูกฝังอยู่ใช่ไหม?",
  ui_story_5053_50530201_127_dialog_content = "เธอหรือดาร์กแองเจิ้ลจะทิ้งคริสตัลไว้ได้หรือไม่?",
  ui_story_5053_50530201_128_dialog_content = "ได้สิ",
  ui_story_5053_50530201_129_dialog_content = "เพราะร่างกายของเธอ <color=#FFB400>ไม่เคยถูกฝัง</color>.",
  ui_story_5053_50530201_130_dialog_content = "หมายความว่าไง",
  ui_story_5053_50530201_131_dialog_content = "ฮึ่ม ตอนที่ฉันพบเธอ เธอยังไม่ตาย",
  ui_story_5053_50530201_132_dialog_content = "ฉันถอดของบางอย่างออกและนำเธอกลับบ้านเพื่อรับการรักษา",
  ui_story_5053_50530201_133_dialog_content = "อะไร แต่ฉันได้ยินคนทั้งเมืองเห็นงานศพ แล้วคุณทำอะไร...",
  ui_story_5053_50530201_134_dialog_content = "ฉันจัดการงานศพของ Joshua เป็นการส่วนตัว ดังนั้นจะไม่มีการก้าวพลาดใดๆ",
  ui_story_5053_50530201_135_dialog_content = "เว้นแต่คุณจะขุดเธอขึ้นมา",
  ui_story_5053_50530201_136_dialog_content = "สวรรค์... บอกข้าว่าเจ้าทำอะไร น้องชาย!",
  ui_story_5053_50530201_137_dialog_content = "เมื่อท่านถาม... ใช่ ข้าได้ขุดคุ้ยท่านแล้ว",
  ui_story_5053_50530201_138_dialog_content = "เพื่อหลีกเลี่ยงการถูกตรวจจับ ฉันขุดอุโมงค์จากระยะไกลไปยังห้องใต้ดิน ดังนั้นจึงไม่มีใครฉลาดกว่า",
  ui_story_5053_50530201_139_dialog_content = "คุณขุดมันเอง? พูดตามตรง ฉันไม่ได้คาดหวังให้คุณใช้แรงงานได้ขนาดนั้น",
  ui_story_5053_50530201_140_dialog_content = "ฉันยอมทำทุกอย่างเพื่อพี่สาว",
  ui_story_5053_50530201_141_dialog_content = "แต่คุณหลอกแพทย์และเจ้าหน้าที่ชันสูตรศพได้อย่างไร? คุณติดสินบนพวกเขาหรือเปล่า...?",
  ui_story_5053_50530201_142_dialog_content = "ไม่ ฉันเพิ่งใช้ยาบางอย่าง",
  ui_story_5053_50530201_143_dialog_content = "ฉันก็แปลกใจเหมือนกันที่หมอผู้ยิ่งใหญ่ในสวนลุมโปลิสถูกหลอกด้วยกลอุบายเล็กๆ น้อยๆ ของฉัน",
  ui_story_5053_50530201_144_dialog_content = "ไม่น่าแปลกใจที่พวกเขาไม่สามารถรักษาพี่สาวของฉันได้",
  ui_story_5053_50530201_145_dialog_content = "คุณไม่เคยถ่อมตัวขนาดนี้เมื่อคุณโต้เถียงกับผู้สอนใน Dawn Academy, Caleb",
  ui_story_5053_50530201_146_dialog_content = "คุณเป็นอัจฉริยะประเภทที่ Academy พบเจอมาสักศตวรรษ ฉันหวังว่าคุณจะใช้สติปัญญาของคุณกับสิ่งที่ถูกต้อง",
  ui_story_5053_50530201_147_dialog_content = "ทำไมคุณต้องทำตามความตั้งใจของคุณเอง คาเลบ...",
  ui_story_5053_50530201_148_dialog_content = "เพราะคุณไม่เคยต้องการทิ้ง Schwartz และลูก ๆ ในขณะที่เขาทำให้ชีวิตคุณยากขึ้นเรื่อย ๆ",
  ui_story_5053_50530201_149_dialog_content = "ฉันแค่อยากจะปกป้องคุณ",
  ui_story_5053_50530201_150_dialog_content = "ฉันขอโทษที่ทำให้คุณรู้สึกเป็นภาระ",
  ui_story_5053_50530201_151_dialog_content = "ที่เขาเป็นแบบนี้เพราะคุณตามใจเขามาตลอด",
  ui_story_5053_50530201_152_dialog_content = "เราจะกลับมาที่นี่อีกครั้งหลังจากที่เราออกจากที่นี่ Caleb",
  ui_story_5053_50530201_153_dialog_content = "ถ้าเอาชนะ Dark Angel ได้ เราจะออกจากที่นี่ไปชุบชีวิต Mother ได้ไหม?",
  ui_story_5053_50530201_154_dialog_content = "เท่าที่เรารวบรวมมาก็เป็นอย่างนั้น",
  ui_story_5053_50530201_155_dialog_content = "แล้วตอนนี้ร่างกายของ Joshua เป็นอย่างไร? จะทนความตื่นตะลึงของการฟื้นฟูอย่างกระทันหันได้หรือไม่?",
  ui_story_5053_50530201_156_dialog_content = "แน่นอนว่ามันได้รับการอนุรักษ์ไว้อย่างสมบูรณ์แบบ ตั้งแต่เธอโคม่า ฉันใช้เวลาและความพยายามทั้งหมดเพื่อเธอ",
  ui_story_5053_50530201_157_dialog_content = "สำหรับผลลัพธ์นั้น <color=#FFB400>แค่มองมาที่ฉัน</color>.",
  ui_story_5053_50530201_158_dialog_content = "มองคุณ? เพื่ออะไร?",
  ui_story_5053_50530201_159_dialog_content = "คาเลบ แม้ว่าจะเป็นของโยชูวา ฉันก็ห้ามไม่ให้คุณทำการทดลองที่ผิดจริยธรรม",
  ui_story_5053_50530201_160_dialog_content = "สำหรับคุณคืออะไร?",
  ui_story_5053_50530201_161_dialog_content = "เดี๋ยวฉันหลงทาง เกิดอะไรขึ้นที่นี่?",
  ui_story_5053_50530201_162_dialog_content = "คุณคิดว่าฉันอายุเท่าไหร่ ยากิน?",
  ui_story_5053_50530201_163_dialog_content = "ยี่สิบอะไร?",
  ui_story_5053_50530201_164_dialog_content = "ดูสิ่งที่ฉันหมายถึง?",
  ui_story_5053_50530201_165_dialog_content = "เอ่อ ถ้าจำไม่ผิด ลุงน่าจะอายุใกล้ 40 แล้ว...",
  ui_story_5053_50530201_166_dialog_content = "หา—?!",
  ui_story_5053_50530201_167_dialog_content = "อะไร-?!",
  ui_story_5053_50530201_168_dialog_content = "นี่คิดว่าลุงเกิดทันหรือเก่งแค่แต่งหน้า...ไม่คิดว่าจะเป็นผลการทดลอง...",
  ui_story_5053_50530201_169_dialog_content = "ฉันไม่เคยใช้ยาที่ยังไม่ทดลองกับน้องสาวของฉัน",
  ui_story_5053_50530201_170_dialog_content = "ฉันจะไม่ทำร้ายผู้บริสุทธิ์เช่นพวกขุนนางเหล่านั้น ดังนั้นทางเลือกเดียวคือการทดสอบกับตัวฉันเอง",
  ui_story_5053_50530201_171_dialog_content = "โอ้ คาเลบ...",
  ui_story_5053_50530201_172_dialog_content = "สบายดีไหมแม่? คุณดูไม่ค่อยดี...",
  ui_story_5053_50530201_173_dialog_content = "ฉันสบายดี... ฉันชินแล้ว อาจจะ...",
  ui_story_5053_50530201_174_dialog_content = "<size=30>แต่ PlayerName, Caleb ยังทำตัวไม่เป็นผู้ใหญ่เกินไป นั่นหมายความว่างานวิจัยของเขาสามารถทำให้ผู้คนยังเด็กตลอดไป เช่น จิตใจ?</size>",
  ui_story_5053_50530201_175_dialog_content = "ฉันได้ยินแล้ว จาคีน!",
  ui_story_5053_50530201_176_dialog_content = "แม้ว่าร่างกายของเธอจะปกติ แต่ Lumina ในตัวเธอมักจะควบคุมไม่ได้",
  ui_story_5053_50530201_177_dialog_content = "ฉันยังต้องทำการวิจัยเพิ่มเติมเนื่องจากฉันยังไม่พบวิธีแก้ปัญหา",
  ui_story_5053_50530201_178_dialog_content = "ลูมิน่า? นั่นคือเหตุผลที่คุณถามฉันว่า Lumina ของ Lady Joshua อยู่ที่ไหน!",
  ui_story_5053_50530201_179_dialog_content = "อย่างชัดเจน. ความตั้งใจของฉันคือการหา Lumina ที่เหลือของเธอเพื่อทดลองการรักษา",
  ui_story_5053_50530201_180_dialog_content = "แต่ใครจะเดาได้ว่าเธออยู่ในคริสตัลมาตลอด? และนั่นเป็นสาเหตุที่ Lumina ในร่างกายของเธอสูญเสียการควบคุม",
  ui_story_5053_50530201_181_dialog_content = "ทฤษฎีของฉันผิดอย่างสิ้นเชิง ...",
  ui_story_5053_50530201_182_dialog_content = "คุณน่าจะบอกฉันเร็วกว่านี้ คาเลบ",
  ui_story_5053_50530201_183_dialog_content = "บอกคุณแล้ว? คุณจะทรมานเธอต่อไปได้ไหม?",
  ui_story_5053_50530201_184_dialog_content = "จะทะเลาะกันอีกทำไม? อย่าทำแบบนี้ต่อหน้าคนอื่น",
  ui_story_5053_50530201_185_dialog_content = "ขอโทษนะพี่สาว",
  ui_story_5053_50530201_186_dialog_content = "เนื่องจากร่างกายของเธอยังอยู่ในสภาพดี เราควรนำเธอออกมาให้เร็วที่สุด",
  ui_story_5053_50530201_187_dialog_content = "กลับมาที่หัวข้อและค้นหาว่าจะทำอย่างไรกับ Dark Angel",
  ui_story_5053_50530201_188_dialog_content = "ใช่ มาทำกันเถอะ",
  ui_story_5053_50530201_189_dialog_content = "ฉันไม่สามารถเอาชนะมันได้ด้วยตัวเอง",
  ui_story_5053_50530201_190_dialog_content = "เพราะเราแบ่งปัน <color=#FFB400>ร่างกายเดียวกันและมีชีวิตเดียว</color>มีเพียงบุคคลที่สามเท่านั้นที่สามารถทำลายมันได้",
  ui_story_5053_50530201_191_dialog_content = "แต่คุณต้องระวังเพราะมันตามล่าคุณเช่นกัน",
  ui_story_5053_50530201_192_dialog_content = "ตามล่าเรา?",
  ui_story_5053_50530201_193_dialog_content = "ใช่. มันเริ่มเบื่อหน่ายกับความขัดแย้งของเราและต้องการเป็นอิสระโดยเอาร่างกายของฉันไปเป็นของตัวเอง",
  ui_story_5053_50530201_194_dialog_content = "คงจะเป็นไปได้ยากมากในโลกแห่งความเป็นจริง",
  ui_story_5053_50530201_195_dialog_content = "แต่ในส่วนของฉันที่เปิดใช้งาน Crystal of Eternal Memory นั้นสามารถทำได้ <color=#FFB400>ฆ่าสิ่งมีชีวิตอื่น ๆ ทั้งหมดเพื่อให้ Lumina สมบูรณ์</color> ที่นี่.",
  ui_story_5053_50530201_196_dialog_content = "จริงเหรอ จาคีน?",
  ui_story_5053_50530201_197_dialog_content = "ใช่. อาจฟังดูไร้สาระ แต่เป็นไปได้ในคริสตัล",
  ui_story_5053_50530201_198_dialog_content = "Crystal อาจดูเหมือนอุปกรณ์เล่นหน่วยความจำ แต่หลักการเบื้องหลังนั้นลึกซึ้งกว่านั้น",
  ui_story_5053_50530201_199_dialog_content = "นั่นเป็นเหตุผลที่แม่สร้างเพียงอันเดียวตามคำสั่งของราชินี จากนั้นก็ซ่อนทุกอย่างเกี่ยวกับมันหลังจากนั้น...",
  ui_story_5053_50530201_200_dialog_content = "ดังนั้น โดยพื้นฐานแล้ว มีสองผลลัพธ์ที่เป็นไปได้",
  ui_story_5053_50530201_201_dialog_content = "หนึ่งคือเราทำลาย Dark Angel และนำ Lady Joshua ออกไปจากที่นี่",
  ui_story_5053_50530201_202_dialog_content = "อีกอันคือ Dark Angel ฆ่าเราและปล่อยให้หลุดเข้าไปในโลกแห่งความจริง?",
  ui_story_5053_50530201_203_dialog_content = "ถูกต้อง. ช่างเป็นเด็กที่ยอดเยี่ยม คุณ PlayerName, ขวา?",
  ui_story_5053_50530201_204_dialog_content = "ใช่. ยังไงก็ตาม คุณรู้จักชื่อของฉันและของจาคีน และชื่อมีอาก็ไม่ทำให้คุณประหลาดใจ",
  ui_story_5053_50530201_205_dialog_content = "คุณมีความทรงจำก่อนการรีเซ็ตด้วยหรือไม่?",
  ui_story_5053_50530201_206_dialog_content = "ใช่ตั้งแต่ <color=#FFB400>ฉันอยู่กับคุณ</color> เมื่อมันเกิดขึ้น.",
  ui_story_5053_50530201_207_dialog_content = "และไม่อยากห่างจากครอบครัวอีกแล้ว...",
  ui_story_5053_50530201_208_dialog_content = "ฉันสาบานว่าฉันจะทำลาย Dark Angel และพาคุณออกไปจากที่นี่ ไม่ต้องห่วง",
  ui_story_5053_50530201_209_dialog_content = "ฉันด้วย...! ฉันจะปลดปล่อยคุณออกจากที่นี่!",
  ui_story_5053_50530201_210_dialog_content = "แท้จริงข้าพเจ้ามีศรัทธาต่อท่านทั้งหลาย",
  ui_story_5053_50530201_211_dialog_content = "The Dark Angel ขาดทักษะการใช้เหตุผล แต่มันก็คดเคี้ยว",
  ui_story_5053_50530201_212_dialog_content = "เราต้องการเหยื่อเพื่อดึงมันออกมา",
  ui_story_5053_50530201_213_dialog_content = "ไม่เป็นไรแดเนียล?",
  ui_story_5053_50530201_214_dialog_content = "ไม่มีปัญหา. เป็นการดีที่สุดที่ฉันจะมีบทบาทที่สำคัญและอันตรายอยู่ดี",
  ui_story_5053_50530201_215_dialog_content = "แต่ฉันจะล่อมันให้ฉันได้อย่างไร",
  ui_story_5053_50530201_216_dialog_content = "คุณไม่ต้องทำอะไร เพราะสัตว์ประหลาดตัวนั้น... <color=#FFB400>ค่อนข้างเกลียดคุณ</color>.",
  ui_story_5053_50530201_217_dialog_content = "ถ้าคุณไม่เข้มแข็งพอที่จะขับไล่มันออกไป มันคงจะฉีกคุณเป็นชิ้นๆ",
  ui_story_5053_50530201_218_dialog_content = "นั่นก็ใช้กับเด็ก ๆ ในโลกนี้เช่นกัน มีแนวโน้มที่จะโจมตีเขาในงานฉลอง",
  ui_story_5053_50530201_219_dialog_content = "แม้ว่าการฆ่าภาพลวงตาจะไม่ช่วยอะไร แต่มันก็ไม่สามารถต้านทานได้",
  ui_story_5053_50530201_220_dialog_content = "ฉันเห็น. ในกรณีนั้น ฉันแค่ต้องตามหาตัวฉันที่ยังเด็กและรอให้มันปรากฏตัว",
  ui_story_5053_50530201_221_dialog_content = "เดี๋ยวนะ นั่นมันจะไม่อันตรายเหรอพ่อ? เกิดอะไรขึ้นถ้าคุณได้รับบาดเจ็บ?",
  ui_story_5053_50530201_222_dialog_content = "คุณเป็นห่วงครอบครัวของเราเสมอ วอนนี่",
  ui_story_5053_50530201_223_dialog_content = "แต่สถานการณ์ปัจจุบันของเราเป็นเรื่องเร่งด่วนและเราต้องให้ความสำคัญกับลำดับความสำคัญของเรา",
  ui_story_5053_50530201_224_dialog_content = "เชื่อพ่อดีไหม",
  ui_story_5053_50530201_225_dialog_content = "ก็ได้...",
  ui_story_5053_50530201_226_dialog_content = "หลังจากขบวนพาเหรดควรเป็นพิธีเปิดที่จัตุรัส",
  ui_story_5053_50530201_227_dialog_content = "เราควรเดิมพันที่นั่นหรือไม่?",
  ui_story_5053_50530201_228_dialog_content = "เป็นความคิดที่ดี แต่คุณต้องอยู่กับฉัน จาคีน",
  ui_story_5053_50530201_229_dialog_content = "ทำไม อย่าดูถูกฉัน ฉันเป็นนักสู้ที่ดีกว่า PlayerName!",
  ui_story_5053_50530201_230_dialog_content = "อะแฮ่ม...",
  ui_story_5053_50530201_231_dialog_content = "ใช่ ฉันรู้ แต่คุณเป็นคนควบคุมคริสตัล",
  ui_story_5053_50530201_232_dialog_content = "ถ้าคนอื่นบาดเจ็บเราย้อนเวลาคืนทุกอย่างได้เสมอ",
  ui_story_5053_50530201_233_dialog_content = "แต่ถ้ามีอะไรเกิดขึ้นกับคุณ",
  ui_story_5053_50530201_234_dialog_content = "ย-คุณพูดถูก...",
  ui_story_5053_50530201_235_dialog_content = "ดังนั้นเราจึงมี City Lord เป็นเหยื่อล่อ มีอา PlayerName และฉันจะมุ่งหน้าไปที่จัตุรัสด้วยกันเพื่อหยุด Dark Angel",
  ui_story_5053_50530201_236_dialog_content = "Jakine และน้องสาวของฉันจะอยู่ที่นี่เพื่อรอข่าวดี",
  ui_story_5053_50530201_237_dialog_content = "ดูแลเธอให้ดี จาคีน",
  ui_story_5053_50530201_238_dialog_content = "ฉันเข้าใจแล้ว! ทำไมทุกคนสงสัยฉัน...",
  ui_story_5053_50530201_239_dialog_content = "ฉันประหลาดใจ คาเลบ ฉันคิดว่าคุณจะยืนกรานที่จะอยู่กับน้องสาวของคุณ",
  ui_story_5053_50530201_240_dialog_content = "การฆ่า Dark Angel และพาน้องสาวของฉันออกไปจากที่นี่คือสิ่งสำคัญที่สุดในตอนนี้ คุณคิดว่าฉันไม่เข้าใจ?",
  ui_story_5053_50530201_241_dialog_content = "อืม เราควรไปกัน",
  ui_story_5053_50530201_242_dialog_content = "ใช่ ไปกันเถอะ!",
  ui_story_5053_50530201_243_dialog_content = "หยุดผลักไสฉัน พวกเธอสองคน",
  ui_story_5053_50530201_244_dialog_content = "เดินทางปลอดภัย!",
  ui_story_5053_50530201_245_dialog_content = "ฉันจะไม่แพ้คุณอีก โจชัว ฉันสัญญา",
  ui_story_5053_50530201_246_dialog_content = "ใช่ ฉันเชื่อคุณ",
  ui_story_5053_50530201_247_dialog_content = "คุณจะไม่",
  ui_story_5053_50530301_1_dialog_content = "ขบวนพาเหรดสิ้นสุดลงแล้วและการเฉลิมฉลองจะเริ่มขึ้นในไม่ช้า",
  ui_story_5053_50530301_2_dialog_content = "ยังมีจุดที่ดีให้ดูหรือไม่?",
  ui_story_5053_50530301_3_dialog_content = "รีบไปดูกันเลย!",
  ui_story_5053_50530301_4_dialog_content = "มีอะไรให้ดูบ้าง? ทั้งหมดเป็นเพียงเรื่องตลก",
  ui_story_5053_50530301_5_dialog_content = "คนแน่นทุกที่ เราจะมองเห็น Dark Angel ได้อย่างไรเมื่อเรามองไม่เห็น?",
  ui_story_5053_50530301_6_dialog_content = "เข้าใกล้ขาตั้งและรอ",
  ui_story_5053_50530301_7_dialog_content = "เนื่องจากคุณทั้งคู่สามารถล่อ Dark Angel มาหาเราได้ เราจะไม่มีโอกาสที่ดีกว่านี้ไหมถ้าคุณทั้งคู่ขึ้นไปที่นั่น",
  ui_story_5053_50530301_8_dialog_content = "ฉันว่าฉันไปดีกว่า เพราะคนที่นี่ยังจำฉันได้",
  ui_story_5053_50530301_9_dialog_content = "ถ้าพ่อไปคงวุ่นวายเกินเหตุ...",
  ui_story_5053_50530301_10_dialog_content = "จริง. แต่ถ้าแองเจิ้ลโจมตีแสตนด์ คุณจะสู้กับมันคนเดียวได้ไหม มีอา?",
  ui_story_5053_50530301_11_dialog_content = "ฉัน... ฉันไม่ได้อยู่คนเดียว",
  ui_story_5053_50530301_12_dialog_content = "พ่อในโลกนี้จะช่วยฉันด้วย",
  ui_story_5053_50530301_13_dialog_content = "ไม่ต้องพูดถึง ฉันจะมีมุมมองที่ดีกว่าบนนั้น ฉันสามารถถ่ายทอดตำแหน่งของทูตสวรรค์ให้คุณเมื่อฉันเห็นมัน...",
  ui_story_5053_50530301_14_dialog_content = "อืม... ฉันจะย้ายไปในที่ที่ทุกคนมองเห็นฉันและส่งสัญญาณ!",
  ui_story_5053_50530301_15_dialog_content = "ขออภัย ท่านพ่อ... บางทีความคิดข้าอาจไร้เดียงสาเกินไป?",
  ui_story_5053_50530301_16_dialog_content = "คุณครอบคลุมทุกอย่าง เราจะดำเนินการตามที่คุณแนะนำ",
  ui_story_5053_50530301_17_dialog_content = "โอ๊ะ? จริงเหรอ?",
  ui_story_5053_50530301_18_dialog_content = "ขอบคุณพ่อ ฉันจะออกไปแล้ว แค่รอสัญญาณของฉัน!",
  ui_story_5053_50530301_19_dialog_content = "เพียงหนึ่งวัน Mia ก็กล้าหาญและเป็นอิสระมากแล้ว เป็นเรื่องดีที่ได้เห็น",
  ui_story_5053_50530301_20_dialog_content = "บัดนี้ไม่ใช่เวลามาสรรเสริญ PlayerName. จับตาดูปีศาจที่ทำลายน้องสาวของฉัน!",
  ui_story_5053_50530301_21_dialog_content = "ใช่ ฉันจะไปทันที!",
  ui_story_5053_50530301_22_dialog_content = "การเฉลิมฉลองจะเริ่มขึ้นเร็วๆ นี้ คาร์ลีน กลับไปที่ที่นั่งของคุณ",
  ui_story_5053_50530301_23_dialog_content = "ใช่ค่ะ ท่านพ่อ",
  ui_story_5053_50530301_24_dialog_content = "พ่อคาร์ลีน",
  ui_story_5053_50530301_25_dialog_content = "เวโรนิก้า?! พ่อ เวโรนิก้ามาแล้ว!",
  ui_story_5053_50530301_26_dialog_content = "เวโรนิก้า? คุณมาทำอะไรที่นี่?",
  ui_story_5053_50530301_27_dialog_content = "M-แม่บอกให้ฉันกลับบ้านเพื่อฉลองวันครอบครัว",
  ui_story_5053_50530301_28_dialog_content = "คุณเห็นแม่ของคุณ?",
  ui_story_5053_50530301_29_dialog_content = "ใช่... เธอรู้สึกไม่ค่อยสบายแต่บอกว่าเราไม่ควรกังวล",
  ui_story_5053_50530301_30_dialog_content = "นี่เจ้าหญิงเวโรนิกาไม่ใช่เหรอ มันเป็นเวลานาน. เป็นอย่างไรบ้าง",
  ui_story_5053_50530301_31_dialog_content = "เจ้าหญิงเวโรนิกาเข้าร่วมอัศวินและติดตามพวกเขาไปที่อัมบราตันไม่ใช่หรือ",
  ui_story_5053_50530301_32_dialog_content = "ฉันอยากกลับมาฉลองก็เลยขอเวลานอก",
  ui_story_5053_50530301_33_dialog_content = "ฉันเห็น. และคุณควรจะเป็นวันครอบครัวชวาร์ตษ์",
  ui_story_5053_50530301_34_dialog_content = "น่าเสียดายที่ครอบครัวของฉันยังคงประจำการอยู่ที่ Umbraton และไม่มีสิทธิพิเศษ",
  ui_story_5053_50530301_35_dialog_content = "Veronica เป็นสมาชิกของ House Schwartz ดังนั้นจึงเป็นสิทธิ์ของเธอที่จะกลับมาในวันครอบครัวของเรา!",
  ui_story_5053_50530301_36_dialog_content = "เงียบไว้ คาร์ลีน และทำความเคารพดยุคเฮอร์มีส",
  ui_story_5053_50530301_37_dialog_content = "อย่าโทษคาร์ลีนเลย พ่อ ฉันกลับมาโดยไม่บอกกล่าว",
  ui_story_5053_50530301_38_dialog_content = "และเนื่องจาก Duke Hermes อยู่ที่นี่ Mrs. Hermes เป็นอย่างไรบ้าง?",
  ui_story_5053_50530301_39_dialog_content = "เธอทำได้ดีเช่นเคย",
  ui_story_5053_50530301_40_dialog_content = "ฉันเป็นห่วงมาก เพราะหลานชายของคุณลางานอยู่เสมอ และบอกว่าคุณนายเฮอร์มีสสุขภาพไม่ดี",
  ui_story_5053_50530301_41_dialog_content = "เป็นการดีที่รู้ว่าเธอสบายดี",
  ui_story_5053_50530301_42_dialog_content = "... ค่ะ ขอบคุณสำหรับความนับถือค่ะ ฝ่าบาท",
  ui_story_5053_50530301_43_dialog_content = "คุณควรหาเวลาอยู่กับครอบครัวบ้างเป็นครั้งคราว Duke Hermes",
  ui_story_5053_50530301_44_dialog_content = "เจ้าหญิงเวโรนิกาครบกำหนดแล้ว อัศวินต้องฝึกฝนเธอมาอย่างดี",
  ui_story_5053_50530301_45_dialog_content = "บางที แต่ฉันหวังว่ามันจะไม่ไปที่หัวของเธอ",
  ui_story_5053_50530301_46_dialog_content = "โอ้ ท่านชวาร์ตษ์ ท่านไม่ต้องเข้มงวดกับเจ้าหญิงเวโรนิกาเท่านั้น",
  ui_story_5053_50530301_47_dialog_content = "ขอบคุณ ดยุคทรอย พ่อพูดถูก ฉันต้องถ่อมตัวและเรียนรู้ต่อไป",
  ui_story_5053_50530301_48_dialog_content = "ฉันเข้าใจแล้ว เจ้าหญิงเวโรนิก้า... เธอเติบโตมากับการทำงานร่วมกับอัศวินจริงๆ",
  ui_story_5053_50530301_49_dialog_content = "การเฉลิมฉลองกำลังเริ่มต้นขึ้น กรุณานั่งลงทุกท่าน",
  ui_story_5053_50530301_50_dialog_content = "คุณเจ๋งมาก เวโรนิก้า! บรรดาขุนนางจากสภาผู้อาวุโสไม่ได้ทำให้คุณกลัวเลย!",
  ui_story_5053_50530301_51_dialog_content = "คุณคิดเหมือนกันใช่ไหม? ฉันรู้สึกประหม่า พูดตามตรง...",
  ui_story_5053_50530301_52_dialog_content = "คุณกล้าเหมือนกัน คาร์ลีน ร่วมขบวนพาเหรดกับคุณพ่อด้วยตัวคนเดียว",
  ui_story_5053_50530301_53_dialog_content = "ไม่ ฉันก็ไม่อยากห่างจากแม่เหมือนกัน...",
  ui_story_5053_50530301_54_dialog_content = "พอขึ้นรถ พ่อบอกว่าแม่ไม่ค่อยสบายอยากให้ไปฉลองคนเดียว...",
  ui_story_5053_50530301_55_dialog_content = "(ฉันเข้าใจแล้ว แม่ใช้ความเจ็บป่วยเป็นข้ออ้างในการพาคาร์ลีนและพ่อออกไปเพื่อที่เธอจะได้เห็นเรา)",
  ui_story_5053_50530301_56_dialog_content = "(นั่นต้องทำร้ายความรู้สึกของ Carleen เล็กน้อย แต่อย่างน้อยก็ไม่มีอะไรที่เป็นความจริง)",
  ui_story_5053_50530301_57_dialog_content = "(ลำดับความสำคัญ ลำดับความสำคัญ... ไม่ ฉันทำไม่ได้)",
  ui_story_5053_50530301_58_dialog_content = "เราจะกลับไปหาแม่ไหม คาร์ลีน?",
  ui_story_5053_50530301_59_dialog_content = "เราสามารถ? มันจะไม่รบกวนเธอเหรอ?",
  ui_story_5053_50530301_60_dialog_content = "แน่นอนมันจะไม่ แม่รักคุณและจะดีขึ้นเมื่ออยู่กับคุณ",
  ui_story_5053_50530301_61_dialog_content = "ฉันรักแม่และคุณด้วย! และพ่อ!",
  ui_story_5053_50530301_62_dialog_content = "ฉันจะเอาผลไม้ของเธอไปบอกเธอเกี่ยวกับขบวนพาเหรดเมื่อเรากลับมา!",
  ui_story_5053_50530301_63_dialog_content = "ฮี่ฮี่ สาวน้อยผู้แสนดี",
  ui_story_5053_50530301_64_dialog_content = "(มันยอดเยี่ยมมากที่ได้เห็น Carleen ร่าเริงอีกครั้ง)",
  ui_story_5053_50530301_65_dialog_content = "คุณเห็นอะไร?",
  ui_story_5053_50530301_66_dialog_content = "มีอาอยู่บนนั้น แต่ตอนนี้ฉันไม่เห็นเธอ... แม้ว่า Young Schwartz จะพร้อมที่จะพูด",
  ui_story_5053_50530301_67_dialog_content = "ยังไม่มีการมองเห็นของ Dark Angel",
  ui_story_5053_50530301_68_dialog_content = "เราแทบจะมองไม่เห็นจากที่นี่ เราควรจะลองจุดอื่น",
  ui_story_5053_50530301_69_dialog_content = "<color=#e8d9bb>แตก! แตก!</color>",
  ui_story_5053_50530301_70_dialog_content = "เสียงนั่น...",
  ui_story_5053_50530301_71_dialog_content = "ฉันไม่คิดว่าเราต้องไปลองที่อื่น คาเลบ",
  ui_story_5053_50530301_72_dialog_content = "เป็ด คุณสองคน!",
  ui_story_5053_50530301_73_dialog_content = "โน่น...นี่!",
  ui_story_5053_50530302_1_dialog_content = "ฉันขอประกาศการเริ่มต้นการเฉลิมฉลองวันครอบครัวชวาร์ตษ์!",
  ui_story_5053_50530302_2_dialog_content = "เอาล่ะ พิธีประลองเริ่มต้นขึ้น!",
  ui_story_5053_50530302_3_dialog_content = "(ทำไมยังไม่โชว์...)",
  ui_story_5053_50530302_4_dialog_content = "(พวกเขาควรจะอยู่ที่นั่น แต่ฉันไม่เห็นพวกเขาเลย...)",
  ui_story_5053_50530302_5_dialog_content = "(อย่าบอกนะว่า Dark Angel ติดตามอยู่แล้ว PlayerName และอื่น ๆ ลง?)",
  ui_story_5053_50530302_6_dialog_content = "(ฉันควรหาข้ออ้างแล้วจากไปดีไหม)",
  ui_story_5053_50530302_7_dialog_content = "คุณกำลังหาอะไรอยู่ วอนนี่?",
  ui_story_5053_50530302_8_dialog_content = "ไม่นะ คาร์ลีน... ดูสิ การประลองเริ่มขึ้นแล้ว ฟังดูเหมือนเป็นเรื่องน่าตื่นเต้น",
  ui_story_5053_50530302_9_dialog_content = "เมื่อไหร่พวกเขาจะให้ฉันเข้าร่วม ... ฉันเก่งพอ ๆ กับพวกเขา",
  ui_story_5053_50530302_10_dialog_content = "น่าแปลกที่นักดวลสองคนหยุด...",
  ui_story_5053_50530302_11_dialog_content = "และกำลังเดินมาทางเรา...",
  ui_story_5053_50530302_12_dialog_content = "เราได้โบนัสโชว์หรืออะไรไหม?",
  ui_story_5053_50530302_13_dialog_content = "ว่าไง",
  ui_story_5053_50530302_14_dialog_content = "(พ่องงเหมือนไม่รู้ว่าเกิดอะไรขึ้น)",
  ui_story_5053_50530302_15_dialog_content = "(ตอนนั้นฉันไม่ได้อยู่ที่นี่ ฉันเลยไม่รู้ว่าอะไรจะเกิดขึ้นตอนนี้ แต่รู้สึกว่ามันไม่ถูกต้อง)",
  ui_story_5053_50530302_16_dialog_content = "...",
  ui_story_5053_50530302_17_dialog_content = "(อาจจะเป็น...?!)",
  ui_story_5053_50530302_18_dialog_content = "พ่อ การลอบสังหารเดินหน้าแล้ว!",
  ui_story_5053_50530302_19_dialog_content = "คุณรู้เรื่องนั้นได้อย่างไร? แล้วมัน... สะเทือนใจ?",
  ui_story_5053_50530302_20_dialog_content = "เรื่องมันยาวน่ะครับ...",
  ui_story_5053_50530302_21_dialog_content = "คุณมาทำอะไรที่นี่? นี่ไม่ใช่ที่สำหรับคุณ!",
  ui_story_5053_50530302_22_dialog_content = "...",
  ui_story_5053_50530302_23_dialog_content = "คุณอวดดีแค่ไหนที่ไม่ตอบโต้ฉัน!",
  ui_story_5053_50530302_24_dialog_content = "พวกเขาไม่ได้มาอย่างสันติ... ถอยกลับ ดยุคเฮอร์มีส!",
  ui_story_5053_50530302_25_dialog_content = "รักษาคาร์ลีนให้ปลอดภัย เวโรนิก้า!",
  ui_story_5053_50530302_26_dialog_content = "ระวังพ่อ!",
  ui_story_5053_50530302_27_dialog_content = "ฮ่า!",
  ui_story_5053_50530302_28_dialog_content = "หมดมุกแล้วสินะ",
  ui_story_5053_50530302_29_dialog_content = "ฟันดาบของอธิปไตย!",
  ui_story_5053_50530302_30_dialog_content = "โอย...",
  ui_story_5053_50530302_31_dialog_content = "คุณต้องการที่จะลองโชคของคุณเช่นกัน?",
  ui_story_5053_50530302_32_dialog_content = "ฮ่า!",
  ui_story_5053_50530302_33_dialog_content = "เอานี่ไปกินนี่ซะ!",
  ui_story_5053_50530302_34_dialog_content = "โอย...",
  ui_story_5053_50530302_35_dialog_content = "คุณรอดจากดาบของฉัน? บอกฉันทีว่าใครส่งคุณมา?",
  ui_story_5053_50530302_36_dialog_content = "เดี๋ยวนะ—",
  ui_story_5053_50530302_37_dialog_content = "มันสายเกินไปที่จะร้องขอความเมตตาในตอนนี้!",
  ui_story_5053_50530302_38_dialog_content = "เวโรนิก้า ทำไมพ่อถึงกระซิบกับคนเลว?",
  ui_story_5053_50530302_39_dialog_content = "ไม่ ฉันไม่คิดว่าพ่อเป็นคนขู่เขา... เขาจับพ่อด้วยอาวุธของเขา",
  ui_story_5053_50530302_40_dialog_content = "<color=#e8d9bb>เพล้ง!</color>",
  ui_story_5053_50530302_41_dialog_content = "หา?",
  ui_story_5053_50530302_42_dialog_content = "ฮะ...ฮะ! เร็วๆ นี้...",
  ui_story_5053_50530302_43_dialog_content = "ทำไมหน้าเขาบิดเบี้ยวจัง",
  ui_story_5053_50530302_44_dialog_content = "แล้วทำไมเขาถึงหัวเราะเมื่อเขาได้รับบาดเจ็บ? เกิดอะไรขึ้น...",
  ui_story_5053_50530302_45_dialog_content = "นี่มัน... นี่มันพลังอะไรกันเนี่ย? <color=#FFB400>ฉันไม่สามารถปลดปล่อยอาวุธของฉันได้</color>!",
  ui_story_5053_50530302_46_dialog_content = "ในกรณีนี้ Sovereign's...",
  ui_story_5053_50530302_47_dialog_content = "มาแล้วค่ะ...",
  ui_story_5053_50530302_48_dialog_content = "เงยหน้าขึ้นพ่อ! ท้องฟ้า!",
  ui_story_5053_50530302_49_dialog_content = "<size=45><color=#e8d9bb>คำราม—!</color></size>",
  ui_story_5053_50530302_50_dialog_content = "ว่าไง",
  ui_story_5053_50530302_51_dialog_content = "T-ลมแรงเกินไป! มันจะพัดฉันออกไป!",
  ui_story_5053_50530302_52_dialog_content = "ฉันอยู่นี่ คาร์ลีน!",
  ui_story_5053_50530302_53_dialog_content = "มังกร...ก <color=#FFB400>มังกร</color>? พวก Kartimas... พวกมันจะทำลายแสตนด์ด้วยเหรอ?!",
  ui_story_5053_50530302_54_dialog_content = "<size=45><color=#e8d9bb>คำราม—!</color></size>",
  ui_story_5053_50530302_55_dialog_content = "คาร์ลีน เวโรนิก้า!",
  ui_story_5053_50530302_56_dialog_content = "วิ่งเร็ว!",
  ui_story_5053_50530302_57_dialog_content = "<size=45><color=#e8d9bb>บูม—!!!</color></size>",
  ui_story_5053_50530401_1_dialog_content = "อ๊ากก!",
  ui_story_5053_50530401_2_dialog_content = "คุณแย่กว่าที่คุณเห็น!",
  ui_story_5053_50530401_3_dialog_content = "แค่ Seed กล้าดียังไงมาหลอกฉันโดยเลียนเสียงน้องสาวฉัน...",
  ui_story_5053_50530401_4_dialog_content = "ฉันจะให้เธอชดใช้ความทุกข์ทรมานของเธอด้วยเลือด!",
  ui_story_5053_50530401_5_dialog_content = "ฮ่า!",
  ui_story_5053_50530401_6_dialog_content = "...",
  ui_story_5053_50530401_7_dialog_content = "อย่าใจร้อน คาเลบ!",
  ui_story_5053_50530401_8_dialog_content = "ถึงเวลาตายแล้ว!",
  ui_story_5053_50530401_9_dialog_content = "อ๊ากก!",
  ui_story_5053_50530401_10_dialog_content = "อะไรนะ!",
  ui_story_5053_50530401_11_dialog_content = "คาเลบ!!!",
  ui_story_5053_50530401_12_dialog_content = "กะ...เลบ...?",
  ui_story_5053_50530401_13_dialog_content = "อย่าให้ชื่อของฉันปิดปากคุณ...",
  ui_story_5053_50530401_14_dialog_content = "จังหวะนี้แหละ!",
  ui_story_5053_50530401_15_dialog_content = "ฉันจะเขย่าดาวทุกดวง—!!!",
  ui_story_5053_50530401_16_dialog_content = "อัก!!!",
  ui_story_5053_50530401_17_dialog_content = "ช...วอร์ทซ์...",
  ui_story_5053_50530401_18_dialog_content = "ช...",
  ui_story_5053_50530401_19_dialog_content = "ทุกอย่างดูเหมือนจะกลับมาเป็นปกติ?",
  ui_story_5053_50530401_20_dialog_content = "หายแล้ว...แปลว่าตาย?",
  ui_story_5053_50530401_21_dialog_content = "ไม่ มีบางอย่างผิดปกติ ดูนั่นสิ",
  ui_story_5053_50530401_22_dialog_content = "อ๊าก—!",
  ui_story_5053_50530401_23_dialog_content = "รีบหนีไป!!!",
  ui_story_5053_50530401_24_dialog_content = "ฝูงชนกำลังหนีออกจากจัตุรัส ... การก่อจลาจลเริ่มต้นขึ้นหรือไม่?",
  ui_story_5053_50530401_25_dialog_content = "ไม่สามารถเป็นได้ หากปราศจากการแทรกแซงของเรา มันคงจะเริ่มต้นขึ้นหลังจากการลอบสังหาร...",
  ui_story_5053_50530401_26_dialog_content = "เปล่านะ...",
  ui_story_5053_50530401_27_dialog_content = "มองขึ้นไปบนท้องฟ้า!",
  ui_story_5053_50530401_28_dialog_content = "คำราม—!",
  ui_story_5053_50530401_29_dialog_content = "มังกรคาร์ติมา?!",
  ui_story_5053_50530401_30_dialog_content = "มันทำอะไรในเมือง?",
  ui_story_5053_50530401_31_dialog_content = "โอ้สวรรค์ นี่มันกำลังทำอะไรอยู่ในลูโมโปลิส...?",
  ui_story_5053_50530401_32_dialog_content = "ยามเช่นนี้ไม่ควรคุ้มกันหรือ? คุณกำลังรออะไรอยู่?",
  ui_story_5053_50530401_33_dialog_content = "...",
  ui_story_5053_50530401_34_dialog_content = "H-เฮ้ คุณกำลังทำอะไรอยู่?",
  ui_story_5053_50530401_35_dialog_content = "ฆ่า...ฆ่า...ฆ่า...",
  ui_story_5053_50530401_36_dialog_content = "อ๊าาา—!",
  ui_story_5053_50530401_37_dialog_content = "ดาบแห่งราชัน!",
  ui_story_5053_50530401_38_dialog_content = "คุณเป็นอัศวินประเภทไหนที่ทำร้ายคนที่ไร้ทางสู้? นี่เป็นระดับที่ Kartimas ก้มลงมาหรือไม่?",
  ui_story_5053_50530401_39_dialog_content = "โอ๊ะ...",
  ui_story_5053_50530401_40_dialog_content = "T-คนนี้ยังมีชีวิตอยู่!",
  ui_story_5053_50530401_41_dialog_content = "ฆ่า...",
  ui_story_5053_50530401_42_dialog_content = "ฆ่า? คุณกำลังพูดอะไร?",
  ui_story_5053_50530401_43_dialog_content = "ช...วอร์ทซ์...",
  ui_story_5053_50530401_44_dialog_content = "ฆ่า... ฆ่า... ฆ่าผู้บุกรุก!",
  ui_story_5053_50530401_45_dialog_content = "ออกจากทาง, PlayerName!",
  ui_story_5053_50530401_46_dialog_content = "ทำไมเธอเป็นอะไรไป...?",
  ui_story_5053_50530401_47_dialog_content = "<color=#e8d9bb><size=45>ตูม!</size></color>",
  ui_story_5053_50530401_48_dialog_content = "คลื่นกระแทกที่ทรงพลังเช่นนี้ อะไรตอนนี้?",
  ui_story_5053_50530401_49_dialog_content = "เสียงระเบิดดังมาจากแสตนด์!",
  ui_story_5053_50530401_50_dialog_content = "City Lord ถูกโจมตี!",
  ui_story_5053_50530401_51_dialog_content = "วิ่งเพื่อชีวิตของคุณ!",
  ui_story_5053_50530401_52_dialog_content = "ถูกโจมตี? เมีย...!",
  ui_story_5053_50530401_53_dialog_content = "ถ้า Mia ยังยืนหยัดอยู่... ไม่สิ เป็นไปไม่ได้...",
  ui_story_5053_50530401_54_dialog_content = "พี่สาวของฉันยังอยู่ที่คฤหาสน์ชวาร์ตซ์ หากพวกกบฏพบเธอ...",
  ui_story_5053_50530401_55_dialog_content = "PlayerNameออกไปกับ Caleb!",
  ui_story_5053_50530401_56_dialog_content = "ถ้าฉันไม่กลับพร้อมมีอา บอกให้ Jakine ถอยหลังทันที!",
  ui_story_5053_50530401_57_dialog_content = "ท่านชวาร์ตษ์!!!",
  ui_story_5053_50530401_58_dialog_content = "(เกิดอะไรขึ้น คริสตัลแห่งความทรงจำชั่วนิรันดร์แตกหรือเปล่า)",
  ui_story_5053_50530401_59_dialog_content = "(หรือบางที Dark Angel ยังมีชีวิตอยู่และนี่คือทั้งหมดที่เธอทำ...?)",
  ui_story_5053_50530401_60_dialog_content = "อย่ายืนอยู่ตรงนั้น! เราต้องออกไปจากที่นี่!",
  ui_story_5053_50530401_61_dialog_content = "ฆ่า...ฆ่า...ฆ่า...",
  ui_story_5053_50530402_1_dialog_content = "ฮ่า!",
  ui_story_5053_50530402_2_dialog_content = "โอย...",
  ui_story_5053_50530402_3_dialog_content = "ให้ตายเถอะพวกกบฏ... ขอบคุณสำหรับความช่วยเหลือ ชายชรา",
  ui_story_5053_50530402_4_dialog_content = "ไฮโซอยู่ไหน?",
  ui_story_5053_50530402_5_dialog_content = "ฝ่าบาท? คุณควรจะคิดเกี่ยวกับการทำให้ตัวเองมีชีวิตอยู่",
  ui_story_5053_50530402_6_dialog_content = "คุณหมายถึงอะไร?",
  ui_story_5053_50530402_7_dialog_content = "เจ้าหญิงคาร์ลีน เจ้าหญิงเวโรนิกา และเจ้าเมืองถูกมังกรโจมตี... <color=#FFB400>พวกเขาตายแล้ว</color>!",
  ui_story_5053_50530402_8_dialog_content = "ที่ไหน? เจ้าหญิงเวโรนิกาอยู่ที่ไหน!",
  ui_story_5053_50530402_9_dialog_content = "ยังยืนอยู่ที่เดิม อย่าบอกนะว่าจะไปเก็บซากพวกมันในเวลาแบบนี้?",
  ui_story_5053_50530402_10_dialog_content = "ขอบคุณครับ",
  ui_story_5053_50530402_11_dialog_content = "คนโง่... การยึดติดกับสิ่งที่คุณสูญเสียไปแล้วมีแต่จะทำให้คุณเสียชีวิต",
  ui_story_5053_50530402_12_dialog_content = "โจชัว!",
  ui_story_5053_50530402_13_dialog_content = "เลดี้โจชัว! จากิน! คุณอยู่ที่ไหน",
  ui_story_5053_50530402_14_dialog_content = "ทำไมพวกเขาถึงไม่ตอบสนอง... โจชัว!",
  ui_story_5053_50530402_15_dialog_content = "ฉันอยู่นี่ คาเลบ",
  ui_story_5053_50530402_16_dialog_content = "ขอบคุณพระเจ้า คุณไม่เป็นไร! ฉันคิดว่าฉันจะสูญเสียคุณไปอีกครั้ง...",
  ui_story_5053_50530402_17_dialog_content = "การก่อความไม่สงบถูกเลื่อนขึ้น เราต้องพาคุณไปยังที่ปลอดภัย",
  ui_story_5053_50530402_18_dialog_content = "จาคีนอยู่ไหน? เธอไปอยู่ที่ไหนในโลกในเวลาเช่นนี้?",
  ui_story_5053_50530402_19_dialog_content = "ใจเย็นๆ คาเลบ ทีละเรื่อง",
  ui_story_5053_50530402_20_dialog_content = "เหงื่อออกทุกที่ แม้แต่ปลอกคอยังยับ ที่นี่ให้ฉันแก้ไขให้คุณ",
  ui_story_5053_50530402_21_dialog_content = "ฮะ? เอ่อ ฉันจัดการเอง...",
  ui_story_5053_50530402_22_dialog_content = "T-ขอบคุณค่ะพี่สาว",
  ui_story_5053_50530402_23_dialog_content = "เลดี้โจชัวไม่เป็นไร แต่จาคีนหนีไปไหน",
  ui_story_5053_50530402_24_dialog_content = "คุณจาคีนอยู่ไหน!!",
  ui_story_5053_50530402_25_dialog_content = "โอย...",
  ui_story_5053_50530402_26_dialog_content = "สิ...ส...?",
  ui_story_5053_50530402_27_dialog_content = "เกิดอะไรขึ้น คาเลบ?",
  ui_story_5053_50530402_28_dialog_content = "ท-นี่...",
  ui_story_5053_50530402_29_dialog_content = "แต่...ทำไม?",
  ui_story_5053_50530402_30_dialog_content = "หน้าอกของคุณ Caleb?!",
  ui_story_5053_50530402_31_dialog_content = "คุณได้รับบาดเจ็บระหว่างทางหรือไม่? N-ไม่ ไม่สามารถ...",
  ui_story_5053_50530402_32_dialog_content = "ทำไมอายุยังชอบนั่งกับพื้น?",
  ui_story_5053_50530402_33_dialog_content = "ยังเด็กเหมือนเดิม Caleb",
  ui_story_5053_50530402_34_dialog_content = "ช่างน่าผิดหวัง",
  ui_story_5053_50530402_35_dialog_content = "ทำไม...",
  ui_story_5053_50530402_36_dialog_content = "พี่...",
  ui_story_5053_50530402_37_dialog_content = "เมียหลวง...",
  ui_story_5053_50530402_38_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530402_39_dialog_content = "ฉันรู้ว่าเราย้อนเวลาได้...",
  ui_story_5053_50530402_40_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530402_41_dialog_content = "แต่ไม่อยากให้ผ่านเลยไป...",
  ui_story_5053_50530402_42_dialog_content = "แม้ว่าเธอจะเกลียดฉันที่ส่งเธอไปจากฉัน แต่ฉันก็จะสบายใจได้เมื่อรู้ว่าเธอปลอดภัยดี...",
  ui_story_5053_50530402_43_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530402_44_dialog_content = "<size=45>คำราม—!</size>",
  ui_story_5053_50530402_45_dialog_content = "คุณต้องการที่จะฆ่าฉันหลังจากฆ่าครอบครัวของฉัน?",
  ui_story_5053_50530402_46_dialog_content = "ฉันจะตอบแทนคุณสองเท่าสำหรับความเจ็บปวดที่คุณทำกับพวกเขา...",
  ui_story_5053_50530402_47_dialog_content = "<size=45>คำราม—!</size>",
  ui_story_5053_50530402_48_dialog_content = "<size=45>ให้ตายเถอะ!!!</size>",
  ui_story_5053_50530402_49_dialog_content = "<color=#e8d9bb>ตุบ ตุบ...</color>",
  ui_story_5053_50530402_50_dialog_content = "(ทำไม ทำไม ทำไม!)",
  ui_story_5053_50530402_51_dialog_content = "(ทำไม Lady Joshua ถึงฆ่า Caleb น้องชายของเธอเอง?!)",
  ui_story_5053_50530402_52_dialog_content = "<color=#e8d9bb>ตึก ตึก ตึก...</color>",
  ui_story_5053_50530402_53_dialog_content = "(ทุกคนในโลกนี้บ้าไปแล้วเหรอ?)",
  ui_story_5053_50530402_54_dialog_content = "(หรือฉันติดอยู่ในฝันร้ายที่ไม่มีวันจบสิ้น?)",
  ui_story_5053_50530402_55_dialog_content = "<color=#e8d9bb>ตึก ตึก ตึก...</color>",
  ui_story_5053_50530402_56_dialog_content = "(เธอไปแล้วเหรอ?)",
  ui_story_5053_50530402_57_dialog_content = "(แต่ฉันซ่อนใต้โต๊ะตลอดไปไม่ได้หรอก...ฉันจะทำยังไงดี?)",
  ui_story_5053_50530402_58_dialog_content = "<color=#e8d9bb>ตุ้บ ตุ้บ.</color>",
  ui_story_5053_50530402_59_dialog_content = "(เสียงฝีเท้าหยุดลง...)",
  ui_story_5053_50530402_60_dialog_content = "ฉันพบคุณ!",
  ui_story_5053_50530402_61_dialog_content = "อะไรนะ!",
  ui_story_5053_50530402_62_dialog_content = "โอ้ ที่รัก แม้แต่คาร์ลีนก็ยังเล่นซ่อนหา",
  ui_story_5053_50530402_63_dialog_content = "คุณไม่ใช่เด็กอีกต่อไป PlayerName. คุณต้องการให้ฉันเล่นเกมกับคุณอีกนานแค่ไหน?",
  ui_story_5053_50530402_64_dialog_content = "แฮ่ก... แฮ่ก...",
  ui_story_5053_50530402_65_dialog_content = "หยุดวิ่ง นั่นมีแต่จะทำให้ความตายของคุณทรมานมากขึ้น",
  ui_story_5053_50530402_66_dialog_content = "Mia, Caleb... Lumina ของพวกเขาดี ฉันไม่เคยรู้สึกชุ่มชื่นเท่านี้มาก่อน",
  ui_story_5053_50530402_67_dialog_content = "ฉันสงสัยว่าจะเกิดอะไรขึ้นถ้าฉันใช้ลูมิน่าของ Caelestite? บางทีฉันอาจจะอ่านใจคนอื่นได้ด้วย?",
  ui_story_5053_50530402_68_dialog_content = "ฉันไม่ปล่อยแกไปแน่!",
  ui_story_5053_50530402_69_dialog_content = "ก็ฉันควบคุมคนในโลกนี้ได้อยู่แล้ว",
  ui_story_5053_50530402_70_dialog_content = "นั่นทำให้สิ่งต่าง ๆ ง่ายและสะดวกใช่ไหม",
  ui_story_5053_50530402_71_dialog_content = "แฮ่ก... แฮ่ก...",
  ui_story_5053_50530402_72_dialog_content = "(ข้างหน้ามีประตูเดียวเท่านั้น... ได้โปรดอย่าปล่อยให้มันเป็นทางตัน!)",
  ui_story_5053_50530402_73_dialog_content = "นั่นสินะ... ฉันเดาว่านั่นเป็นสัญชาตญาณของ The Last Caelesite",
  ui_story_5053_50530402_74_dialog_content = "เลือกที่ดี",
  ui_story_5053_50530402_75_dialog_content = "<color=#e8d9bb>เอี๊ยด—</color>",
  ui_story_5053_50530402_76_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530402_77_dialog_content = "จากิน?!",
  ui_story_5053_50530402_78_dialog_content = "จากิน! ตัวเธอเย็นและหายใจไม่ออก...",
  ui_story_5053_50530402_79_dialog_content = "คุณรู้วิธีเลือกจุดอย่างแน่นอน PlayerName.",
  ui_story_5053_50530402_80_dialog_content = "ผู้ทำนายแดนเหนือสามารถควบคุมคริสตัลได้ ดังนั้นเธอจึงเป็นคนแรกที่ฉันฆ่า",
  ui_story_5053_50530402_81_dialog_content = "ทำไมฉันถึงขอให้เธออยู่กับฉัน",
  ui_story_5053_50530402_82_dialog_content = "ฉันไม่เข้าใจ เลดี้โจชัว ทำไมคุณทำแบบนี้",
  ui_story_5053_50530402_83_dialog_content = "ทำไมคุณถึงฆ่าจาคีนและน้องชายของคุณ... และฉันด้วย",
  ui_story_5053_50530402_84_dialog_content = "มันยากที่จะเข้าใจ? ฉันต้องการพลังของคุณ",
  ui_story_5053_50530402_85_dialog_content = "ฉันไม่แบกรับความประสงค์ร้ายของคุณ แต่การเสียสละของคุณเป็นสิ่งจำเป็น",
  ui_story_5053_50530402_86_dialog_content = "ฉันไม่เข้าใจ คุณคือโจชัวตัวจริงหรือเปล่า",
  ui_story_5053_50530402_87_dialog_content = "แท้จริงแล้วคุณเป็นอะไร?",
  ui_story_5053_50530402_88_dialog_content = "ฉันคือโจชัว โจชัวตัวจริง!",
  ui_story_5053_50530402_89_dialog_content = "เปิดตาของคุณให้กว้างและดูดี จำสิ่งนี้ไว้ก่อนตาย",
  ui_story_5053_50530402_90_dialog_content = "<color=#e8d9bb>ฟิ้วววว!</color>",
  ui_story_5053_50530402_91_dialog_content = "ว่าไง",
  ui_story_5053_50530402_92_dialog_content = "เข้ามาหาฉันสิ PlayerName...",
  ui_story_5053_50530402_93_dialog_content = "จากิน?!",
  ui_story_5053_50530402_94_dialog_content = "คุณยังมีชีวิตอยู่? ฉันคิดว่าคุณเป็น...",
  ui_story_5053_50530402_95_dialog_content = "คุณลืม? เป็นหมอดูพเนจรตั้งแต่ยังเล็ก...",
  ui_story_5053_50530402_96_dialog_content = "เคล็ดลับเล็ก ๆ น้อย ๆ คืออะไร? ... (เริ่มไอ)",
  ui_story_5053_50530402_97_dialog_content = "จากิน!",
  ui_story_5053_50530402_98_dialog_content = "แล้วคนอื่น ๆ ล่ะครับ?",
  ui_story_5053_50530402_99_dialog_content = "...",
  ui_story_5053_50530402_100_dialog_content = "คำสาป...!",
  ui_story_5053_50530402_101_dialog_content = "สร้างภาพลวงตาด้วยเวทมนตร์แห่งดินแดนทางเหนือ...",
  ui_story_5053_50530402_102_dialog_content = "ช่างเป็นสติปัญญาที่น่ารังเกียจ",
  ui_story_5053_50530402_103_dialog_content = "ขอโทษนะ ฉันเป็นเด็กดื้อมาโดยตลอด",
  ui_story_5053_50530402_104_dialog_content = "ถ้าอย่างนั้นให้ฉันแสดงให้คุณเห็นวินัย!",
  ui_story_5053_50530402_105_dialog_content = "ระวังลูกแก้ว!",
  ui_story_5053_50530402_106_dialog_content = "รับ Crystal of Eternal Memory ที่นี่ PlayerName.",
  ui_story_5053_50530402_107_dialog_content = "วางมือของคุณบนมัน แม้จะทำไม่ได้...",
  ui_story_5053_50530402_108_dialog_content = "คุณต้องไม่ปล่อยมือ",
  ui_story_5053_50530402_109_dialog_content = "เข้าใจแล้ว!",
  ui_story_5053_50530402_110_dialog_content = "เรดดิตัส เรดดิตัส เรดดิตัส!",
  ui_story_5053_50530402_111_dialog_content = "ย้อนกลับไปจุดเริ่มต้น...",
  ui_story_5053_50530402_112_dialog_content = "Abracadabra—เออ!",
  ui_story_5053_50530402_113_dialog_content = "อ๊ะ ไม่นะ...",
  ui_story_5053_50530402_114_dialog_content = "จากิน... จากิน—!",
  ui_story_5053_50530501_0X_dialog_content = "<color=#e8d9bb>หลังจากรีเซ็ตครั้งที่สอง—</color>",
  ui_story_5053_50530501_1_dialog_content = "ทุกอย่างพร้อมแล้วเจ้านายของฉัน",
  ui_story_5053_50530501_2_dialog_content = "รถม้ารออยู่ข้างนอกและพร้อมออกเดินทางได้ทุกเมื่อ",
  ui_story_5053_50530501_3_dialog_content = "...",
  ui_story_5053_50530501_4_dialog_content = "นายท่านยังกังวลเกี่ยวกับภรรยาของท่านอยู่หรือไม่?",
  ui_story_5053_50530501_5_dialog_content = "โจชัวมีสุขภาพที่ดีอยู่เสมอ และเธอมักจะไม่บ่นเกี่ยวกับสภาพอากาศ ยิ่งไม่ใช่วันแบบนี้",
  ui_story_5053_50530501_6_dialog_content = "ช่วงนี้เธอค่อนข้างยุ่ง คอยสนับสนุนนโยบายใหม่ให้กับภรรยาของขุนนาง ฉันคิดว่ามันคงทำให้เธอลำบากใจ",
  ui_story_5053_50530501_7_dialog_content = "มั่นใจเถอะเจ้านายของฉัน ฉันจะดูแลเธออย่างดี",
  ui_story_5053_50530501_8_dialog_content = "อ๊ากก...",
  ui_story_5053_50530501_9_dialog_content = "ฉันอยู่ที่ไหน...?",
  ui_story_5053_50530501_10_dialog_content = "เดี๋ยวก่อน ที่นี่... ข้างนอกยังกลางวันอยู่หรือเปล่า?",
  ui_story_5053_50530501_11_dialog_content = "ฉันถูกไล่ล่า และฉันก็บังเอิญเจอ Jakine แล้วก็...",
  ui_story_5053_50530501_12_dialog_content = "(ขอบคุณที่ช่วยฉัน จาคีน...)",
  ui_story_5053_50530501_13_dialog_content = "(แต่ฉันไม่เห็นเธอที่ไหนเลยแถวนี้... เป็นไปได้ไหมว่าเราแยกจากกันเหมือนตอนที่เราเข้ามาข้างในคริสตัลครั้งแรก?)",
  ui_story_5053_50530501_14_dialog_content = "(แล้วทำไมเลดี้โจชัวถึงโจมตีเราแบบนั้น เป็นไปได้ไหมว่าเธอไม่ใช่โจชัวตัวจริง?)",
  ui_story_5053_50530501_15_dialog_content = "(ไม่ เธอเป็น <color=#FFB400>คนจริง</color>เช่นเดียวกับพวกเราที่เหลือ Jakine พิสูจน์โดยใช้ Crystal of Eternal Memory)",
  ui_story_5053_50530501_16_dialog_content = "ฉันคือโจชัว โจชัวตัวจริง",
  ui_story_5053_50530501_17_dialog_content = "(วิธีที่เธอเน้นย้ำถึงตัวตนของเธอ... นั่นหมายถึงอะไร?)",
  ui_story_5053_50530501_18_dialog_content = "(ฉันสับสนมาก แต่ตอนนี้ไม่สำคัญแล้ว ถ้ามีอะไรผิดปกติกับ Joshua จริง ๆ เราควรกลับยังไง?)",
  ui_story_5053_50530501_19_dialog_content = "(อ๊าาา... มีอะไรเกิดขึ้นมากมายที่ฉันไม่เข้าใจ แล้วทำไมฉันถึงมาคนเดียวล่ะ!)",
  ui_story_5053_50530501_20_dialog_content = "<color=#e8d9bb>หลุม ตบ หลุม pat—</color>",
  ui_story_5053_50530501_21_dialog_content = "เสียงนั้น! คือว่า...?",
  ui_story_5053_50530501_22_dialog_content = "ที่นี่...?",
  ui_story_5053_50530501_23_dialog_content = "Dark Angel มาพบเราที่นี่ได้อย่างไร? ฉันคิดว่าเรารีเซ็ตทุกอย่างแล้ว!",
  ui_story_5053_50530501_24_dialog_content = "ท-นั่นเสียงน้องสาวฉัน...",
  ui_story_5053_50530501_25_dialog_content = "... ที่นี่!",
  ui_story_5053_50530501_26_dialog_content = "ไวท์ไนท์ ปกป้องพวกเรา!",
  ui_story_5053_50530501_27_dialog_content = "อย่าเสียสมาธิในการต่อสู้ คาเลบ!",
  ui_story_5053_50530501_28_dialog_content = "อ๊าาา—!",
  ui_story_5053_50530501_29_dialog_content = "ดาบแห่งราชัน!",
  ui_story_5053_50530501_30_dialog_content = "ฉันเกลียด...",
  ui_story_5053_50530501_31_dialog_content = "อัก!",
  ui_story_5053_50530501_32_dialog_content = "รวดเร็วทันใจ! ระวังให้ดี ท่านชวาร์ตษ์!",
  ui_story_5053_50530501_33_dialog_content = "คุณหมดหวังที่จะต่อสู้กับฉันแบบตัวต่อตัวหรือไม่?",
  ui_story_5053_50530501_34_dialog_content = "ฉันจะให้ความปรารถนาของคุณแล้ว",
  ui_story_5053_50530501_35_dialog_content = "ช...ชวาร์ต...!",
  ui_story_5053_50530501_36_dialog_content = "Mia และคนอื่นๆ กำลังต่อสู้กับ Dark Angel ตัวนั้นอีกครั้ง... ดังนั้นเราจึงสามารถเริ่มต้นความทรงจำใหม่ได้!",
  ui_story_5053_50530501_37_dialog_content = "ฉันต้องไปที่นั่นและช่วยพวกเขา!",
  ui_story_5053_50530501_38_dialog_content = "คุณนั่น... หยุด",
  ui_story_5053_50530501_39_dialog_content = "ยาม? จังหวะเหมาะ! ดูสิ ฉัน—",
  ui_story_5053_50530501_40_dialog_content = "สงสัย...กำจัด...",
  ui_story_5053_50530501_41_dialog_content = "(หือ? ดูเหมือนว่าจะมีบางอย่างผิดปกติเกี่ยวกับคนเหล่านี้?)",
  ui_story_5053_50530501_42_dialog_content = "คุยอะไรกันอยู่เหรอ",
  ui_story_5053_50530501_43_dialog_content = "เลดี้โจชัว... มีคน... ผู้บุกรุก?",
  ui_story_5053_50530501_44_dialog_content = "ผู้บุกรุก...ต้องจับ...แล้วฆ่า!",
  ui_story_5053_50530501_45_dialog_content = "(มีบางอย่างผิดปกติในใจพวกเขา! พวกเขาเหมือนกับผู้คนจากจัตุรัสกลางเมือง!)",
  ui_story_5053_50530501_46_dialog_content = "อ๊าาา!!!",
  ui_story_5053_50530502_1_dialog_content = "<color=#e8d9bb>ตูม—!!</color>",
  ui_story_5053_50530502_2_dialog_content = "อึก...ไอ ไอ...",
  ui_story_5053_50530502_3_dialog_content = "มันไปไหนแล้ว",
  ui_story_5053_50530502_4_dialog_content = "คงจะหนีไปตามรอยข้างนอก...",
  ui_story_5053_50530502_5_dialog_content = "มันยอดเยี่ยมมาก ลอร์ดชวาร์ตษ์!",
  ui_story_5053_50530502_6_dialog_content = "นางฟ้าต้องเจ็บหนักเท่าแรงคงไปไม่ได้ไกล",
  ui_story_5053_50530502_7_dialog_content = "...",
  ui_story_5053_50530502_8_dialog_content = "คุณยังกังวลเกี่ยวกับ Dark Angel อยู่หรือเปล่า ลุง?",
  ui_story_5053_50530502_9_dialog_content = "เสียงของมัน... ไม่เป็นไร น้องสาวของฉันไม่มีวันเป็นสัตว์ประหลาดได้",
  ui_story_5053_50530502_10_dialog_content = "เดี๋ยวก่อน เราลืมอะไรไปหรือเปล่า? โอ้ ไม่ ที่ไหน PlayerName?!",
  ui_story_5053_50530502_11_dialog_content = "เฮ้ คุณพูดถูก! ที่ไหน PlayerName วิ่งไปหา?!",
  ui_story_5053_50530502_12_dialog_content = "โอ้คุณทั้งหมด!",
  ui_story_5053_50530502_13_dialog_content = "วุ้ย... ฉันเสียพวกมันไปหรือเปล่านะ?",
  ui_story_5053_50530502_14_dialog_content = "โน่น...นั่น!",
  ui_story_5053_50530502_15_dialog_content = "ฆ่าผู้บุกรุก!",
  ui_story_5053_50530502_16_dialog_content = "(บัดซบ! แม้ว่าตอนนี้พวกเขาจะไม่มีสติ แต่การ์ดเหล่านี้ก็ยังสั่นไหวไม่ได้!)",
  ui_story_5053_50530502_17_dialog_content = "ไม่... ตรงนั้น!",
  ui_story_5053_50530502_18_dialog_content = "(...เดี๋ยวก่อน ฉันทำได้แล้ว!)",
  ui_story_5053_50530502_19_dialog_content = "<color=#e8d9bb>ตุ้บ—</color>",
  ui_story_5053_50530502_20_dialog_content = "(นี่มันรถเข็นอะไรเนี่ย? มันต้องสำหรับวันหยุดแน่ๆ... ยังไงก็ตาม ฉันคิดว่าพวกเขาจะไม่เห็นฉันที่นี่)",
  ui_story_5053_50530502_21_dialog_content = "ไม่มี... ที่ไหน?",
  ui_story_5053_50530502_22_dialog_content = "ถนนนั้น... ไป...",
  ui_story_5053_50530502_23_dialog_content = "ยามพวกนั้นทำตัวแปลกๆ พวกเขากำลังตามหาใครอยู่หรือเปล่า?",
  ui_story_5053_50530502_24_dialog_content = "ฉันไม่แน่ใจ แต่ใครจะอยากเริ่มต้นปัญหาในวันเช่นนี้? ขบวนพาเหรดกำลังจะเริ่มแล้ว!",
  ui_story_5053_50530502_25_dialog_content = "ฉันแทบรอไม่ไหวที่จะได้เห็นมัน!",
  ui_story_5053_50530502_26_dialog_content = "(ว้าย! ในที่สุดฉันก็เสียพวกมันไปจนได้...)",
  ui_story_5053_50530502_27_dialog_content = "(ตามที่ผู้หญิงคนนั้นบอก ดูเหมือนว่าขบวนพาเหรดยังไม่เริ่ม)",
  ui_story_5053_50530502_28_dialog_content = "(ดี นั่นทำให้ฉันมีเวลารวบรวมความคิดและคิดหาแนวทางต่อไป)",
  ui_story_5053_50530502_29_dialog_content = "(ฉันมีคำถามที่ต้องพิจารณาในตอนนี้...)",
  ui_story_5053_50530502_30_option_content = "สถานการณ์ปัจจุบัน",
  ui_story_5053_50530502_31_dialog_content = "(ขบวนพาเหรดยังไม่เริ่ม และตอนนี้ทุกคนน่าจะได้เห็น Lady Joshua แล้ว)",
  ui_story_5053_50530502_32_dialog_content = "(นั่นหมายความว่ามีสองสถานการณ์ที่เป็นไปได้ในขณะนี้ ซึ่งทั้งสองสถานการณ์ขึ้นอยู่กับ <color=#FFB400>ไม่ว่าทุกคนจะจำการรีเซ็ตเวลาได้หรือไม่</color>.)",
  ui_story_5053_50530502_33_dialog_content = "(ถ้าทุกคนยังจำได้ พวกเขาต้องต่อสู้กับเลดี้โจชัวแล้วหนีไป)",
  ui_story_5053_50530502_34_dialog_content = "(ถ้าเป็นกรณีนี้ คนอื่นๆ ควรจะออกไปตามหาฉันตอนนี้ ฉันยังไม่คุ้นเคยกับ Lumopolis มากนัก ดังนั้นฉันควรจะก้มหน้าลงและรอให้พวกเขาพบฉัน)",
  ui_story_5053_50530502_35_dialog_content = "(แต่หากไม่มีใครจำเวลาที่รีเซ็ตได้ พวกเขาก็อาจตกหลุมพรางของ Joshua...)",
  ui_story_5053_50530502_36_dialog_content = "(ถ้าเป็นเช่นนั้น ทุกอย่างควรจะเกิดขึ้นเหมือนก่อนการรีเซ็ต Jakine จะถูกทิ้งไว้เบื้องหลัง และคนอื่นๆ จะเดินทางไปยังจัตุรัสกลาง)",
  ui_story_5053_50530502_37_dialog_content = "(บังเอิญฉันอยู่ใกล้จัตุรัสมากเหมือนกัน ดูเหมือนว่าทางออกที่ดีที่สุดของฉันคือนั่งที่นี่และรอให้ทุกคนมาถึง)",
  ui_story_5053_50530502_38_dialog_content = "(แต่ก็มี Jakine... Drat! เราจะไม่สามารถช่วยเหลือเธอได้จนกว่าคนอื่นๆ จะมาถึงที่นี่!)",
  ui_story_5053_50530502_39_option_content = "ความทรงจำ\"",
  ui_story_5053_50530502_40_dialog_content = "(อ้างอิงจาก Jakine การใช้การทำนายไม่ว่าด้วยเหตุผลใดๆ ก็ตามต้องใช้ก <color=#FFB400>ปฏิบัติตามกฎอย่างเคร่งครัด</color>.)",
  ui_story_5053_50530502_41_dialog_content = "(ระหว่างการรีเซ็ตครั้งแรก Jakine คอยบอกให้เราทำ <color=#FFB400>จับมือกันไว้แน่น</color>.)",
  ui_story_5053_50530502_42_dialog_content = "(โจชัวยังกล่าวด้วยว่านี่คือเหตุผลที่เธอจำเหตุการณ์ของการรีเซ็ตครั้งแรกได้ เป็นเพราะเธออยู่กับเราเมื่อมันเกิดขึ้น)",
  ui_story_5053_50530502_43_dialog_content = "(หมายความว่าเธอจับมือเราโดยที่เราไม่ทันสังเกต?)",
  ui_story_5053_50530502_44_dialog_content = "(ระหว่างการรีเซ็ตครั้งที่สอง ผู้ที่ครอบครอง Crystal of Eternal Memory มีเพียง Jakine และฉันเท่านั้น)",
  ui_story_5053_50530502_45_dialog_content = "(นั่นหมายความว่า Joshua และคนอื่นๆ จะจำการรีเซ็ตครั้งที่สองไม่ได้ใช่ไหม)",
  ui_story_5053_50530502_46_dialog_content = "(จาคีนกับฉันน่าจะเป็นคนเดียวที่จำทุกสิ่งที่เกิดขึ้นตั้งแต่เรามาอยู่ที่นี่...)",
  ui_story_5053_50530502_47_dialog_content = "(หรืออย่างน้อยฉันก็หวังอย่างนั้น)",
  ui_story_5053_50530502_48_option_content = "มังกร ทหาร และเทพบุตร",
  ui_story_5053_50530502_49_dialog_content = "(เมื่อกี้มันเกี่ยวอะไรกับการ์ดพวกนั้น? ทำไมพวกเขาถึงพยายามจับตัวฉัน?)",
  ui_story_5053_50530502_50_dialog_content = "(พวกเขาบ้าพอๆ กับผู้คนจากจัตุรัสกลาง มันเหมือนกับว่าพวกเขาลงมาด้วยโรคลึกลับบางอย่าง... หรือพวกเขาถูกควบคุมจิตใจ)",
  ui_story_5053_50530502_51_dialog_content = "(เมื่อพิจารณาว่าพวกเขาตั้งใจจะตามล่าฉันมากเพียงใด ฉันว่าพวกเขาพยายามแยกฉันออกจากคนอื่นๆ พวกเขาคอยไล่ตามฉัน บังคับให้ฉันออกจากคฤหาสน์)",
  ui_story_5053_50530502_52_dialog_content = "(ฉันไม่สามารถใช้พลังจิตของฉันใน Crystal of Eternal Memory ได้ ดังนั้นฉันไม่มีทางรู้ว่าเกิดอะไรขึ้นชั้นบนในขณะที่ทุกคนกำลังต่อสู้กันอยู่)",
  ui_story_5053_50530502_53_dialog_content = "(และฉันลงเอยด้วยการพลาดโอกาสที่จะได้พบกับพวกเขา...)",
  ui_story_5053_50530502_54_dialog_content = "(ถ้าโจชัวยังมีความทรงจำอยู่ แสดงว่าเธอคงส่งทหารมาปิดปากฉันแล้ว)",
  ui_story_5053_50530502_55_dialog_content = "(แต่ถ้าเธอไม่ทำเช่นนั้น เธอต้องสั่งให้พวกเขาฆ่าคนที่พลัดหลงออกไปให้หมด)",
  ui_story_5053_50530502_56_dialog_content = "(เหมือนกับครั้งแรกที่เราแยกจากจาคีน)",
  ui_story_5053_50530502_57_dialog_content = "(การต่อสู้กับ Dark Angel ต้องเป็นส่วนหนึ่งของแผนของเธอด้วย วิธีนี้จะทำให้เธอแยกเราออกจากกันและกำจัด Jakine ได้!)",
  ui_story_5053_50530502_58_dialog_content = "(ณ จุดนี้ชัดเจนว่ายามที่ไล่ล่าฉันกำลังทำงานให้เธอ...)",
  ui_story_5053_50530502_59_dialog_content = "(น่าจะปลอดภัยถ้าสมมติว่าคนบ้าคลั่งจากจัตุรัสและมังกรดำนั้นอยู่ภายใต้การควบคุมของเธอด้วย)",
  ui_story_5053_50530502_60_dialog_content = "(ซึ่งหมายความว่าทุกสิ่งที่เราทำตั้งแต่การรีเซ็ตครั้งแรกเป็นส่วนหนึ่งของแผนของเธอทั้งหมด... น่ากลัวจริงๆ)",
  ui_story_5053_50530502_61_dialog_content = "(แต่แล้วดาร์คแองเจิ้ลล่ะ เธอเกี่ยวพันกับโจชัวยังไง?)",
  ui_story_5053_50530502_62_dialog_content = "(สองคนนี้ร่วมงานกันหรือเปล่า หรือมีเรื่องมากกว่านั้น...?)",
  ui_story_5053_50530502_63_dialog_content = "(ตอนนี้ฉันไม่มีข้อมูลเพียงพอที่จะทำงานด้วย)",
  ui_story_5053_50530502_64_dialog_content = "(เฮ้อ... จะว่าไปแล้ว การนั่งรอคนอื่นนี่ยังคงเป็นแนวทางที่ดีที่สุดของฉัน)",
  ui_story_5053_50530502_65_dialog_content = "(ฉันจะบอกความจริงกับทุกคนเมื่อพวกเขาพบฉัน เพื่อเราจะได้ไปช่วยจาคิน...)",
  ui_story_5053_50530502_66_dialog_content = "(ฉันแค่หวังว่าพวกเขาจะไม่เป็นไร!)",
  ui_story_5053_50530601_1_dialog_content = "คุณกำลังพูดว่า...",
  ui_story_5053_50530601_2_dialog_content = "เราสามารถทำลาย Dark Angel และนำ Lady Joshua ออกไปจากที่นี่ได้....",
  ui_story_5053_50530601_3_dialog_content = "... หรือ Dark Angel ฆ่าเราและหลุดออกไปในโลกแห่งความเป็นจริง?",
  ui_story_5053_50530601_4_dialog_content = "นั่นถูกต้องแล้วใช่",
  ui_story_5053_50530601_5_dialog_content = "...",
  ui_story_5053_50530601_6_dialog_content = "ฉันเข้าใจแผนการหลบหนีของเราเป็นอย่างดี แต่...",
  ui_story_5053_50530601_7_dialog_content = "อยู่ไหน PlayerName? ฉันเริ่มเป็นห่วงเขาจริงๆ",
  ui_story_5053_50530601_8_dialog_content = "เขาจากเราไปนานเกินไป ต้องมีบางอย่างเกิดขึ้นกับเขา!",
  ui_story_5053_50530601_9_dialog_content = "ฉันก็ไม่แน่ใจเหมือนกันกับสถานการณ์ปัจจุบันของเขา แต่ไม่ต้องห่วง ฉันจะส่งทีมองครักษ์ไปตามหาเขา",
  ui_story_5053_50530601_10_dialog_content = "เรากำลังหมดเวลา ถ้าเราต้องการจะหนีจากที่นี่อย่างปลอดภัย ลำดับความสำคัญจะไปอยู่ที่การเอาชนะมอนสเตอร์ตัวนั้น",
  ui_story_5053_50530601_11_dialog_content = "งั้นไปล่าดาร์คแองเจิ้ลกันเถอะ!",
  ui_story_5053_50530601_12_dialog_content = "ไม่นะ จาคีน คุณต้องอยู่ที่นี่กับฉัน",
  ui_story_5053_50530601_13_dialog_content = "ฮะ? แต่มาได้อย่างไร? ลูกแก้วของฉันก็มีประโยชน์ในการต่อสู้เหมือนกันนะ!",
  ui_story_5053_50530601_14_dialog_content = "ใช่ ฉันรู้ แต่คุณเป็นคนควบคุมคริสตัล",
  ui_story_5053_50530601_15_dialog_content = "ถ้าคนอื่นบาดเจ็บเราย้อนเวลาคืนทุกอย่างได้เสมอ",
  ui_story_5053_50530601_16_dialog_content = "แต่ถ้ามีอะไรเกิดขึ้นกับคุณ",
  ui_story_5053_50530601_17_dialog_content = "ก็จริงนะ..",
  ui_story_5053_50530601_18_dialog_content = "แม่? ฉัน-ถ้าคุณกับจาคีนจะอยู่ที่นี่ คาร์ลีนก็ควรกลับมาด้วย",
  ui_story_5053_50530601_19_dialog_content = "ฉันไม่อยากให้เธอและพ่อรู้สึกโดดเดี่ยวโดยไม่มีเราอยู่ที่นั่น",
  ui_story_5053_50530601_20_dialog_content = "ดีมาก. ฉันจะให้ยามเรียกเธอกลับไปที่ห้องของเธอเพื่อพักผ่อน",
  ui_story_5053_50530601_21_dialog_content = "คุณไม่ต้องการให้เธอที่นี่กับเราแม่? เธอเฝ้ารอวันนี้มานาน ทำไมส่งเธอกลับห้องคนเดียว?",
  ui_story_5053_50530601_22_dialog_content = "พลาดขบวนพาเหรด เธอจะเสียใจไหม...?",
  ui_story_5053_50530601_23_dialog_content = "วอนนี่ผู้น่ารักของฉัน... โลกภายใน Crystal of Eternal Memory ไม่มีอะไรมากไปกว่าภาพลวงตา",
  ui_story_5053_50530601_24_dialog_content = "เราต้องเป็นไปตามเหตุการณ์ที่กำหนดไว้ล่วงหน้า อย่าปล่อยให้ข้อกังวลที่ไม่จำเป็นใดๆ มากวนใจคุณจากวัตถุประสงค์ของคุณ",
  ui_story_5053_50530601_25_dialog_content = "โอ๊ะ...",
  ui_story_5053_50530601_26_dialog_content = "พี่สาวของฉันพูดถูก Mia ทั้งหมดนี้เป็นเรื่องเพ้อฝัน ดังนั้นอย่าปล่อยให้อารมณ์ของคุณมาบงการคุณ",
  ui_story_5053_50530601_27_dialog_content = "A-เอาล่ะ ขอโทษที่ทำตัวไร้เดียงสา...",
  ui_story_5053_50530601_28_dialog_content = "...",
  ui_story_5053_50530601_29_dialog_content = "โจชัวให้ประเด็นที่ถูกต้อง ความปลอดภัยของทุกคนควรมีความสำคัญสูงสุด ซึ่งเป็นเหตุผลว่าทำไม Caleb จึงควรอยู่ที่นี่ด้วย",
  ui_story_5053_50530601_30_dialog_content = "ฉันจะค้นหา PlayerName ตัวฉันเอง. ตอนนี้ทุกคนควรอยู่ด้วยกัน",
  ui_story_5053_50530601_31_dialog_content = "นั่นไม่จำเป็น สามารถหาทีมผู้พิทักษ์ได้ PlayerName เร็วพอๆ กัน ถ้าไม่มากไปกว่านี้",
  ui_story_5053_50530601_32_dialog_content = "นอกจากนี้ เราต้องการความแข็งแกร่งของทุกคนหากเราหวังว่าจะมีโอกาสต่อสู้กับสัตว์ประหลาดตัวนั้น",
  ui_story_5053_50530601_33_dialog_content = "ฉันคิดว่าคุณรู้ดีพอๆ กับฉันว่าเรื่องใดสำคัญกว่ากัน ใช้สามัญสำนึกของคุณ ดาเนียล",
  ui_story_5053_50530601_34_dialog_content = "เฮ้ การตัดสินของคุณเฉียบแหลมเช่นเคย โจชัว ต้องบอกว่านี่พาย้อนวันวานจริงๆ",
  ui_story_5053_50530601_35_dialog_content = "...",
  ui_story_5053_50530601_36_dialog_content = "นี่เป็นช่วงเวลาที่ดีสำหรับการคิดถึงกันจริงๆ เหรอ? เรายังคงแข่งกับเวลา",
  ui_story_5053_50530601_37_dialog_content = "ไม่ว่าในกรณีใด ฉันสามารถชั่งน้ำหนักตัวเลือกต่าง ๆ สำหรับตัวเองได้อย่างสมบูรณ์แบบ",
  ui_story_5053_50530601_38_dialog_content = "ไปกันเถอะมีอา",
  ui_story_5053_50530601_39_dialog_content = "ย-ครับพ่อ",
  ui_story_5053_50530601_40_dialog_content = "เป็นอะไรกับผู้ชายคนนั้น จู่ๆ ก็ทำตัวแปลกๆ เหรอ!",
  ui_story_5053_50530601_41_dialog_content = "...",
  ui_story_5053_50530601_42_dialog_content = "มีอะไรเกี่ยวกับ Joshua รบกวนคุณ Mia?",
  ui_story_5053_50530601_43_dialog_content = "อา! อืม... ม-อาจจะนิดหน่อย...",
  ui_story_5053_50530601_44_dialog_content = "ก็คงมีแค่ฉัน แต่... หลังจากที่ห่างหายไปนาน แม่ก็รู้สึกไม่ค่อยคุ้นเคย",
  ui_story_5053_50530601_45_dialog_content = "บอกฉันที โจชัวเป็นคนแบบไหนสำหรับคุณ?",
  ui_story_5053_50530601_46_dialog_content = "M-แม่คือ... แม่เป็นคนที่ใจดีและอดทนที่สุดเท่าที่ฉันเคยรู้จักมา และแม่ก็รักลูกมากกว่าสิ่งใด",
  ui_story_5053_50530601_47_dialog_content = "ใช่ โจชัวในหัวใจของฉันยังเป็นผู้หญิงที่อบอุ่นและใจดี เป็นหนึ่งในคนที่แน่วแน่และจริงใจที่สุดเท่าที่ฉันเคยพบมา",
  ui_story_5053_50530601_48_dialog_content = "พ่อ...!",
  ui_story_5053_50530601_49_dialog_content = "เชื่อในตัวเองนะมีอา และเชื่อมั่นในภาพลักษณ์ที่สวยงามของคุณแม่ที่คุณเก็บไว้ในใจ",
  ui_story_5053_50530601_50_dialog_content = "เชื่อในตัวฉัน?",
  ui_story_5053_50530601_51_dialog_content = "แม้ว่าปกติคุณจะซุ่มซ่าม แต่คุณก็ได้แสดงให้เห็นด้านที่แข็งแกร่งและกล้าหาญของตัวเองตลอดการทดสอบนี้",
  ui_story_5053_50530601_52_dialog_content = "ฉันคิดว่าถึงเวลาแล้วที่ฉันต้องยอมรับว่าคุณโตแล้ว",
  ui_story_5053_50530601_53_dialog_content = "จากนี้ไป ฉันสัญญาว่าจะเคารพความคิดเห็นของคุณ แทนที่จะบอกว่าคุณรู้สึกอย่างไร",
  ui_story_5053_50530601_54_dialog_content = "ไม่จำเป็นต้องลังเลอีกต่อไป มีอา ไม่ว่าจะเกี่ยวข้องกับแม่ของคุณ หรือคาร์ลีน หรืออะไรก็ตาม...",
  ui_story_5053_50530601_55_dialog_content = "ทำในสิ่งที่คุณรู้สึกว่าถูกต้องและทำอย่างกล้าหาญ ฉันจะเชื่อในตัวคุณเสมอ",
  ui_story_5053_50530601_56_dialog_content = "(พ่อ...ให้กำลังใจไหม?)",
  ui_story_5053_50530601_57_dialog_content = "(ไม่เคยได้ยินเขาพูดอะไรแบบนี้มาก่อน รู้สึก... ดีจัง)",
  ui_story_5053_50530601_58_dialog_content = "ขอบคุณพ่อ ฉันสัญญาว่าจะเด็ดขาดมากขึ้นจากนี้ไป",
  ui_story_5053_50530601_59_dialog_content = "ฉันจะอยู่บนแสตนด์เพื่อเฝ้าระวัง เหมือนที่เราวางแผนไว้ ถ้าฉันเห็นสัญญาณของ Dark Angel ฉันจะบอกให้ทุกคนรู้",
  ui_story_5053_50530601_60_dialog_content = "ดี. ระวังตัวด้วย Mia",
  ui_story_5053_50530601_61_dialog_content = "(มีอาควรจะปลอดภัยที่นั่นชั่วคราว PlayerNameในทางกลับกัน... ตอนนี้เขาอยู่ที่ไหน?)",
  ui_story_5053_50530601_62_dialog_content = "(การหายตัวไปของเขารู้สึกน่าสงสัยอย่างมากในตอนนี้ แต่ทำไม...?)",
  ui_story_5053_50530601_63_dialog_content = "กว่า... ที่นี่...",
  ui_story_5053_50530601_64_dialog_content = "... ที่นี่!",
  ui_story_5053_50530601_65_dialog_content = "เสียงนั่น...",
  ui_story_5053_50530601_66_dialog_content = "ช...ชวาร์ต...!!!",
  ui_story_5053_50530601_67_dialog_content = "อ๊าาาาาา!!!",
  ui_story_5053_50530601_68_dialog_content = "นี่คือที่ที่คุณเคยไป",
  ui_story_5053_50530601_69_dialog_content = "ดี. ตราบใดที่คุณยังอยู่ที่นี่ จะไม่มีใครตกอยู่ในอันตราย",
  ui_story_5053_50530601_70_dialog_content = "เจ็บ! ตาย...ตาย!!!",
  ui_story_5053_50530601_71_dialog_content = "คุณจะไม่หลอกฉันด้วยการปลอมตัวเป็นโจชัว",
  ui_story_5053_50530701_1_dialog_content = "อึก... อ๊าาาา!",
  ui_story_5053_50530701_2_dialog_content = "(หากไม่มี Mia หรือ Caleb ที่นี่ ดูเหมือนว่าเราจะก้ำกึ่ง น่าเสียดายที่ Eclipsites เหล่านี้กำลังเอียงตาชั่งให้เธอเล็กน้อย)",
  ui_story_5053_50530701_3_dialog_content = "“ไวท์ไนท์ ปกป้องพวกเรา!”",
  ui_story_5053_50530701_4_dialog_content = "ฉันจะบอกว่าเรามาถึงทางตันแล้ว ตอนนี้คุณพอใจหรือยัง?",
  ui_story_5053_50530701_5_dialog_content = "ช...ชวาร์ต...!",
  ui_story_5053_50530701_6_dialog_content = "ฉันเกลียดคุณ...!",
  ui_story_5053_50530701_7_dialog_content = "ทำไม...",
  ui_story_5053_50530701_8_dialog_content = "มันเจ็บมาก! ทำไม... ทำไม... ทรยศฉัน?!",
  ui_story_5053_50530701_9_dialog_content = "คุณบอกว่า... เราสร้าง... อนาคตด้วยกัน! คุณสัญญา...!",
  ui_story_5053_50530701_10_dialog_content = "แล้วทำไม... เสียสละ... ครอบครัว?!",
  ui_story_5053_50530701_11_dialog_content = "เจ็บ... ทนไม่ไหว!!!",
  ui_story_5053_50530701_12_dialog_content = "พูดอะไรของเธอน่ะ",
  ui_story_5053_50530701_13_dialog_content = "ถ้าเพียงแต่...ถ้าเพียงแต่ฉันรู้...",
  ui_story_5053_50530701_14_dialog_content = "ฉันไม่เคยจะ...รัก...",
  ui_story_5053_50530701_15_dialog_content = "และ...ก็เลือกคุณ!!!",
  ui_story_5053_50530701_16_dialog_content = "?!",
  ui_story_5053_50530701_17_dialog_content = "โจชัว...?!",
  ui_story_5053_50530701_18_dialog_content = "แต่นี่จะเป็นไปได้อย่างไร?",
  ui_story_5053_50530701_19_dialog_content = "...!!!",
  ui_story_5053_50530701_20_dialog_content = "อ่า...! มะ...มะ...อันตราย...",
  ui_story_5053_50530701_21_dialog_content = "คิดจะไปไหน!",
  ui_story_5053_50530701_22_dialog_content = "กรา-!",
  ui_story_5053_50530701_23_dialog_content = "ไปให้พ้น สิ่งมีชีวิตที่น่ารังเกียจ!",
  ui_story_5053_50530701_24_dialog_content = "(Young Schwartz เพิ่งพูดจบ ซึ่งหมายความว่าการต่อสู้กำลังจะเริ่มขึ้น)",
  ui_story_5053_50530701_25_dialog_content = "(หากทุกอย่างเป็นไปตามที่คาดไว้ มังกรจะปรากฏตัวในไม่ช้า และผู้คนจะตื่นตระหนกพร้อมกับผู้คุม...)",
  ui_story_5053_50530701_26_dialog_content = "(เมื่อเป็นเช่นนั้น ฉันสามารถใช้ประโยชน์จากความโกลาหลและวิ่งไปที่อัฒจันทร์ได้! ฉันต้องพบกับคนอื่นๆ และบอกพวกเขาเกี่ยวกับ Joshua ก่อนที่มันจะสายเกินไป!)",
  ui_story_5053_50530701_27_dialog_content = "คำราม—!",
  ui_story_5053_50530701_28_dialog_content = "อ๊าาา!!!",
  ui_story_5053_50530701_29_dialog_content = "อะ-นั่นอะไรน่ะ?!",
  ui_story_5053_50530701_30_dialog_content = "วิ่ง! ช่วยฉันด้วย!!!",
  ui_story_5053_50530701_31_dialog_content = "ใช้ได้! ตอนนี้เป็นโอกาสของฉันที่จะตามหาลอร์ดชวาร์ตซ์และคนอื่นๆ—",
  ui_story_5053_50530701_32_dialog_content = "<color=#e8d9bb>ตูมม!!!</color>",
  ui_story_5053_50530701_33_dialog_content = "โว้ว...! อะ-อะไรนะ?!",
  ui_story_5053_50530701_34_dialog_content = "คำราม—!",
  ui_story_5053_50530701_35_dialog_content = "<color=#e8d9bb>ตูม!!!</color>",
  ui_story_5053_50530701_36_dialog_content = "อ๊าาา...! อุ๊ย!!!",
  ui_story_5053_50530701_37_dialog_content = "เทพบุตรรัตติกาล?! เกิดอะไรขึ้น?!",
  ui_story_5053_50530701_38_dialog_content = "เธอกำลังทำอะไรบนท้องฟ้า? เธอปิดกั้นการโจมตีของมังกรหรือไม่?",
  ui_story_5053_50530701_39_dialog_content = "มังกรบิน?!",
  ui_story_5053_50530701_40_dialog_content = "มังกรจงเจริญ! มังกรจงเจริญ!!!",
  ui_story_5053_50530701_41_dialog_content = "บ้านคาร์ติมา? ดังนั้นพวกเขาจึงเป็นคนทรยศมาตลอด?",
  ui_story_5053_50530701_42_dialog_content = "ช่างกล้าที่จะแสดงสีที่แท้จริงของพวกเขาในเวลาเช่นนี้",
  ui_story_5053_50530701_43_dialog_content = "(ว่าแต่สัตว์ประหลาดบนท้องฟ้านั่นมันอะไรนะ...?)",
  ui_story_5053_50530701_44_dialog_content = "S-Sister! เกิดอะไรขึ้น?",
  ui_story_5053_50530701_45_dialog_content = "ถอยไปข้างหลังฉัน คาร์ลีน!",
  ui_story_5053_50530701_46_dialog_content = "(มันคือ Dark Angel! แต่ทำไมเธอถึงมาอยู่ที่นี่?)",
  ui_story_5053_50530701_47_dialog_content = "นี่มันอะไรกัน...?!",
  ui_story_5053_50530701_48_dialog_content = "เวโรนิก้า! คาร์ลีน! อยู่ด้านหลัง!",
  ui_story_5053_50530701_49_dialog_content = "<color=#e8d9bb>ทุบ—!</color>",
  ui_story_5053_50530701_50_dialog_content = "(เธอโดนเปลวเพลิงของมังกร! ไม่ เดี๋ยวก่อน... ดูเหมือนว่าเธอกำลังสกัดกั้นการโจมตีของมันอยู่!)",
  ui_story_5053_50530701_51_dialog_content = "แต่ทำไมเธอถึง...",
  ui_story_5053_50530701_52_dialog_content = "เวโรนิก้า ดูเหมือนว่าเธอกำลังช่วยเราขับไล่มังกร!",
  ui_story_5053_50530701_53_dialog_content = "D-เธอหมดสติไปหรือเปล่า?",
  ui_story_5053_50530701_54_dialog_content = "The Dark Angel... ฉันไม่เข้าใจ...",
  ui_story_5053_50530701_55_dialog_content = "เมีย!!!",
  ui_story_5053_50530701_56_dialog_content = "เมียหลวง! คุณสบายดีไหม?!",
  ui_story_5053_50530701_57_dialog_content = "PlayerName? ฉันสบายดี ไม่ต้องกังวล! คุณอยู่ที่ไหนตลอดเวลานี้?",
  ui_story_5053_50530701_58_dialog_content = "อ-นี่...!",
  ui_story_5053_50530701_59_dialog_content = "ฆ่า... ฆ่าผู้บุกรุก!",
  ui_story_5053_50530701_60_dialog_content = "ทึ่ง! ไม่ใช่พวกเขาอีกครั้ง!",
  ui_story_5053_50530701_61_dialog_content = "เกิดอะไรขึ้นกับผู้คุมพวกนั้น?!",
  ui_story_5053_50530701_62_dialog_content = "มังกรจงเจริญ! มังกรจงเจริญ!!!",
  ui_story_5053_50530701_63_dialog_content = "จู่โจม!",
  ui_story_5053_50530701_64_dialog_content = "ระวัง, PlayerName! พวกกบฏก็เข้าร่วมการต่อสู้ด้วย!",
  ui_story_5053_50530701_65_dialog_content = "ฉันจะต้องอธิบายสิ่งต่างๆ ในภายหลัง มีอา ตอนนี้เราต้องเตรียมพร้อมสำหรับการต่อสู้!",
  ui_story_5053_50530701_66_dialog_content = "ไม่สำคัญว่าวันนี้จะมีสัตว์ประหลาดบินได้หรือสวะทรยศกี่ตัวก็ตาม! ในนามของ House Schwartz พวกเจ้าทุกคนจะต้องถูกลงโทษเพราะทำลายวันนี้!",
  ui_story_5053_50530701_67_dialog_content = "*โฮก*",
  ui_story_5053_50530701_68_dialog_content = "ระวัง! ปล่อยให้ Dark Angel อยู่คนเดียวในขณะนี้",
  ui_story_5053_50530701_69_dialog_content = "ศัตรูของเราแตกต่างไปจากเดิม อย่าหวังว่าจะเอาชนะได้ง่ายๆ",
  ui_story_5053_50530701_70_dialog_content = "แล้วคุณจะเป็นใคร...?",
  ui_story_5053_50530701_71_dialog_content = "แค่มุ่งโจมตีไปที่มังกร แล้วช่วยฉันปราบมัน!",
  ui_story_5053_50530701_72_dialog_content = "หืม แม้แต่มังกรบินก็ยังเทียบข้าไม่ได้",
  ui_story_5053_50530701_73_dialog_content = "แสงแห่งไวท์ไนท์!",
  ui_story_5053_50530701_74_dialog_content = "รัว—!!!",
  ui_story_5053_50530701_75_dialog_content = "อะไร?! เจาะคอแต่หายแทบไม่ทัน!!",
  ui_story_5053_50530701_76_dialog_content = "การฟื้นฟูอย่างรวดเร็ว...หรือความคงกระพันบางประเภท",
  ui_story_5053_50530701_77_dialog_content = "แต่อย่างไร? ใครสามารถมอบพลังแบบนี้ให้กับมันได้? นี่อาจเป็นของ Mime หรือเปล่า?",
  ui_story_5053_50530701_78_dialog_content = "...",
  ui_story_5053_50530701_79_dialog_content = "ยามของคุณ! มันเตรียมโจมตีอีกครั้ง!",
  ui_story_5053_50530801_1_dialog_content = "แฮ่ก... แฮ่ก...",
  ui_story_5053_50530801_2_dialog_content = "ฆ่า... ฆ่าผู้บุกรุก... ฆ่าให้หมด!",
  ui_story_5053_50530801_3_dialog_content = "อ่า! ฆ่าพวกเขาทั้งหมด!!!",
  ui_story_5053_50530801_4_dialog_content = "อึ! ทำไมการ์ดบ้าๆพวกนี้ถึงโผล่มาเยอะขึ้นเรื่อยๆ! คุณยังสู้ได้ไหม Mia?",
  ui_story_5053_50530801_5_dialog_content = "เจ้าพวกนี้น่ากลัวมาก... ดวงตาของพวกเขาขาวโพลนไปหมด และใบหน้าของพวกเขาบิดเบี้ยวไปหมด!",
  ui_story_5053_50530801_6_dialog_content = "ฉันสบายดี แต่จำนวนศัตรูมีแต่จะเพิ่มขึ้น!",
  ui_story_5053_50530801_7_dialog_content = "ผู้คนที่วิ่งหนีไปตอนนี้ได้เข้าร่วมกลุ่มของพวกเขาแล้ว... แม้แต่กลุ่มกบฏที่พ่ายแพ้ก็ยังอยู่ข้างพวกเขา!",
  ui_story_5053_50530801_8_dialog_content = "เหมือนโรคระบาดอะไรสักอย่าง...",
  ui_story_5053_50530801_9_dialog_content = "รักษาระยะห่างจากพวกเขา Mia! อะไรก็ตามที่ควบคุมพวกเขาดูเหมือนจะแพร่กระจายผ่านการโจมตีของพวกเขา!",
  ui_story_5053_50530801_10_dialog_content = "แต่เราจะคงอยู่ได้ไม่นานในอัตรานี้...!",
  ui_story_5053_50530801_11_dialog_content = "นี่เป็นส่วนหนึ่งของแผนของเธอด้วยเหรอ? ท่านชวาร์ตษ์ เราต้องการความช่วยเหลือ!",
  ui_story_5053_50530801_12_dialog_content = "พ่อยุ่งเกินไปที่จะต่อสู้กับมังกร!",
  ui_story_5053_50530801_13_dialog_content = "(พ่อ... ทำไงดี?)",
  ui_story_5053_50530801_14_dialog_content = "ไม่จำเป็นต้องลังเลอีกต่อไป มีอา ไม่ว่าจะเกี่ยวข้องกับแม่ของคุณ หรือคาร์ลีน หรืออะไรก็ตาม...",
  ui_story_5053_50530801_15_dialog_content = "ทำในสิ่งที่คุณรู้สึกว่าถูกต้องและทำอย่างกล้าหาญ ฉันจะเชื่อในตัวคุณเสมอ",
  ui_story_5053_50530801_16_dialog_content = "(เชื่อในตัวเอง Mia! เชื่อในวิจารณญาณของคุณ!)",
  ui_story_5053_50530801_17_dialog_content = "ฮิปโปคา—!",
  ui_story_5053_50530801_18_dialog_content = "<color=#e8d9bb>ตูม!!!</color>",
  ui_story_5053_50530801_19_dialog_content = "S-ทรงพลังมาก!",
  ui_story_5053_50530801_20_dialog_content = "ฮิปโปคา! ขอบคุณ... ขอบคุณที่รับสายฉัน! ฉันสัญญาว่าจะไม่ทอดทิ้งคุณอีก!",
  ui_story_5053_50530801_21_dialog_content = "นั่นช่างเหลือเชื่อ Mia! คุณกำจัดการ์ดที่ติดเชื้อทั้งหมดออกไปในคราวเดียว!",
  ui_story_5053_50530801_22_dialog_content = "ฉันแค่ดีใจที่มันได้ผล! มาช่วยพ่อกันเถอะ!",
  ui_story_5053_50530801_23_dialog_content = "เมีย... เดี๋ยวก่อน...",
  ui_story_5053_50530801_24_dialog_content = "หอบ หอบ หอบ...",
  ui_story_5053_50530801_25_dialog_content = "วี-เวโรนิก้า...",
  ui_story_5053_50530801_26_dialog_content = "ซี-คาร์ลีน หัวเธอเลือดไหล!!",
  ui_story_5053_50530801_27_dialog_content = "ผู้คุมคนหนึ่งทำร้ายคุณหรือเปล่า คาร์ลีน? หมายความว่าเธอจะ...",
  ui_story_5053_50530801_28_dialog_content = "หนีไปจากเธอ Mia! ตาเธอเริ่มขาวโพลนเหมือนคนอื่น!!",
  ui_story_5053_50530801_29_dialog_content = "มานี่ คาร์ลีน... วางหอกลง ตกลงไหม?",
  ui_story_5053_50530801_30_dialog_content = "โปรด?",
  ui_story_5053_50530801_31_dialog_content = "...",
  ui_story_5053_50530801_32_dialog_content = "เวโรนิก้า... มันเจ็บ...",
  ui_story_5053_50530801_33_dialog_content = "อย่ากลัวไปเลย คาร์ลีน วางอาวุธลงแล้วให้ฉันทำแผลให้ โอเค?",
  ui_story_5053_50530801_34_dialog_content = "เลขที่! หัว... เจ็บ...!",
  ui_story_5053_50530801_35_dialog_content = "มีเสียงแปลกๆ... มันคอยบอกให้ฉันฆ่าเธอ! ไม่ ฉันจะไม่ทำ!",
  ui_story_5053_50530801_36_dialog_content = "ฉันรู้ว่าคุณจะไม่ทำ คาร์ลีน ฉันจะปกป้องเธอเอง ไม่ต้องกลัว!",
  ui_story_5053_50530801_37_dialog_content = "อยู่ด้านหลัง!!",
  ui_story_5053_50530801_38_dialog_content = "ฉัน... ฉันคือคาร์ลีน เดอ ชวาร์ตซ์... ลูกสาวที่น่าภาคภูมิใจของเฮาส์ชวาร์ตษ์ และผู้พิทักษ์แห่งลูโมโพลิส...",
  ui_story_5053_50530801_39_dialog_content = "และฉันจะไม่ทำร้ายใครในครอบครัวของฉัน! ไม่เคย!",
  ui_story_5053_50530801_40_dialog_content = "อุ๊ย! ฉันไม่อยากทำร้ายคุณ เวโรนิก้า! นั่นเป็นเหตุผลว่าทำไม...",
  ui_story_5053_50530801_41_dialog_content = "ฉันต้องยุติเรื่องนี้ ตรงนี้และเดี๋ยวนี้... ฉันขอโทษ พี่สาว... ลาก่อน",
  ui_story_5053_50530801_42_dialog_content = "อย่าทำอย่างนั้น คาร์ลีน! วางอาวุธลง!!",
  ui_story_5053_50530801_43_dialog_content = "คาร์ลีน!!!",
  ui_story_5053_50530801_44_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5053_50530801_45_dialog_content = "เธอแทงคอด้วยหอกของเธอเอง...",
  ui_story_5053_50530801_46_dialog_content = "คาร์ลีน... คุณ...",
  ui_story_5053_50530801_47_dialog_content = "...",
  ui_story_5053_50530801_48_dialog_content = "ไม่ไม่...!",
  ui_story_5053_50530801_49_dialog_content = "อ๊าาาาาาาาา!!!!",
  ui_story_5053_50530801_50_dialog_content = "คาร์ลีน!! โน้วววว!!!",
  ui_story_5053_50530801_51_dialog_content = "รีบออกไป Mia! นี่ไม่ใช่เรื่องจริง จำได้ไหม? Carleen ในโลกนี้เป็นเพียงภาพลวงตา!",
  ui_story_5053_50530801_52_dialog_content = "ฉันไม่อยากเสียเธอไป คาร์ลีน!!! ได้โปรด... อย่าทิ้งฉันไว้คนเดียว... ได้โปรด คาร์ลีน...",
  ui_story_5053_50530801_53_dialog_content = "ใจเย็นเมีย! ฟังฉันอยู่หรือเปล่า! เฮ้!!",
  ui_story_5053_50530801_54_dialog_content = "(มีอาเสียใจเกินกว่าจะได้ยินฉัน... อย่าบอกนะว่าเธอกำลังจะเสียการควบคุมอีกแล้ว?!)",
  ui_story_5053_50530801_55_dialog_content = "ว้าาาาาา!!!",
  ui_story_5053_50530801_56_dialog_content = "ที่ร้อนแรง!!!",
  ui_story_5053_50530801_57_dialog_content = "พลังเมียหลวงกำลังจะบ้าดีเดือด!!",
  ui_story_5053_50530801_58_dialog_content = "...",
  ui_story_5053_50530801_59_dialog_content = "ทะ-นายกำลังทำอะไรอยู่...?!",
  ui_story_5053_50530801_60_dialog_content = "อย่าร้องไห้...",
  ui_story_5053_50530801_61_dialog_content = "อย่าร้องไห้... ที่รัก ตัวน้อยของฉัน... วอนนี่...",
  ui_story_5053_50530801_62_dialog_content = "ทุกอย่างจะ...เรียบร้อย...",
  ui_story_5053_50530801_63_dialog_content = "อา...",
  ui_story_5053_50530801_64_dialog_content = "เลือกดอกกุหลาบ...เพื่อลูกของฉัน... ♪",
  ui_story_5053_50530801_65_dialog_content = "สายลมที่พัดผ่านใบหน้าของคุณ... รอยยิ้มของคุณเท่านั้นที่ฉันต้องการ... ♪",
  ui_story_5053_50530801_66_dialog_content = "เลือกช่อดอกกุหลาบ...เพื่อพ่อและแม่ที่รัก... ♪",
  ui_story_5053_50530801_67_dialog_content = "แม้โลกจะเปลี่ยนไป...ความรักของเราจะยังเหมือนเดิม... ♪",
  ui_story_5053_50530801_68_dialog_content = "วอนนี่... ดูสิ... นี่แม่...",
  ui_story_5053_50530801_69_dialog_content = "ม-แม่...? แม่!",
  ui_story_5053_50530801_70_dialog_content = "ว้าาาาาาาาาาา!!!",
  ui_story_5053_50530801_71_dialog_content = "แม่! คาร์ลีน... เธอคือ...",
  ui_story_5053_50530801_72_dialog_content = "มือของเธอ... มือของเธออุ่นมาก... และมีเลือดของเธอ...",
  ui_story_5053_50530801_73_dialog_content = "แม่... ได้โปรด...",
  ui_story_5053_50530801_74_dialog_content = "นี่มัน...ก็แค่ฝันร้าย...",
  ui_story_5053_50530801_75_dialog_content = "วอนนี่ตัวน้อยของฉัน... ทั้งหมดนี้...เป็นเพียงฝันร้าย...",
  ui_story_5053_50530801_76_dialog_content = "ร้องไห้ได้...ถ้าอยาก...",
  ui_story_5053_50530801_77_dialog_content = "แม่...อยู่นี่...",
  ui_story_5053_50530801_78_dialog_content = "...",
  ui_story_5053_50530801_79_dialog_content = "อ้อมกอดอันอบอุ่นของเธอ...และเพลงกล่อมเด็กเมื่อกี้นี้...",
  ui_story_5053_50530801_80_dialog_content = "เป็นคุณจริงๆแม่...",
  ui_story_5053_50530801_81_dialog_content = "ฉันคิดถึงคุณมาก...",
  ui_story_5053_50530801_82_dialog_content = "เช่นเดียวกับฉัน...ที่รัก...",
  ui_story_5053_50530801_83_dialog_content = "(The Dark Angel... เธอกำลังปลอบ Mia?!)",
  ui_story_5053_50530801_84_dialog_content = "(แต่ฉันคิดว่าเธอเป็นแค่สัตว์ประหลาดไร้สติ! ไม่ เดี๋ยวก่อน... โจชัวเป็นคนพูดแบบนั้น และไม่มีอะไรที่เธอพูดจะเชื่อถือได้)",
  ui_story_5053_50530801_85_dialog_content = "... คุณสบายดีไหม Mia? คุณยังยืนหยัดอยู่ได้ไหม",
  ui_story_5053_50530801_86_dialog_content = "PlayerName... ฉันขอโทษ ฉันควบคุมตัวเองไม่ได้ในตอนนี้",
  ui_story_5053_50530801_87_dialog_content = "ฉันไม่ได้ทำร้ายเธอใช่ไหม ฉัน...?",
  ui_story_5053_50530801_88_dialog_content = "ไม่แน่นอน! ดู? ฉันสบายดี และดูเหมือนว่าคุณก็สบายดีเช่นกัน",
  ui_story_5053_50530801_89_dialog_content = "ดังนั้นการจัดการกับ Dark Angel นี้เป็นอย่างไร ตอนนี้ฉันหายดีแล้ว...",
  ui_story_5053_50530801_90_dialog_content = "เธอเป็นแม่ของฉันไม่ต้องสงสัยเลย",
  ui_story_5053_50530801_91_dialog_content = "คุณกำลังบอกว่านี่คือ Lady Joshua ตัวจริง...?!",
  ui_story_5053_50530801_92_dialog_content = "ฉันรู้ว่ามันเข้าใจยาก แต่ใจฉันบอกว่าเธอคือแม่ที่แท้จริงของฉัน...",
  ui_story_5053_50530801_93_dialog_content = "อีกคนหนึ่งบอกเราว่า Dark Angel ไม่มีความรู้สึกผิดชอบชั่วดีและมีอยู่เพื่อทำลายเท่านั้น... แต่อ้อมกอดของเธอตอนนี้บอกฉันเป็นอย่างอื่น",
  ui_story_5053_50530801_94_dialog_content = "สำหรับแม่ที่เราพบในคฤหาสน์ ฉันมักจะรู้สึกบางอย่างที่ไม่คุ้นเคยเกี่ยวกับตัวเธอ...",
  ui_story_5053_50530801_95_dialog_content = "... ไม่ ฉันเข้าใจอย่างถ่องแท้ ในความเป็นจริงสิ่งนี้จะตอบคำถามมากมาย",
  ui_story_5053_50530801_96_dialog_content = "ฮะ? คุณหมายความว่าอย่างไร, PlayerName?",
  ui_story_5053_50530801_97_dialog_content = "ไม่มีเวลามากพอที่จะอธิบายในตอนนี้ Jakine ตกอยู่ในอันตรายร้ายแรง และเราต้องไปช่วยเธอ",
  ui_story_5053_50530801_98_dialog_content = "ฉันจะบอกคุณเพิ่มเติมเกี่ยวกับวิธีการ!",
  ui_story_5053_50530801_99_dialog_content = "จาคีน? ฉันไม่คิดว่าคุณไม่มีอะไรต้องกังวล ลุงเคเลบก็อยู่กับเธอ",
  ui_story_5053_50530801_100_dialog_content = "คาเลบอยู่กับเธอ?",
  ui_story_5053_50530801_101_dialog_content = "ถูกตัอง. พ่อบอกให้เขาอยู่ข้างหลัง แต่ฉันไม่แน่ใจว่าทำไม",
  ui_story_5053_50530801_102_dialog_content = "ไม่ว่าเหตุผลของเขาจะไม่สร้างความแตกต่างกับ Caleb ที่นั่น",
  ui_story_5053_50530801_103_dialog_content = "โจชัวจากคฤหาสน์กำลังวางแผนที่จะฆ่าพวกเราทุกคน เธอไม่สามารถเชื่อถือได้",
  ui_story_5053_50530801_104_dialog_content = "ว-คุณกำลังพูดถึงอะไร?!",
  ui_story_5053_50530801_105_dialog_content = "นี่ไม่ใช่ครั้งแรกที่ทั้งหมดนี้เกิดขึ้น Mia!",
  ui_story_5053_50530801_106_dialog_content = "!!!",
  ui_story_5053_50530801_107_dialog_content = "คาเลบ... อันตราย...",
  ui_story_5053_50530801_108_dialog_content = "ม... พี่ชายของฉัน... คาเลบ...",
  ui_story_5053_50530801_109_dialog_content = "พี่...อันตราย...",
  ui_story_5053_50530801_110_dialog_content = "คุณกำลังบอกว่าการรีเซ็ตอีกครั้งเกิดขึ้นหลังจากครั้งแรกใช่ไหม",
  ui_story_5053_50530801_111_dialog_content = "งั้นเราต้องตามหาพ่อให้เจอแล้วรีบกลับ!!",
  ui_story_5053_50530801_112_dialog_content = "พ่อ!",
  ui_story_5053_50530801_113_dialog_content = "ลอร์ด Schwartz, Caleb และ Jakine ตกอยู่ในอันตรายร้ายแรง! รีบไปฉันจะอธิบายทุกอย่างระหว่างทาง!",
  ui_story_5053_50530801_114_dialog_content = "ช...ชวาร์ตซ...",
  ui_story_5053_50530801_115_dialog_content = "... ดูเหมือนว่าสิ่งต่าง ๆ จะซับซ้อนกว่าที่ฉันคิดไว้",
  ui_story_5053_50530801_116_dialog_content = "น่าเสียดาย ฉันไม่มีทางออกจากที่นี่ได้ในตอนนี้",
  ui_story_5053_50530801_117_dialog_content = "มังกรจะรักษาบาดแผลใดๆ ที่เกิดขึ้นทันที แม้กระทั่งบาดแผลที่เจ็บปวดที่สุด",
  ui_story_5053_50530801_118_dialog_content = "ฉันสามารถอธิบายลักษณะที่เป็นลางร้ายนี้ว่าเป็นความคงกระพันประเภทหนึ่งเท่านั้น",
  ui_story_5053_50530801_119_dialog_content = "หนึ่งเดียวในโลกที่สร้างขึ้นโดย Crystal of Eternal Memory",
  ui_story_5053_50530801_120_dialog_content = "แต่นี่จะเป็นไปได้อย่างไร...?",
  ui_story_5053_50530801_121_dialog_content = "ฉันคิดว่าโจชัวอีกคนต้องมีบางอย่างที่เกี่ยวข้อง ลอร์ดชวาร์ตษ์ คุณช่วยปัดเป่ามังกรต่อไปได้ไหม?",
  ui_story_5053_50530801_122_dialog_content = "โจชัว... ถ้าอย่างนั้นก็ดี ฉันจะฝากที่เหลือไว้ในมือคุณ",
  ui_story_5053_50530801_123_dialog_content = "เวโรนิก้า? ทำไมไม่หลบมังกรล่ะ! แล้วคนพวกนี้คือใคร...?",
  ui_story_5053_50530801_124_dialog_content = "...",
  ui_story_5053_50530801_125_dialog_content = "ท่านพ่อ... ข้ามีเรื่องด่วนที่ต้องทำที่คฤหาสน์ โปรดอย่าพยายามที่จะหยุดฉัน",
  ui_story_5053_50530801_126_dialog_content = "ไม่มีอะไรจะเร่งด่วนไปกว่าสถานการณ์ปัจจุบันของเรา เวโรนิก้า",
  ui_story_5053_50530801_127_dialog_content = "ยิ่งไปกว่านั้น ฉันห้ามไม่ให้คุณยุ่งเกี่ยวกับคนแปลกหน้าเหล่านี้",
  ui_story_5053_50530801_128_dialog_content = "ข้าแทบจะไม่ถือว่าเราเป็นคนแปลกหน้า เจ้าเมือง เนื่องจากเราต่อสู้อยู่ข้างเดียวกันมาระยะหนึ่งแล้ว",
  ui_story_5053_50530801_129_dialog_content = "นี่ไม่ใช่เวลาหรือสถานที่สำหรับข้อเรียกร้องของบิดา",
  ui_story_5053_50530801_130_dialog_content = "...",
  ui_story_5053_50530801_131_dialog_content = "วางใจได้ในฐานะพันธมิตรของเวโรนิกา PlayerName และฉันสาบานว่าจะปกป้องเธอทุกวิถีทาง",
  ui_story_5053_50530801_132_dialog_content = "คุณมีหน้าที่ต้องปกป้องผู้คนใน Lumopolis และตอนนี้พวกเขาต้องการคุณมากกว่าที่เคย",
  ui_story_5053_50530801_133_dialog_content = "เพียงพอ. เพื่อนร่วมงานของฉัน คุณร็อต มีความสามารถมากกว่าที่จะปกป้องครอบครัวของฉัน และภรรยาของฉันก็ไม่ใช่คนแปลกหน้าที่จะต่อสู้เช่นกัน เราแทบไม่ต้องการการปกป้องจากภายนอก น้อยกว่ามากจากคนแปลกหน้าทั้งหมด",
  ui_story_5053_50530801_134_dialog_content = "นอกจากนี้ ฉันไม่มีเหตุผลที่จะไว้วางใจกลุ่มที่นับสัตว์ประหลาดเป็นหนึ่งในกลุ่มของพวกเขาเอง",
