  ui_story_5053_50530901_14_dialog_content = "แน่นอน! ท้ายที่สุด แม้แต่แม่กุญแจธรรมดาก็สร้างความปลอดภัยให้กับเราได้อย่างมหัศจรรย์!",
  ui_story_5053_50530901_15_dialog_content = "ให้ฉันถามคำถามคุณ คาเลบ ทำไมคุณถึงต้องการช่วยฉัน",
  ui_story_5053_50530901_16_dialog_content = "อืม? เพราะคุณเป็นน้องสาวของฉันแน่นอน! พี่ชายคนไหนไม่อยากช่วยน้องสาวของตัวเอง?",
