  ui_story_5053_50530901_19_dialog_content = "สิ่งเหล่านั้นจะไม่มีวันเปลี่ยนแปลง ไม่ว่าจะผ่านไปกี่ปีฉันก็ยังรู้สึกแบบนี้เสมอ",
