  ui_story_5053_50530901_21_dialog_content = "คุณทำได้ดีมาก คาเลบ",
  ui_story_5053_50530901_22_dialog_content = "โจชัว...!",
  ui_story_5053_50530901_23_dialog_content = "จริงอยู่ว่าโลกเป็นสถานที่ที่เปลี่ยนแปลงตลอดเวลา แต่ก็มีบางสิ่งที่แม้แต่กาลเวลาก็เปลี่ยนแปลงไม่ได้...",
  ui_story_5053_50530901_24_dialog_content = "บอกฉันว่า Lumopolis เป็นอย่างไรหลังจากผ่านไปสิบสองปี",
  ui_story_5053_50530901_25_dialog_content = "ไม่มีอะไรเปลี่ยนแปลง. ขุนนางกาฝากเหล่านั้นดื้อรั้นและไร้ยางอายเช่นเคย",
  ui_story_5053_50530901_26_dialog_content = "หลังจากอ้วนพีบนความรุ่งโรจน์ของลูโมโปลิสแล้ว สิ่งที่เหลืออยู่ก็คือระบบที่เน่าเปื่อยซึ่งปกคลุมด้วยแผ่นไม้อัดที่บางที่สุดเท่านั้น",
