  ui_story_5053_50530901_31_dialog_content = "เมื่อถึงจุดนี้ เขาสามารถต่อสู้กับขุนนางที่ฉ้อฉลจนแทบสิ้นลมหายใจ และยังคงไม่มีอะไรเปลี่ยนแปลง",
