  ui_story_5053_50530901_34_dialog_content = "ฉันคิดว่าลอร์ดชวาร์ตษ์สมควรได้รับเครดิตมากกว่านั้น แม้ว่าพวกนักเขียนโค้ดผู้สูงศักดิ์เหล่านั้นจะวางแผนต่อต้านเขาอยู่ตลอดเวลา แต่เขาก็ยังคงรักษาภาพลักษณ์อันมีเกียรติในสายตาของสาธารณชน",
  ui_story_5053_50530901_35_dialog_content = "คุณจะรู้อะไรเกี่ยวกับการทำงานภายในของ Lumopolis, Jakine? สิ่งเดียวที่คุณและคนทั้งโลกสามารถเห็นได้คือสิ่งที่เรียกว่า \"รูปลักษณ์ที่น่ายกย่อง\" ของเขา",
  ui_story_5053_50530901_36_dialog_content = "B-แต่แม้แต่ราชินีเบธเลเฮมก็ยังคิดว่า... หึ ไม่เป็นไร! ฉันจะคุยกับยาม!",
  ui_story_5053_50530901_37_dialog_content = "แล้วฉันล่ะ คาเลบ? คุณมองว่าฉันล้มเหลวในการเลือกดาเนียลเป็นสามีหรือไม่?",
  ui_story_5053_50530901_38_dialog_content = "N-ไม่เลย! คุณเป็นเหยื่ออีกคนของการโกหกที่ยิ่งใหญ่ของชวาร์ตษ์!",
  ui_story_5053_50530901_39_dialog_content = "และถ้า... จำไว้นะ นี่เป็นเรื่องสมมุติล้วน ๆ แต่ถ้าคุณจะทิ้งเขาไว้... บ้านของเราจะเปิดรอคุณเสมอ",
  ui_story_5053_50530901_40_dialog_content = "และถ้าคุณเบื่อ Lumopolis และความสกปรกของมัน เราก็ไปอยู่ที่อื่นก็ได้!",
  ui_story_5053_50530901_41_dialog_content = "นั่นไม่จำเป็น คาเลบ ฉันไม่มีความตั้งใจที่จะทิ้ง Lumopolis ให้เน่าเปื่อย ฉันจะเปลี่ยนเมืองนี้ภายในชั่วชีวิตของฉัน ถ้านั่นคือสิ่งสุดท้ายที่ฉันทำ",
