  ui_story_5053_50530901_46_dialog_content = "ดูเหมือนว่าความพยายามของเราที่จะเลี้ยงดูคุณไม่ได้ไร้ประโยชน์แต่อย่างใด",
  ui_story_5053_50530901_47_dialog_content = "ของเรา? โยชูวา เจ้ากำลังพูดถึงบิดาของเราหรือ? เขาต้องทำอย่างไรกับเรื่องนี้? แล้วทำไมถึงพูดแบบนั้น...?",
  ui_story_5053_50530901_48_dialog_content = "ดูเหมือนว่าถึงเวลาที่จะต้องบอกความจริงกับคุณแล้ว คาเลบ ยามจับเธอ",
  ui_story_5053_50530901_49_dialog_content = "...",
