  ui_story_5053_50530901_52_dialog_content = "คาเลบ... <color=#FFB400>ฉันไม่ใช่น้องสาวของคุณโดยสายเลือด</color>.",
  ui_story_5053_50530901_53_dialog_content = "หา...?",
  ui_story_5053_50530901_54_dialog_content = "หลายปีก่อน ครอบครัวของฉันปฏิเสธที่จะยอมจำนนต่อ House Schwartz และการปกครองแบบเผด็จการ เป็นผลให้ครอบครัวของฉันถูกกำจัดโดยพ่อของดาเนียลซึ่งเป็นเจ้าเมืองคนก่อน",
  ui_story_5053_50530901_55_dialog_content = "ครอบครัวอื่น ๆ อีกมากมายมีส่วนร่วมในชะตากรรมของเราเช่นกัน มีเพียงไม่กี่คนเท่านั้นที่รอดชีวิต และตอนนั้นฉันยังเป็นเด็ก",
  ui_story_5053_50530901_56_dialog_content = "พวกเราทุกคนมาเพื่อดูถูก House Schwartz และเราสาบานว่าจะล้างแค้นพวกเขาทุกคน",
  ui_story_5053_50530901_57_dialog_content = "ในที่สุดฉันก็หาทางเข้าไปในสวนลุมโปลิสจนได้ ตระกูลขุนนางที่สูญเสียลูกสาวไปเพราะการปกครองแบบเผด็จการของ Schwartz ยอมรับฉันในฐานะของพวกเขาเอง",
  ui_story_5053_50530901_58_dialog_content = "เดี๋ยวก่อน... ครอบครัวที่ปลิดชีพ... ใคร <color=#FFB400>เสียลูกสาวให้ชวาร์ตษ์</color>...",
  ui_story_5053_50530901_59_dialog_content = "ถูกต้องมันเป็น <color=#FFB400>โจชัว</color>, พี่ - น้องสาวของคุณ. น้องสาวต่างสายเลือดและแม่ของคุณถูกฆ่าตายไปนานแล้ว",
  ui_story_5053_50530901_60_dialog_content = "พวกเขาไม่เคยทะเลาะกับเฮาส์ชวาร์ตษ์เลย พวกเขาแค่ไปเยี่ยมเพื่อน ซึ่งเป็นศัตรูทางการเมืองของ Schwartz ซึ่งครอบครัวของเขาถูกหมายหัวให้กำจัด",
  ui_story_5053_50530901_61_dialog_content = "...แล้วพ่อรู้เรื่องนี้ไหม...?",
  ui_story_5053_50530901_62_dialog_content = "แน่นอนเขาทำ พ่อของคุณเป็นคนขอให้ฉันรับตำแหน่งแทนลูกสาวของเขา และหาทางแก้แค้นเฮาส์ชวาร์ตษ์",
  ui_story_5053_50530901_63_dialog_content = "ฉันเป็นไปไม่ได้! ผู้ชายที่ใจดีและซื่อสัตย์อย่างพ่อของฉันจะ...",
  ui_story_5053_50530901_64_dialog_content = "ความเกลียดชังสามารถผลักดันให้แม้แต่คนที่มีความเห็นอกเห็นใจมากที่สุดให้ทำสิ่งชั่วร้าย คาเลบ",
  ui_story_5053_50530901_65_dialog_content = "การแก้แค้นไม่ใช่ความรักที่กระตุ้นให้เราเลี้ยงดูคุณให้เป็นผู้ชายที่คุณเป็นในวันนี้",
  ui_story_5053_50530901_66_dialog_content = "เมื่อความพยายามลอบสังหารพ่อของคุณจบลงด้วยความล้มเหลว เขาปลิดชีวิตตัวเองไม่ใช่แค่เพื่อปกป้องพวกเรา แต่เพื่อปกป้องการแก้แค้น",
  ui_story_5053_50530901_67_dialog_content = "เมื่อหลายปีก่อนฉันเห็นความจริงใจของแดเนียล ฉันให้โอกาสเขาครั้งสุดท้ายที่จะเปลี่ยนแปลงเฮาส์ชวาร์ตษ์และลูโมโพลิสให้ดีขึ้น",
  ui_story_5053_50530901_68_dialog_content = "ฉันให้การสนับสนุนอย่างไม่ย่อท้อแก่เขาในการรณรงค์เพื่อขึ้นเป็นเจ้าเมืองคนต่อไป",
  ui_story_5053_50530901_69_dialog_content = "ฉันบอกตัวเองว่าฉันดีกว่าพ่อของเขา ว่าฉันจะไม่ทำตัวต่ำขนาดฆ่าคนบริสุทธิ์เพียงเพื่อให้มีทางของฉัน",
  ui_story_5053_50530901_70_dialog_content = "แต่ฉันคิดผิด แดเนียลไร้ความสามารถเกินกว่าจะเปลี่ยนแปลงอะไรได้ ฉันจึงตระหนักว่าถึงเวลาแล้วที่เฮาส์ชวาร์ตษ์จะต้องทนรับความโกรธเกรี้ยวของเรา",
  ui_story_5053_50530901_71_dialog_content = "เคเลบ กำจัดทิ้ง <color=#FFB400>จาคีน</color>.",
  ui_story_5053_50530901_72_dialog_content = "... อะไร? คุณกำลังพูดอะไรโจชัว!",
  ui_story_5053_50530901_73_dialog_content = "ฉันต้องการ Lumina จากคนนอกเพื่อออกจากที่นี่ ฉันยังมีจุดประสงค์ที่จะเติมเต็มที่นั่น",
  ui_story_5053_50530901_74_dialog_content = "ไม่ โจชัว... จาคีนไม่มีส่วนเกี่ยวข้องกับเรื่องนี้! คุณพูดเอง คุณไม่เต็มใจที่จะฆ่าคนบริสุทธิ์เพื่อหาทางของคุณ!",
  ui_story_5053_50530901_75_dialog_content = "การตายของเธอคือการเสียสละที่จำเป็น",
  ui_story_5053_50530901_76_dialog_content = "อะไรนะ... เสียสติไปแล้วเหรอ?! เกิดอะไรขึ้นกับเลดี้โจชัวผู้อ่อนหวานและอ่อนโยนก่อนหน้านี้!",
  ui_story_5053_50530901_77_dialog_content = "ฉันอยากจะถามในสิ่งเดียวกัน! คุณเลี้ยงดูฉันมาไม่ใช่เพราะความรัก แต่เพื่อการล้างแค้น... ฉันไม่เคยได้ยินเรื่องน่าหัวเราะกว่านี้มาก่อนในชีวิต! Jakine แน่ใจนะว่าคนนี้ไม่ใช่แค่ภาพลวงตา?!",
  ui_story_5053_50530901_78_dialog_content = "ไม่ใช่เธอหรอก เชื่อฉันสิ! และฉันก็ไม่ได้ร่ายมนตร์ใส่เธอด้วย!",
  ui_story_5053_50530901_79_dialog_content = "คุณจะเพิกเฉยต่อความจริงไปอีกนานแค่ไหน คาเลบ? คุณต้องการให้การเสียสละของครอบครัวของคุณไร้ประโยชน์หรือไม่?",
  ui_story_5053_50530901_80_dialog_content = "...",
  ui_story_5053_50530901_81_dialog_content = "ไม่เป็นไร ฉันจัดการจาคีนเองได้ ดูเหมือนเราจะล้มเหลวในการให้ความรู้แก่คุณอย่างละเอียด Caleb",
  ui_story_5053_50530901_82_dialog_content = "ฉันจะให้โอกาสครั้งสุดท้ายแก่คุณในการพิสูจน์ความตั้งใจของคุณ เมื่อถึงเวลา คุณต้องกำจัดชวาร์ตษ์พร้อมกับคนอื่นๆ",
  ui_story_5053_50530901_83_dialog_content = "อ๊าก ปล่อยฉันนะ! บ้าไปแล้วถ้าคิดจะฆ่าพวกเราให้หมด!!!",
  ui_story_5053_50530901_84_dialog_content = "คุณไม่มีใครตำหนินอกจากชวาร์ตษ์ ลาก่อน ทูตแห่งนอร์ธแลนด์",
  ui_story_5053_50530901_85_dialog_content = "<color=#e8d9bb>ฟิ้วว—</color>",
  ui_story_5053_50530901_86_dialog_content = "... คุณพูดถูก โจชัว แม้ว่าพวกคุณหลายคนจะไม่คุ้นเคยกับฉัน แต่ก็ปฏิเสธไม่ได้ว่าคุณคือน้องสาวที่รักของฉัน",
  ui_story_5053_50530901_87_dialog_content = "เพราะเหตุใดข้าจึงต้องหยุดเจ้า! ฉันจะไม่ปล่อยให้คุณอยู่กับความเสียใจในการทำสิ่งที่เลวร้าย!",
  ui_story_5053_50530901_88_dialog_content = "เสียใจ? ฉันไม่เคยเสียใจอะไรเลยสักครั้ง ฉันเลือกที่จะเลี้ยงดูคุณแทนพ่อที่ขี้ขลาดของคุณ เพื่อที่คุณจะได้สืบทอดความปรารถนาที่จะล้างแค้นของเรา",
  ui_story_5053_50530901_89_dialog_content = "อึก...!",
  ui_story_5053_50530901_90_dialog_content = "แต่คุณกลับเลือกที่จะหักหลังฉัน...เหมือนกับคนอื่นๆ!!!",
  ui_story_5053_50530901_91_dialog_content = "ไม่ โจชัว... ฉันไม่มีวันทรยศคุณ!",
  ui_story_5053_50530901_92_dialog_content = "ฮึ่ม คุณจัดการปลดอาวุธฉันได้แล้ว... แต่เล่ห์เหลี่ยมเล็กๆ น้อยๆ จะไม่ช่วยคุณตอนนี้!",
  ui_story_5053_50530901_93_dialog_content = "ถ้าพูดกันตามตรง ฉันมีเรื่องจะสารภาพด้วย หลายปีที่ผ่านมา ฉันเคยพูดว่าชวาร์ตษ์ไม่คู่ควรกับคุณ แต่ความจริงก็คือ...",
  ui_story_5053_50530901_94_dialog_content = "ฉันไม่พอใจเขา! ฉันแค้นผู้ชายคนนั้นและลูก ๆ ที่คุณให้กำเนิดเขาเพราะพวกเขาพรากคุณไปจากฉัน! พวกเขาพรากครอบครัวเดียวที่ฉันเหลืออยู่ในโลกนี้ไป!",
  ui_story_5053_50530901_95_dialog_content = "ฉันไม่สนหรอกว่าเราจะไม่เกี่ยวข้องกันทางสายเลือด... คุณเลี้ยงฉันตั้งแต่เด็กจนโต และคุณจะเป็นน้องสาวที่รักของฉันตลอดไป!",
  ui_story_5053_50530901_96_dialog_content = "ดูเหมือนว่าคุณจะไม่เป็นอะไรมากไปกว่าเด็กขี้แย เรียกร้องความสนใจจากน้องสาวของเขา ออกไปให้พ้นทางของฉันเดี๋ยวนี้!",
  ui_story_5053_50530901_97_dialog_content = "ถูกตัอง! และฉันจะไม่มีวันเปลี่ยน ไม่ว่าคุณจะเยาะเย้ยฉันมากแค่ไหนก็ตาม!",
  ui_story_5053_50530901_98_dialog_content = "แต่ฉันรู้... ฉันรู้ว่าคุณรักสามีและลูกสาวของคุณมากแค่ไหน ไม่มีอะไรที่ฉันเคยเปลี่ยนได้!",
  ui_story_5053_50530901_99_dialog_content = "บอกแล้วว่ามันคือการแสดง!!",
  ui_story_5053_50530901_100_dialog_content = "ฉัน... ฉันขอโทษ โจชัว แต่ฉันปฏิเสธที่จะเชื่ออย่างนั้น",
  ui_story_5053_50530901_101_dialog_content = "และฉันปฏิเสธที่จะปล่อยให้คุณทำสิ่งนี้ ฉันจะปกป้องครอบครัวอันมีค่าของคุณ แม้ต้องแลกด้วยชีวิตของฉันเอง!",
  ui_story_5053_50530901_102_dialog_content = "เอาล่ะ ถ้าอย่างนั้นทั้งชีวิตของคุณและ Lumina ของคุณก็จะสูญเสียไป",
  ui_story_5053_50530901_103_dialog_content = "เอ่อ...?!",
