  ui_story_5053_50530901_135_dialog_content = "?!",
  ui_story_5053_50530901_136_dialog_content = "โอ้ เจ้าสิ่งมีชีวิตที่น่าขยะแขยง ปรากฏตัวในเวลาเช่นนี้...!",
