  ui_story_5053_50530901_139_dialog_content = "ค... คาเลบ...!!",
  ui_story_5053_50530901_140_dialog_content = "เฮ้... ฆ่าฉันด้วยการโจมตีเพียงครั้งเดียว... ยังไงซะ ก็ยังมีความเมตตาอยู่ในใจเธออยู่ดี...",
