  ui_story_5053_50530901_157_dialog_content = "<size=50>หราาาาาาาาาาาาาาาา!!!</size>",
  ui_story_5053_50531001_1_dialog_content = "แฮ่ก... แฮ่ก...",
  ui_story_5053_50531001_2_dialog_content = "คุณสบายดีไหม PlayerName? เราสามารถหยุดและพักผ่อนได้หากต้องการ",
  ui_story_5053_50531001_3_dialog_content = "ฉันสบายดี ไม่ต้องกังวล ฉันแค่กังวลเพราะตอนนี้ Dark Angel บินออกไปอย่างรวดเร็ว",
  ui_story_5053_50531001_4_dialog_content = "เธออยู่กับเราตลอดเวลา แต่ทันใดนั้นเธอก็บินออกไปราวกับว่าเธอรู้สึกผิด...",
  ui_story_5053_50531001_5_dialog_content = "เธอเคยทำแบบเดียวกันนี้มาก่อน เมื่อเธอรู้สึกว่าคุณตกอยู่ในอันตราย ฉันเริ่มกังวลเกี่ยวกับ Jakine และ Caleb จริงๆ",
  ui_story_5053_50531001_6_dialog_content = "เราเกือบจะถึงแล้ว! หวังว่าพวกเขาจะยังโอเค...",
  ui_story_5053_50531001_7_dialog_content = "มีอา คุณแน่ใจหรือว่าจาคีนจำอะไรเกี่ยวกับการรีเซ็ตครั้งที่สองไม่ได้",
  ui_story_5053_50531001_8_dialog_content = "ฉันแน่ใจว่ามัน พวกเราไม่มีใครจำได้ว่ามันเคยเกิดขึ้น... นั่นคือเหตุผลที่เราเชื่อทุกอย่างที่ Joshua คนอื่นบอกเรา",
  ui_story_5053_50531001_9_dialog_content = "พูดตามตรง ฉันยังไม่ค่อยเชื่อเรื่องราวของคุณเอง PlayerName...",
  ui_story_5053_50531001_10_dialog_content = "เลย...ต้องไปเห็นความจริงด้วยตัวเอง!",
  ui_story_5053_50531001_11_dialog_content = "(แล้วทำไมฉันถึงจำทุกอย่างได้ ทั้งๆที่ Jakine จำไม่ได้ มันไม่สมเหตุสมผลเลย...)",
  ui_story_5053_50531001_12_dialog_content = "มีบางอย่างรู้สึกไม่ถูกต้อง ยามทั้งหมดอยู่ที่ไหน?",
  ui_story_5053_50531001_13_dialog_content = "รู้สึกเหมือนพื้นสั่นสะเทือน...เมียจ๋า ระวัง!!",
  ui_story_5053_50531001_14_dialog_content = "?!",
  ui_story_5053_50531001_15_dialog_content = "ผู้บุกรุก! คนทรยศ! ตาย-!",
  ui_story_5053_50531001_16_dialog_content = "อ๊าก—!!!",
  ui_story_5053_50531001_17_dialog_content = "ตาย! ตาย! ตาย!",
  ui_story_5053_50531001_18_dialog_content = "ไม่ใช่ยามบ้าๆ พวกนั้นอีกแล้ว!",
  ui_story_5053_50531001_19_dialog_content = "อื้อหือ!!! ใครก็ได้ช่วยฉันที!!!",
  ui_story_5053_50531001_20_dialog_content = "นั่นมัน... จากิน?!",
  ui_story_5053_50531001_21_dialog_content = "ยามตามเธอ! เราต้องฝ่าฟันฝูงชนนี้ไปให้ได้ Mia!",
  ui_story_5053_50531001_22_dialog_content = "มีมากเกินไป! ฮิปโป-",
