  ui_story_5053_50531001_25_dialog_content = "<color=#e8d9bb>ฟิ้วว—</color>",
  ui_story_5053_50531001_26_dialog_content = "เอิ๊ก...!!",
  ui_story_5053_50531001_27_dialog_content = "อ๊าาาาาาาา!!!",
  ui_story_5053_50531001_28_dialog_content = "(คุณบลองก์?! เหลือเชื่อมาก! เธอเต้นผ่านกลุ่มผู้คุมทั้งหมดและพาพวกเขาออกไป!)",
  ui_story_5053_50531001_29_dialog_content = "น้องร็อต! ข้างหลังคุณ!",
  ui_story_5053_50531001_30_dialog_content = "ไม่ต้องกังวลตัวเองเจ้าหญิงเวโรนิกา",
  ui_story_5053_50531001_31_dialog_content = "ในฐานะสมาชิกของ Nightwatch หน้าที่ของฉันคือป้องกันไม่ให้ใครก็ตามมาทำให้ Lumopolis เป็นมลทิน",
  ui_story_5053_50531001_32_dialog_content = "จะไม่มีใครขัดขวางความสงบเรียบร้อยของ Lumopolis ภายใต้การดูแลของฉัน!",
  ui_story_5053_50531001_33_dialog_content = "ขอเทิดทูนรัตติกาลสีขาว!",
  ui_story_5053_50531001_34_dialog_content = "ฮึ-!!",
  ui_story_5053_50531001_35_dialog_content = "ย๊ากกก!!",
  ui_story_5053_50531001_36_dialog_content = "เจ้าหญิงเวโรนิก้า คุณจาคีน คุณเจ็บไหม?",
