  ui_story_5053_50531001_38_dialog_content = "คุณมาทันเวลาพอดี ฉันไม่คิดว่าเราจะชนะได้ถ้าไม่มีคุณ คุณร็อต",
  ui_story_5053_50531001_39_dialog_content = "เกิดอะไรขึ้นในโลกนี้ ฝ่าบาท? ยามเหล่านี้ไม่ได้ทำตัวเหมือนกบฏทั่วไป",
