  ui_story_5053_50531002_158_dialog_content = "ฉันรู้ว่าตอนนี้เรากำลังแบกรับอะไรมากมายไว้บนบ่าของคุณ ฉันคงประหม่าถ้าต้องทำทุกอย่างด้วยตัวเองเหมือนกัน แต่อย่ากลัวไปเลย",
  ui_story_5053_50531002_159_dialog_content = "ทุกอย่างจะโอเค เราเชื่อคุณไม่ว่าจะเกิดอะไรขึ้น!",
  ui_story_5053_50531002_160_dialog_content = "จากิน...!",
  ui_story_5053_50531002_161_dialog_content = "ขวา! แค่ปล่อยให้ฉัน!",
  ui_story_5053_50531002_162_dialog_content = "เรดดิตัส เรดดิตัส เรดดิตัส! ให้ทุกอย่างกลับมาเป็นเหมือนเดิม!",
  ui_story_5053_50531002_163_dialog_content = "อะบราคาดาบร้า!",
  ui_story_5053_50531101_0X_dialog_content = "<color=#e8d9bb>หลังจากรีเซ็ตครั้งที่สาม—</color>",
  ui_story_5053_50531101_1_dialog_content = "ทุกอย่างพร้อมแล้วเจ้านายของฉัน",
  ui_story_5053_50531101_2_dialog_content = "รถม้ารออยู่ข้างนอกและพร้อมออกเดินทางได้ทุกเมื่อ",
  ui_story_5053_50531101_3_dialog_content = "เข้าใจแล้ว",
  ui_story_5053_50531101_4_dialog_content = "ขึ้นรถม้า คาร์ลีน",
  ui_story_5053_50531101_5_dialog_content = "ฉัน... ฉันอยากอยู่ข้างหลังกับแม่!",
  ui_story_5053_50531101_6_dialog_content = "Jakine... Mia... ฉันต้อง...",
  ui_story_5053_50531101_7_dialog_content = "อืมม... ฉันอยู่ที่ไหน...?",
  ui_story_5053_50531101_8_dialog_content = "ถูกต้อง Jakine ส่งฉันย้อนเวลาอีกครั้ง!",
  ui_story_5053_50531101_9_dialog_content = "และตรงนั้น... ตัวตนที่อายุน้อยกว่าของ Lord Schwartz กำลังพา Carleen ออกจากที่นี่",
  ui_story_5053_50531101_10_dialog_content = "ดูเหมือนว่าการรีเซ็ตจะสำเร็จ!",
  ui_story_5053_50531101_11_dialog_content = "เอาล่ะ สิ่งแรกก่อน ...",
  ui_story_5053_50531101_12_dialog_content = "บุคคลต้องสงสัย...ต้องกำจัด...",
  ui_story_5053_50531101_13_dialog_content = "บุคคลน่าสงสัย...ไม่อยู่...",
  ui_story_5053_50531101_14_dialog_content = "วุ้ย ฉันหลบทหารยามได้! ที่ดูแลสิ่งนั้น!",
  ui_story_5053_50531101_15_dialog_content = "(ก่อนที่จะรีเซ็ต เราสามคนได้วางแผนสามขั้นตอนเพื่อพาเราออกจากที่นี่)",
  ui_story_5053_50531101_16_dialog_content = "(ขั้นแรก หา Dark Angel และเกลี้ยกล่อมให้เธอต่อสู้ฝ่ายเรา)",
  ui_story_5053_50531101_17_dialog_content = "(จากนั้นป้องกันมังกรและผู้คุ้มกันที่ติดเชื้อไม่ให้โจมตี)",
  ui_story_5053_50531101_18_dialog_content = "(สุดท้าย กำจัด White Demon ก่อนที่คนอื่นจะได้รับบาดเจ็บหรือแย่กว่านั้น)",
  ui_story_5053_50531101_19_dialog_content = "(มีอา จาคีน...)",
  ui_story_5053_50531101_20_dialog_content = "(นี่คือการรีเซ็ตครั้งล่าสุดของเรา ฉันต้องดึงมันออก ไม่เช่นนั้นเราทุกคนก็ถึงวาระ)",
  ui_story_5053_50531101_21_dialog_content = "บุคคลต้องสงสัย...กำจัด...",
  ui_story_5053_50531101_22_dialog_content = "!!!",
  ui_story_5053_50531101_23_dialog_content = "ไม่อยู่ที่นี่...",
  ui_story_5053_50531101_24_dialog_content = "(นั่นเกือบจะแล้ว... จากการปะทะกับการ์ดเหล่านี้ไม่กี่ครั้ง พวกเขาจะไม่หยุดไล่ตามฉันจนกว่าจะถึงจุดจบ)",
  ui_story_5053_50531101_25_dialog_content = "(ฉันไม่ค่อยมีเวลา กำลังรบ และความคล่องตัว... ซึ่งหมายความว่าฉันจะต้องทำทั้งสามขั้นตอนให้เสร็จในคราวเดียว)",
  ui_story_5053_50531101_26_dialog_content = "(ฉันมีช็อตเดียวที่นี่!)",
  ui_story_5053_50531102_1_dialog_content = "<color=#e8d9bb>ตูมม!!!</color>",
  ui_story_5053_50531102_2_dialog_content = "อึก...ไอ ไอ...",
  ui_story_5053_50531102_3_dialog_content = "ดาร์กแองเจิ้ลไปไหน?",
  ui_story_5053_50531102_4_dialog_content = "ดูเหมือนว่าเธอจะหนีไปทางด้านนอก",
  ui_story_5053_50531102_5_dialog_content = "มันยอดเยี่ยมมาก ท่านชวาร์ตษ์!",
  ui_story_5053_50531102_6_dialog_content = "ฉันแค่ขอบคุณที่ไม่มีใครได้รับบาดเจ็บ—",
  ui_story_5053_50531102_7_dialog_content = "โอ้คุณทั้งหมด!",
  ui_story_5053_50531102_8_dialog_content = "แม่... มาทำอะไรที่นี่? คุณไม่ควรดูขบวนพาเหรดเหรอ?",
  ui_story_5053_50531102_9_dialog_content = "...",
  ui_story_5053_50531102_10_dialog_content = "... ดูเหมือนพวกเราจะมีแขกที่ไม่ต้อนรับ",
  ui_story_5053_50531102_11_dialog_content = "ทุกคนสบายดีไหม",
  ui_story_5053_50531102_12_dialog_content = "โจชัว? B-แต่ตอนนี้ Dark Angel...",
  ui_story_5053_50531102_13_dialog_content = "ฮี่ฮี่ ดังนั้นอัจฉริยะตัวน้อยของฉันก็มีช่วงเวลาที่สับสนเช่นกัน",
  ui_story_5053_50531102_14_dialog_content = "พวกเจ้าคงเหน็ดเหนื่อยจากการต่อสู้ เข้ามาข้างในและพักผ่อนใช่ไหม",
  ui_story_5053_50531102_15_dialog_content = "ไม่ต้องกังวลกับมอนสเตอร์ตัวนั้น ฉันจะส่งทหารออกไปตามล่ามันในไม่ช้า",
  ui_story_5053_50531102_16_dialog_content = "แม่คะ แป๊บเดียว มีอะไรผิดปกติ...",
  ui_story_5053_50531102_17_dialog_content = "มีใครเห็น PlayerName?",
  ui_story_5053_50531102_18_dialog_content = "โอ้ใช่! อยู่ไหน PlayerName? ฉันไม่เห็นเขาที่ไหนเลย",
  ui_story_5053_50531102_19_dialog_content = "เขาหายไปตลอดเวลา",
  ui_story_5053_50531102_20_dialog_content = "โอ้ว...",
  ui_story_5053_50531102_21_dialog_content = "ฉันขอโทษแม่ เราต้องไปหา PlayerName ก่อนที่เขาจะพบกับอันตรายใดๆ...",
  ui_story_5053_50531102_22_dialog_content = "ฉันรู้สึกอบอุ่นหัวใจที่ได้เห็นว่าคุณห่วงใยวอนนี่เพื่อนของคุณมากแค่ไหน... แต่ฉันมีบางสิ่งที่สำคัญมากที่จะแบ่งปันกับทุกคน",
  ui_story_5053_50531102_23_dialog_content = "ฉันจะส่งทีมองครักษ์ไปค้นหา PlayerName. เข้าไปข้างในกันก่อนไหม",
  ui_story_5053_50531102_24_dialog_content = "ฮะ? อืม...โอเค...",
  ui_story_5053_50531102_25_dialog_content = "... นั่นสินะ?",
  ui_story_5053_50531102_26_dialog_content = "มันไม่เหมือนคุณเลยที่จะพูดถึงสถานการณ์ชีวิตหรือความตายของบุคคลหนึ่งอย่างเมินเฉย",
  ui_story_5053_50531102_27_dialog_content = "โอ้? นั่นคือสิ่งที่คุณคิดกับฉัน? สตรีผู้สูงศักดิ์ธรรมดาผู้อ่อนแอ? แดเนียล",
  ui_story_5053_50531102_28_dialog_content = "...",
  ui_story_5053_50531102_29_dialog_content = "แดเนียล? แต่โจชัว คุณเป็นได้ยังไง!",
  ui_story_5053_50531201_1_dialog_content = "แฮ่ก ๆ...",
  ui_story_5053_50531201_2_dialog_content = "ฉันรู้ว่าฉันเห็นเธอไปทางนี้ แต่ทำไมฉันหาเธอไม่เจอ",
  ui_story_5053_50531201_3_dialog_content = "ช...วอร์ทซ์...",
  ui_story_5053_50531201_4_dialog_content = "ที่นั่น! เบื้องหลังลังนั้น!",
  ui_story_5053_50531201_5_dialog_content = "...!!!",
  ui_story_5053_50531201_6_dialog_content = "เดี๋ยวก่อน ฉันไม่อยากสู้กับนาย! Caleb และ Veronica กำลังตกอยู่ในอันตราย และพวกเขาต้องการความช่วยเหลือจากคุณ!",
  ui_story_5053_50531201_7_dialog_content = "คา... คาเลบ...? เวโรนิก้า...?",
  ui_story_5053_50531201_8_dialog_content = "ถูกตัอง! Caleb น้องชายของคุณ และลูกสาวของคุณ Veronica!",
  ui_story_5053_50531201_9_dialog_content = "พวกเขาคือครอบครัวของคุณใช่ไหม",
  ui_story_5053_50531201_10_dialog_content = "ครอบครัวของฉัน...",
  ui_story_5053_50531201_11_dialog_content = "ใช่ ครอบครัวของคุณ! และตอนนี้พวกเขากำลังตกอยู่ในอันตรายร้ายแรง!",
  ui_story_5053_50531201_12_dialog_content = "ครอบครัวของฉัน... ตกอยู่ในอันตราย...",
  ui_story_5053_50531201_13_dialog_content = "มีอะไรบางอย่างผิดปกติ...?",
  ui_story_5053_50531201_14_dialog_content = "<size=50>ของฉัน... ครอบครัว... ชวาร์ตซ!!!</size>",
  ui_story_5053_50531201_15_dialog_content = "ฮ-ห๊ะ?! เฮ้ เก็บมันไว้! คุณจะแจ้งเตือนยาม!",
  ui_story_5053_50531201_16_dialog_content = "(คราวที่แล้วเราบอกว่า Caleb ตกอยู่ในอันตราย เธอเต็มใจช่วยเรา ทำไมคราวนี้เธอถึงโกรธล่ะ?!)",
  ui_story_5053_50531201_17_dialog_content = "(เป็นไปได้ไหมที่ Dark Angel จะฟังเฉพาะ Mia หรือคนอื่นจากครอบครัวของเธอ?)",
  ui_story_5053_50531201_18_dialog_content = "ความเจ็บปวด...! อาการปวดมาก...!",
  ui_story_5053_50531201_19_dialog_content = "อา ไม่ดีเลย... ฉันหมดเวลาแล้ว! ฉันควรทำอย่างไรดี?!",
  ui_story_5053_50531201_20_dialog_content = "อย่าร้องไห้...",
  ui_story_5053_50531201_21_dialog_content = "อย่าร้องไห้... ที่รัก ตัวน้อยของฉัน... วอนนี่...",
  ui_story_5053_50531201_22_dialog_content = "ทุกอย่างจะ...โอเค...",
  ui_story_5053_50531201_23_dialog_content = "อา...",
  ui_story_5053_50531201_24_dialog_content = "(ฉันต้องทำให้เธอสงบลงด้วยวิธีใด ดังนั้นวิธีที่ชาวออโรเรียนทำเพื่อปลอบโยนกันและกัน... สิ่งหนึ่งที่หมายถึงความสงบสุขและความปลอดภัยของ Dark Angel...)",
  ui_story_5053_50531201_25_dialog_content = "(มันเป็นโอกาสเดียวของฉัน!)",
  ui_story_5053_50531201_26_dialog_content = "เลือกดอกกุหลาบ...เพื่อลูกของฉัน? ♪",
  ui_story_5053_50531201_27_dialog_content = "บางอย่าง บางอย่าง... สายลมที่พัดผ่านใบหน้าของคุณคือสิ่งที่ฉันต้องการ ♪",
  ui_story_5053_50531201_28_dialog_content = "...?",
  ui_story_5053_50531201_29_dialog_content = "...",
  ui_story_5053_50531201_30_dialog_content = "เลือกดอกกุหลาบ...? เพื่อพ่อและแม่ที่รักของฉัน... ♪",
  ui_story_5053_50531201_31_dialog_content = "หุบปาก",
  ui_story_5053_50531201_32_dialog_content = "ฉันขอโทษถ้าฉันร้องเพลงแย่มาก",
  ui_story_5053_50531201_33_dialog_content = "ฉันได้ยินเพลงนี้บนถนนเป็นครั้งคราว มันติดหู แต่ฉันจำคำศัพท์ไม่ได้",
  ui_story_5053_50531201_34_dialog_content = "เมโลดี้หนีฉันเกือบตลอดเวลาเช่นกัน",
  ui_story_5053_50531201_35_dialog_content = "สมาชิกของ House Schwartz ไม่มีสิทธิ์ร้องเพลงของ Lower Lumopolis",
  ui_story_5053_50531201_36_dialog_content = "... ทำไมคุณถึงไม่พอใจ House Schwartz มากนัก?",
  ui_story_5053_50531201_37_dialog_content = "ความเกลียดชังทำให้คุณต้องสวมหน้ากากและเสียสละตัวเองเพื่อเข้าใกล้ฉันและกลายเป็นคนรักของฉัน",
  ui_story_5053_50531201_38_dialog_content = "ทั้งหมดนี้ก็เพื่อที่คุณจะได้ลอบสังหารพ่อของฉัน",
  ui_story_5053_50531201_39_dialog_content = "...",
  ui_story_5053_50531201_40_dialog_content = "การกระทำของคุณไม่มีที่ติ และความเชี่ยวชาญในการต่อสู้และวิชาการของคุณไม่เป็นสองรองใคร",
  ui_story_5053_50531201_41_dialog_content = "บอกฉันทีว่าต้องใช้เวลานานแค่ไหนในการฝึกฝนความสามารถเหล่านี้?",
  ui_story_5053_50531201_42_dialog_content = "ห้าปี? สิบปี? หรือบางที...ทั้งชีวิตของคุณ?",
  ui_story_5053_50531201_43_dialog_content = "การฝึกฝนและการเตรียมการทั้งหมดเพียงเพื่อปฏิบัติการลอบสังหารที่มีชื่อเสียงระดับสูงเพียงครั้งเดียว",
  ui_story_5053_50531201_44_dialog_content = "ชีวิตพ่อของฉันคู่ควรกับความเกลียดชังในหัวใจของคุณและในหัวใจของผู้สมรู้ร่วมคิดของคุณหรือไม่?",
  ui_story_5053_50531201_45_dialog_content = "ก่อนที่คุณจะสรุปผิด ผมขออธิบายให้ชัดเจนสักข้อหนึ่ง",
  ui_story_5053_50531201_46_dialog_content = "ที่ข้าพูดเช่นนี้ไม่ใช่เพียงเพื่อปกป้องเกียรติบิดาของข้า... แต่เพราะข้าไม่ต้องการเห็นเจ้าถูกความเกลียดชังกลืนกิน",
  ui_story_5053_50531201_47_dialog_content = "House Schwartz เป็นศูนย์รวมของการกดขี่และการปกครองแบบเผด็จการ",
  ui_story_5053_50531201_48_dialog_content = "อาหารทุกมื้อที่คุณมี และเสื้อผ้าที่คุณใส่ล้วนเปื้อนเลือดของเหยื่อ",
  ui_story_5053_50531201_49_dialog_content = "เหยื่อที่คุณพูด พวกเขารวมถึงพี่สาวแท้ๆ ของ Caleb และครอบครัวที่แท้จริงของคุณด้วยหรือไม่?",
  ui_story_5053_50531201_50_dialog_content = "...",
  ui_story_5053_50531201_51_dialog_content = "นี่เป็นเพียงการคาดเดาในส่วนของฉัน อย่างน้อยก็ในตอนนี้",
  ui_story_5053_50531201_52_dialog_content = "เมื่อ 7 ปีก่อน แม่ของคาเลบเสียชีวิตอย่างน่าสลดใจและไม่ได้ตั้งใจในระหว่างปฏิบัติการต่อต้านกบฏ",
  ui_story_5053_50531201_53_dialog_content = "โจชัวน้องสาวของเขาก็อยู่ด้วยในระหว่างการโจมตี",
  ui_story_5053_50531201_54_dialog_content = "ถึงกระนั้น ราวกับว่าด้วยปาฏิหาริย์ เธอกลายเป็นผู้รอดชีวิตเพียงคนเดียวจากการผ่าตัด... แต่มันไม่ใช่ปาฏิหาริย์ใช่ไหม",
  ui_story_5053_50531201_55_dialog_content = "เมื่อนั้น \"โจชัว\" คนใหม่อย่างคุณก็จะปรากฏตัวขึ้น ฉันคิดผิดป่านนี้?",
  ui_story_5053_50531201_56_dialog_content = "...",
  ui_story_5053_50531201_57_dialog_content = "ฉันไม่เคยเล่าความสงสัยให้ใครฟัง และไม่เคยบอกใครเกี่ยวกับการปรากฏตัวของคุณที่นี่",
