  ui_story_5053_50531201_136_dialog_content = "นั่นจะทำให้คุณมีความสุขจริงๆ เหรอ โจชัว?",
  ui_story_5053_50531201_137_dialog_content = "ความสุขของฉันไม่ได้ผูกติดอยู่กับสิ่งนี้",
  ui_story_5053_50531201_138_dialog_content = "เมื่อการลอบสังหารเสร็จสิ้นลง ชีวิตของข้าก็จะสิ้นสุดลงเช่นกัน",
  ui_story_5053_50531201_139_dialog_content = "กล่าวอีกนัยหนึ่ง คุณได้เลือกความตายโดยไม่คำนึงว่าผลลัพธ์จะเป็นอย่างไร?",
  ui_story_5053_50531201_140_dialog_content = "นี่คือการปกป้องพันธมิตรของคุณหรือไม่?",
  ui_story_5053_50531201_141_dialog_content = "ไม่ เมื่อภารกิจของฉันเสร็จสิ้น ฉันไม่มีเหตุผลที่จะต้องอยู่อีกต่อไป",
  ui_story_5053_50531201_142_dialog_content = "ไม่มีเหตุผล...?",
  ui_story_5053_50531201_143_dialog_content = "ขุนนางขับเคลื่อนด้วยผลประโยชน์ส่วนตน แต่เราขับเคลื่อนด้วยอุดมคติของเรา",
  ui_story_5053_50531201_144_dialog_content = "เรามีชีวิตอยู่เพื่อความมั่งคั่งหรือยศถาบรรดาศักดิ์ แต่เพื่อสร้างดวงอาทิตย์ดวงใหม่ขึ้นสู่ท้องฟ้า ซึ่งส่องสว่างแก่โลกอย่างเท่าเทียมกัน",
  ui_story_5053_50531201_145_dialog_content = "เพื่อทำลายดวงอาทิตย์เก่าและกดขี่ลง เราเต็มใจเสียสละตนเองมากกว่า อย่าคิดว่าคุณสามารถตัดสินเราด้วยความคิดที่เป็นประโยชน์เน่าเฟะของคุณ",
  ui_story_5053_50531201_146_dialog_content = "เฮ้ แม้ว่าฉันจะรู้สึกเป็นเกียรติที่คุณแบ่งปันอะไรมากมายกับฉัน แต่ทำไมทุกอย่างถึงเป็นความลับและคลุมเครือ?",
  ui_story_5053_50531201_147_dialog_content = "นี่คือวิธีพูดที่คุณต้องการ...?",
  ui_story_5053_50531201_148_dialog_content = "ถ้าพ่อของฉันและการปกครองของเขาเป็นตัวแทนของ \"ดวงอาทิตย์ดวงเก่า\" สิ่งที่เรียกว่า \"ดวงอาทิตย์ดวงใหม่\" นี้จะไม่เป็นเพียงผู้ปกครองคนอื่นหรือ?",
  ui_story_5053_50531201_149_dialog_content = "ผู้ที่อยู่เบื้องหลังแผนการลอบสังหาร... พวกเขาพยายามที่จะรับตำแหน่งผู้ปกครองคนใหม่แทนพ่อของฉันหรือไม่?",
  ui_story_5053_50531201_150_dialog_content = "...",
  ui_story_5053_50531201_151_dialog_content = "...ไม่น่าเชื่อ.",
  ui_story_5053_50531201_152_dialog_content = "ฉันเข้าใจได้ว่าการตายร่วมกับศัตรูของคุณเพื่อปกป้องครอบครัวและพันธมิตรของคุณ... แต่คุณหมายความว่าอย่างไรที่คุณไม่มีเหตุผลในการดำรงอยู่?",
  ui_story_5053_50531201_153_dialog_content = "น้องชายของคุณคนไหนที่ต่อต้านฉันทั้งกลางวันและกลางคืนตั้งแต่ฉันขโมยคุณไปจากเขา?",
  ui_story_5053_50531201_154_dialog_content = "พ่อบุญธรรมของคุณคนไหนที่กลัวความปลอดภัยของคุณและขอให้คุณกลับบ้าน",
  ui_story_5053_50531201_155_dialog_content = "พวกเขาไม่มีเหตุผลพอที่จะมีชีวิตอยู่ต่อไป...?",
  ui_story_5053_50531201_156_dialog_content = "หากคุณเชื่ออย่างแท้จริงว่าเฮาส์ชวาร์ตษ์ได้ปล้นอิสรภาพของทุกคนไป คุณต้องทำลายพวกเราเพื่อยึดคืนมา!",
  ui_story_5053_50531201_157_dialog_content = "แล้วทำไมคุณต้องลิดรอนอิสรภาพแบบเดียวกันนั้นด้วย ทั้งๆ ที่คุณทำสำเร็จ?",
  ui_story_5053_50531201_158_dialog_content = "นี่หมายความว่าคุณจะจบชีวิตตัวเองถ้าพ่อของฉันเสียชีวิตกะทันหันอย่างนั้นหรือ? ชะตากรรมของคุณเกี่ยวพันกันเหรอ?!",
  ui_story_5053_50531201_159_dialog_content = "ฉันพิสูจน์มามากพอแล้วใช่ไหม ความผูกพันและความสัมพันธ์กับผู้ชายคนนั้นและลูกชายโง่ ๆ ของเขาเป็นเพียงการปลอมตัว",
  ui_story_5053_50531201_160_dialog_content = "ฉันเป็นอาวุธที่มีจุดประสงค์เพียงอย่างเดียวคือยุติการปกครองของ House Schwartz",
  ui_story_5053_50531201_161_dialog_content = "หากไม่มีศัตรู ฉันไม่มีเหตุผลที่จะดำรงอยู่ เสรีภาพเป็นของประชาชน ไม่ใช่ของฉัน",
  ui_story_5053_50531201_162_dialog_content = "...ช่างเจ้าเล่ห์เสียนี่กระไร",
  ui_story_5053_50531201_163_dialog_content = "ดูเหมือนว่า \"ดวงอาทิตย์ดวงใหม่\" นี้ไม่เคยสอนคุณถึงความหมายที่แท้จริงของความรักหรืออิสรภาพ",
  ui_story_5053_50531201_164_dialog_content = "คุณจะส่งมอบให้กับผู้คนได้อย่างไร?",
  ui_story_5053_50531201_165_dialog_content = "...",
  ui_story_5053_50531201_166_dialog_content = "... ฉันเข้าใจแล้ว.",
  ui_story_5053_50531201_167_dialog_content = "ฉันไม่เคยเป็นส่วนหนึ่งของโลกของคุณ ผมไม่มีทางเข้าใจอย่างแท้จริงว่าประชาชนได้รับความเดือดร้อนอย่างไรภายใต้การปกครองที่เข้มงวด",
  ui_story_5053_50531201_168_dialog_content = "คุณก็ไม่เคยเป็นส่วนหนึ่งของโลกของฉันเช่นกัน คุณไม่มีทางเข้าใจความหมายที่แท้จริงของความรักหรืออิสรภาพ",
  ui_story_5053_50531201_169_dialog_content = "นี่เป็นช่องว่างที่เราไม่สามารถหวังจะเชื่อมได้",
  ui_story_5053_50531201_170_dialog_content = "ยอมแล้ว ยอมแพ้แล้ว...",
  ui_story_5053_50531201_171_dialog_content = "นี่คือเหตุผลที่เราควรทำงานร่วมกันและชดเชยข้อบกพร่องของกันและกัน!",
  ui_story_5053_50531201_172_dialog_content = "คุณบ้าไปแล้ว.",
  ui_story_5053_50531201_173_dialog_content = "จะเรา หรือพ่อ หรือแม้แต่ \"ตะวันใหม่\" คนนี้...",
  ui_story_5053_50531201_174_dialog_content = "ไม่มีใครสามารถมองเห็นสิ่งต่าง ๆ จากมุมมองของทุกคน อย่างน้อยก็ไม่ได้อยู่คนเดียว",
  ui_story_5053_50531201_175_dialog_content = "แต่ถ้าเราละความแตกต่างของเราแล้วลองทำงานร่วมกัน...",
  ui_story_5053_50531201_176_dialog_content = "เราสามารถสร้างโลกใหม่ที่เสรีได้! หนึ่งเดียวที่สามารถได้ยินเสียงของทุกคน!",
  ui_story_5053_50531201_177_dialog_content = "นี่คือเป้าหมายของคุณเช่นกันใช่ไหม",
  ui_story_5053_50531201_178_dialog_content = "...",
  ui_story_5053_50531201_179_dialog_content = "ตั้งแต่ที่ฉันหยุดเธอวันนั้น ฉันคิดเรื่องนี้มาตลอด",
  ui_story_5053_50531201_180_dialog_content = "ผิดไหมที่เราจะฝากความฝันไว้กับคนอื่น?",
  ui_story_5053_50531201_181_dialog_content = "ไม่ว่าจะเป็นการทำให้การมองเห็นของพ่อเป็นจริง หรือฆ่าเขาเพื่อสร้าง \"ดวงอาทิตย์ดวงใหม่\"...",
  ui_story_5053_50531201_182_dialog_content = "บางทีการกำหนดชะตากรรมของเราอาจเป็นวิธีที่ดีที่สุดที่จะทำให้ความฝันของเราเป็นจริง",
  ui_story_5053_50531201_183_dialog_content = "สับสนและงมงายอย่างที่ฉันเป็นอยู่ตอนนี้...",
  ui_story_5053_50531201_184_dialog_content = "ผมเชื่อว่าการทำงานร่วมกันเราสามารถบรรลุสิ่งที่เราต้องการ",
  ui_story_5053_50531201_185_dialog_content = "สิ่งที่เราต้องทำคือก้าวแรก",
  ui_story_5053_50531201_186_dialog_content = "คุณสามารถเปิดตาของฉันสู่โลกภายนอกสวนลุมโปลิส",
  ui_story_5053_50531201_187_dialog_content = "เมื่อนั้นฉันจึงจะเห็นข้อบกพร่องของการเมืองของพ่อฉัน",
  ui_story_5053_50531201_188_dialog_content = "เป็นการแลกเปลี่ยน ฉันจะช่วยให้คุณได้สัมผัสกับชีวิตอย่างเต็มที่ เพื่อให้คุณสามารถหัวเราะออกมาจากก้นบึ้งของหัวใจได้อีกครั้ง",
  ui_story_5053_50531201_189_dialog_content = "เมื่อวันนั้นมาถึง คุณสามารถแบ่งปันความสุขนั้นกับคนทั้งโลกได้!",
  ui_story_5053_50531201_190_dialog_content = "...ช่างไร้สาระสิ้นดี",
  ui_story_5053_50531201_191_dialog_content = "มีผู้หญิงอีกมากมายที่ยินดีจะเล่นในบ้านกับคุณ เสียเวลากับฉันทำไม",
  ui_story_5053_50531201_192_dialog_content = "ก็...พูดตามตรง...",
  ui_story_5053_50531201_193_dialog_content = "มีคนไม่กี่คนที่เต็มใจต่อต้านพ่อของฉัน และชาวสวนลูโมโปลิสก็ไม่สามารถเข้าใจโลกภายนอกได้...",
  ui_story_5053_50531201_194_dialog_content = "แล้วก็ เอ่อ... อย่างที่ฉันพูดตอนที่เราเจอกันครั้งแรก—",
  ui_story_5053_50531201_195_dialog_content = "ฉันตกหลุมรักคุณตั้งแต่แรกเห็น!",
  ui_story_5053_50531201_196_dialog_content = "...",
  ui_story_5053_50531201_197_dialog_content = "(Dark Angel ไม่ได้เคลื่อนไหวเป็นเวลานาน ในที่สุดเธอก็สงบลงแล้ว...?)",
  ui_story_5053_50531201_198_dialog_content = "เฮ้! ในที่สุดคุณก็เต็มใจที่จะฟังฉันออกไหม?",
  ui_story_5053_50531201_199_dialog_content = "ฟังนะ ปีศาจขาว... ฉันหมายถึง อีกคนที่คุณต้องการฆ่า Caleb, Veronica และคนอื่นๆ",
  ui_story_5053_50531201_200_dialog_content = "พวกเขาต้องการ...",
  ui_story_5053_50531201_201_dialog_content = "ดะ...นีเอล...",
  ui_story_5053_50531201_202_dialog_content = "หา?",
  ui_story_5053_50531201_203_dialog_content = "แดเนียล... คุณ... หักหลังฉันทำไม!",
  ui_story_5053_50531201_204_dialog_content = "<size=45>แดเนียล!!!</size>",
  ui_story_5053_50531201_205_dialog_content = "อะไร—?! เธอจะบ้าดีเดือดยิ่งกว่าเดิม! P-โปรดใจเย็นๆ! ฉันไม่ใช่ลอร์ดชวาร์ตษ์!",
  ui_story_5053_50531201_206_dialog_content = "<size=45>แดเนียล! แดเนียล!</size>",
  ui_story_5053_50531201_207_dialog_content = "(ฉันหมดเวลาแล้ว แต่อย่างน้อยฉันก็ได้รับความสนใจจากเธอ! ฉันต้องดึงเธอไปที่จัตุรัสกลาง!)",
  ui_story_5053_50531201_208_dialog_content = "<size=45>แดเนียล—</size>",
  ui_story_5053_50531301_1_dialog_content = "ฉันขอขอบคุณชาวลูโมโปลิสทุกคนที่มารวมตัวกันที่นี่ในวันนี้เพื่อเฉลิมฉลองโอกาสพิเศษนี้",
  ui_story_5053_50531301_2_dialog_content = "House Schwartz เป็นอัญมณีมงกุฎของเมืองเช่นเดียวกับรากฐาน",
  ui_story_5053_50531301_3_dialog_content = "เรายกแขนขึ้นเพื่อป้องกัน Lumopolis กวัดแกว่งดาบที่ประดิษฐ์โดยคนของมันเอง",
  ui_story_5053_50531301_4_dialog_content = "วันนี้เรายกย่องไม่เพียง แต่ House Schwartz และแบบอย่างทางศีลธรรมเท่านั้น แต่ยังยกย่องผู้คนที่ภาคภูมิใจและชอบธรรมของ Lumopolis ด้วย!",
  ui_story_5053_50531301_5_dialog_content = "ฉันขอประกาศการเริ่มต้นการเฉลิมฉลองวันครอบครัวชวาร์ตษ์!",
  ui_story_5053_50531301_6_dialog_content = "การเฉลิมฉลองกำลังจะเริ่มขึ้น แต่ Dark Angel ยังไม่ปรากฏตัวใกล้กับอัฒจันทร์",
  ui_story_5053_50531301_7_dialog_content = "กำจัด...ผู้บุกรุก...",
  ui_story_5053_50531301_8_dialog_content = "อืม? เกิดอะไรขึ้นกับผู้คุมเหล่านี้?",
  ui_story_5053_50531301_9_dialog_content = "ถ้าฉันจำไม่ผิด คนที่อยู่ภายใน Crystal of Eternal Memory นั้นไม่มีอะไรมากไปกว่าภาพลวงตาที่ Lumina สร้างขึ้น",
  ui_story_5053_50531301_10_dialog_content = "ทำไมจู่ๆพวกเขาถึงทำตัวผิดปกติ? ราวกับสูญเสียความรู้สึกไปแล้ว...",
  ui_story_5053_50531301_11_dialog_content = "ฉันจะอยู่บนแสตนด์เพื่อคอยระวัง ถ้าฉันเห็นสัญญาณของ Dark Angel ฉันจะบอกให้ทุกคนรู้",
  ui_story_5053_50531301_12_dialog_content = "ดี. ระวังตัวด้วย Mia",
  ui_story_5053_50531301_13_dialog_content = "(มีอาควรจะปลอดภัยที่นั่นชั่วคราว PlayerNameในทางกลับกัน ตอนนี้เขาอยู่ที่ไหน?)",
  ui_story_5053_50531301_14_dialog_content = "ว่าไง",
  ui_story_5053_50531301_15_dialog_content = "PlayerName...",
  ui_story_5053_50531301_16_dialog_content = "ต้องหา... PlayerName...",
  ui_story_5053_50531301_17_dialog_content = "หยุด. เห็นได้ชัดว่าพวกคุณไม่ใช่อัศวินแห่ง House Kartima",
  ui_story_5053_50531301_18_dialog_content = "บ้านคาร์ติมาดูแลความปลอดภัยสำหรับงานฉลองปีนี้ แล้วทำไมคุณถึงเที่ยวเตร่แบบนี้ล่ะ?",
  ui_story_5053_50531301_19_dialog_content = "(ยามเหล่านี้เดินโซซัดโซเซไปรอบๆ และพึมพำกับตัวเอง... พวกเขาอาจจะเมาหรือเปล่า?)",
  ui_story_5053_50531301_20_dialog_content = "(และทำไมพวกเขาถึงสนใจที่จะค้นหา PlayerName?)",
  ui_story_5053_50531301_21_dialog_content = "ต้องหา... PlayerName...",
  ui_story_5053_50531301_22_dialog_content = "ต้องกำจัด... PlayerName...",
  ui_story_5053_50531301_23_dialog_content = "ฉันขอโทษคุณ? สิ่งที่คุณเพิ่งพูดไปเป็นการฝ่าฝืนหน้าที่อัศวินของคุณอย่างร้ายแรง",
  ui_story_5053_50531301_24_dialog_content = "จงอธิบายตัวท่านเองในบัดนี้เถิด ท่านทั้งหลาย",
  ui_story_5053_50531301_25_dialog_content = "กำจัด...ผู้บุกรุก...!",
  ui_story_5053_50531301_26_dialog_content = "พวกเขาไม่สามารถแม้แต่จะพูดให้สอดคล้องกัน น้อยกว่าบอกฉันว่าใครหรืออะไรอยู่เบื้องหลังสิ่งนี้ เกิดอะไรขึ้นกับอัศวินเหล่านี้ในโลกนี้?",
  ui_story_5053_50531301_27_dialog_content = "(หลังจากการรีเซ็ต จะไม่มีใครใน Crystal of Eternal Memory จดจำได้ PlayerName อีกต่อไป.)",
  ui_story_5053_50531301_28_dialog_content = "(พวกเขาไม่ควรแม้แต่จะรับรู้ถึงการมีอยู่ของเขา น้อยกว่ามากที่ซ่อนเจตนาฆ่าต่อเขา)",
  ui_story_5053_50531301_29_dialog_content = "นั่นไม่จำเป็น สามารถหาทีมผู้พิทักษ์ได้ PlayerName เร็วพอๆ กัน ถ้าไม่มากไปกว่านี้",
  ui_story_5053_50531301_30_dialog_content = "นอกจากนี้ เราต้องการความแข็งแกร่งของทุกคนหากเราหวังว่าจะมีโอกาสต่อสู้กับสัตว์ประหลาดตัวนั้น",
  ui_story_5053_50531301_31_dialog_content = "ฉันคิดว่าคุณรู้ดีพอๆ กับฉันว่าเรื่องใดสำคัญกว่ากัน ใช้สามัญสำนึกของคุณ ดาเนียล",
  ui_story_5053_50531301_32_dialog_content = "(... โจชัวเป็นคนเดียวนอกกลุ่มของเราที่รู้เรื่องนี้ PlayerName.)",
  ui_story_5053_50531301_33_dialog_content = "(นอกจากเราแล้วเธอยังเป็นคนเดียวที่มีชีวิตใน Crystal of Eternal Memory)",
  ui_story_5053_50531301_34_dialog_content = "(แต่ทำไมเธอถึงต้องการตามล่าเด็กที่ไม่มีส่วนเกี่ยวข้องกับเธอ?)",
  ui_story_5053_50531301_35_dialog_content = "(การบอกให้ Caleb อยู่เคียงข้างเธอเป็นทางเลือกที่ถูกต้อง)",
  ui_story_5053_50531301_36_dialog_content = "(ฉันได้แต่ภาวนาว่าเขาจะไม่ปล่อยให้ความสุขที่ได้กลับมาพบกับพี่สาวของเขามาบดบังการตัดสินของเขาและเปิดโปงความจริงแทนฉัน)",
  ui_story_5053_50531301_37_dialog_content = "ฮึก... ฮึก... ท่านลอร์ดชวาร์ตษ์! โอ้ ขอบคุณพระเจ้าที่ฉันพบคุณ!",
  ui_story_5053_50531301_38_dialog_content = "PlayerName...?",
  ui_story_5053_50531301_39_dialog_content = "อ๊าาาาาา—!",
  ui_story_5053_50531301_40_dialog_content = "PlayerName, ลง!",
  ui_story_5053_50531301_41_dialog_content = "ลืมเรื่อง Dark Angel! เมียหลวงตกอยู่ในอันตราย! เราต้องไปที่สแตนด์!",
  ui_story_5053_50531301_42_dialog_content = "หมายความว่าไง",
  ui_story_5053_50531301_43_dialog_content = "แค่เชื่อฉัน! ลุยกันเลย!!",
  ui_story_5053_50531301_44_dialog_content = "ดีมาก...",
  ui_story_5053_50531301_45_dialog_content = "ว้าว! อะ-นี่มันอะไรกันเนี่ย?!",
  ui_story_5053_50531301_46_dialog_content = "ถือนิ่ง ฉันกำลังพาคุณไปที่แสตนด์",
  ui_story_5053_50531301_47_dialog_content = "?!",
  ui_story_5053_50531301_48_dialog_content = "ด...แดเนียล...? แดเนียล!!!",
  ui_story_5053_50531301_49_dialog_content = "เฮ้! เลิกผลักไส!",
  ui_story_5053_50531301_50_dialog_content = "อะ-เกิดอะไรขึ้น?",
  ui_story_5053_50531301_51_dialog_content = "สัตว์ประหลาด! มันคือสัตว์ประหลาด!!",
  ui_story_5053_50531301_52_dialog_content = "ฝูงชนอยู่ในความโกลาหล เกิดอะไรขึ้นที่นั่น?",
  ui_story_5053_50531301_53_dialog_content = "<size=30> นั่นคือ...พ่อและ PlayerName! เดี๋ยวนะ นั่นมัน... ดาร์กแองเจิ้ลเหรอ!</size>",
  ui_story_5053_50531301_54_dialog_content = "มันคืออะไรเวโรนิก้า?",
  ui_story_5053_50531301_55_dialog_content = "ไม่-ไม่มีอะไร พ่อ...",
  ui_story_5053_50531301_56_dialog_content = "พวกเขากำลังฝ่าฝูงชนและไปยังอัฒจรรย์!",
  ui_story_5053_50531301_57_dialog_content = "หยุดนะการ์ด!!",
  ui_story_5053_50531301_58_dialog_content = "(เทพบุตรกำลังตามล่าพ่อจริงๆ...เหมือนที่แม่พูด)",
  ui_story_5053_50531301_59_dialog_content = "(ฉันไม่รู้ว่าทำไมพวกเขาถึงวิ่งมาทางนี้ แต่ฉันต้องปกป้องเขา)",
  ui_story_5053_50531301_60_dialog_content = "(โอ้ ฮิปโปคา ได้โปรดตอบฉันที ฉันต้องการคุณมากกว่าที่เคย!)",
  ui_story_5053_50531301_61_dialog_content = "เวโรนิก้า เกิดอะไรขึ้น? ใครคือคนแปลกหน้าที่ต่อสู้ฝ่าฝูงชน?",
  ui_story_5053_50531301_62_dialog_content = "ฉันไม่รู้จักคาร์ลีน แต่อยู่ใกล้เรา",
  ui_story_5053_50531301_63_dialog_content = "ผู้ชายตรงหน้าเป็นอย่างอื่น",
  ui_story_5053_50531301_64_dialog_content = "เขาหลบหลีกยามของเราอย่างง่ายดาย โดยแบกคนไว้ในอ้อมแขน",
  ui_story_5053_50531301_65_dialog_content = "จริงๆ แล้วเขาเกือบจะดูเหมือน...",
  ui_story_5053_50531301_66_dialog_content = "H-เขาล้มทหารยามคนหนึ่งและใช้เขากระโจนออกมาจากฝูงชน! เขากำลังตรงมาหาเรา!",
  ui_story_5053_50531301_67_dialog_content = "ผู้ชาย ปกป้องคนอื่น! ฉันจะจัดการพวกมันเอง",
  ui_story_5053_50531301_68_dialog_content = "...",
  ui_story_5053_50531301_69_dialog_content = "คุณเป็นใครและมีธุระอะไรที่นี่?",
  ui_story_5053_50531301_70_dialog_content = "อันตรายที่คุณกล่าวถึงอยู่ที่ไหน PlayerName?",
  ui_story_5053_50531301_71_dialog_content = "ฉันถามคำถามนาย!",
  ui_story_5053_50531301_72_dialog_content = "เหนือกว่าเรา! จะอยู่ที่นี่ทุกวินาที!",
  ui_story_5053_50531301_73_dialog_content = "ไอ้ตัวเหม็นนี่มันมาจากไหน! ยาม! ปกป้องฉัน! การ์ด!!!",
  ui_story_5053_50531301_74_dialog_content = "ด...แดเนียล? แดเนียล...แดเนียล...",
  ui_story_5053_50531301_75_dialog_content = "อ๊าาาา—แดเนียล—!!!",
  ui_story_5053_50531301_76_dialog_content = "อยู่ห่างจากพ่อของฉัน!",
  ui_story_5053_50531301_77_dialog_content = "... ที่นี่! มังกรมาแล้ว!!",
  ui_story_5053_50531301_78_dialog_content = "<size=50>รัว—!!!</size>",
  ui_story_5053_50531301_79_dialog_content = "มังกรบิน?",
  ui_story_5053_50531301_80_dialog_content = "พันธสัญญาที่ตราตรึงในสายเลือดของตระกูลคาร์ติมา... แต่ยังไม่เร็วเกินไปหรือ?",
  ui_story_5053_50531301_81_dialog_content = "ฉันขอแนะนำให้คุณมุ่งความสนใจไปที่อันตรายที่อยู่ตรงหน้า ชายหนุ่ม",
  ui_story_5053_50531301_82_dialog_content = "คนทรยศ Kartima... คุณจะไม่มีวันถูกควบคุมที่นี่!",
  ui_story_5053_50531301_83_dialog_content = "ตั้งสมาธิกับศัตรูที่แท้จริงของคุณ! มันกำลังมาหาเรา!",
  ui_story_5053_50531301_84_dialog_content = "...",
  ui_story_5053_50531301_85_dialog_content = "ธ-มังกร! แต่ไม่น่าจะมาถึงที่นี่!",
  ui_story_5053_50531301_86_dialog_content = "ไม่ต้องกังวลเวโรนิก้า! ฉันจะปกป้องคุณ!",
  ui_story_5053_50531301_87_dialog_content = "ไม่... พวกกบฏนำแผนของพวกเขาไปสู่การปฏิบัติเร็วกว่าที่เราคิด! เข้าที่กำบัง คาร์ลีน!",
  ui_story_5053_50531301_88_dialog_content = "คาร์ลีน...? เวโรนิก้า...?",
  ui_story_5053_50531301_89_dialog_content = "รออออออ!!!!!!",
  ui_story_5053_50531301_90_dialog_content = "มังกรกำลังจะโจมตี!",
  ui_story_5053_50531301_91_dialog_content = "—!!!",
  ui_story_5053_50531301_92_dialog_content = "มังกรตัวนั้นมาจากไหน!",
  ui_story_5053_50531301_93_dialog_content = "ว้าว! พ่ออยู่ไหน!",
  ui_story_5053_50531301_94_dialog_content = "มันพ่นไฟ! วิ่ง!!!",
  ui_story_5053_50531301_95_dialog_content = "ลูกชาย! คุณอยู่ที่ไหนลูกชายของฉัน!",
  ui_story_5053_50531301_96_dialog_content = "...",
  ui_story_5053_50531301_97_dialog_content = "ได้โปรด! คุณเห็นเด็กน้อยของฉันไหม เขาสูงประมาณนี้และ...",
  ui_story_5053_50531301_98_dialog_content = "กำจัด...ให้หมด...",
  ui_story_5053_50531301_99_dialog_content = "หา? ตะกี๊ว่าอะไรนะ?",
  ui_story_5053_50531301_100_dialog_content = "พันธมิตรมากขึ้น... กำจัดพวกเขาทั้งหมด...",
  ui_story_5053_50531301_101_dialog_content = "เอิ๊ก?! ทะ-คุณเป็นอะไร...",
  ui_story_5053_50531301_102_dialog_content = "พันธมิตรมากขึ้น... กำจัดพวกเขาทั้งหมด...",
  ui_story_5053_50531301_103_dialog_content = "*ไอ* เวโรนิก้า? พ่อ? คุณอยู่ที่ไหน",
  ui_story_5053_50531301_104_dialog_content = "คาร์ลีน! คุณสบายดีหรือเปล่า?",
  ui_story_5053_50531301_105_dialog_content = "ฉันสบายดี. แค่ฝุ่นเกาะก็เจ็บคอแล้ว",
  ui_story_5053_50531301_106_dialog_content = "โอ้ ขอบคุณพระเจ้า...",
  ui_story_5053_50531301_107_dialog_content = "เวโรนิก้า...คาร์ลีน...",
  ui_story_5053_50531301_108_dialog_content = "มันได้ผล! ทั้งสี่คนสามารถเอาชนะมังกรคืนได้!!",
  ui_story_5053_50531301_109_dialog_content = "(ดูเหมือนว่าจะมีแต่สมาชิกในครอบครัวเท่านั้นที่สามารถทำให้ Dark Angel สงบลงได้ มันเป็นการเดิมพันครั้งใหญ่ แต่ฉันดีใจที่ได้ผลตอบแทน!",
  ui_story_5053_50531301_110_dialog_content = "ยังเร็วเกินไปที่จะเฉลิมฉลอง",
  ui_story_5053_50531301_111_dialog_content = "มังกรเพียงถอยหลังเพื่อรวบรวมกำลังสำหรับการโจมตีที่รุนแรงอีกครั้ง",
  ui_story_5053_50531301_112_dialog_content = "มันจะลงมาหาเราในไม่ช้า",
  ui_story_5053_50531301_113_dialog_content = "นั่นหมายความว่าเราต้องเอาชนะมันก่อนที่มันจะโจมตีครั้งต่อไป",
  ui_story_5053_50531301_114_dialog_content = "ถ้าอย่างนั้นคุณควรมุ่งไปที่จุดอ่อนของมันจะดีกว่า",
  ui_story_5053_50531301_115_dialog_content = "คุณต้องโจมตีมัน—",
  ui_story_5053_50531301_116_dialog_content = "ฉันรู้ว่าจะโจมตีสัตว์ร้ายที่ไหน",
  ui_story_5053_50531301_117_dialog_content = "มันจะไม่ส่งผลดีต่อเราเลย! มังกรมีความคงกระพันซึ่งช่วยให้สามารถรักษาบาดแผลได้ทันที",
  ui_story_5053_50531301_118_dialog_content = "ว่าไง",
  ui_story_5053_50531301_119_dialog_content = "ท่านชวาร์ตษ์! การจลาจลเริ่มขึ้นแล้ว!",
  ui_story_5053_50531301_120_dialog_content = "แล้วดำเนินการตามแผนต่อไป รวบรวมคนมากขึ้นและปราบกบฏ",
  ui_story_5053_50531301_121_dialog_content = "ปล่อยมังกรไว้ที่ฉัน และให้ทหารที่เหลืออพยพผู้คนออกจากบริเวณนี้",
  ui_story_5053_50531301_122_dialog_content = "แต่ท่านลอร์ด... ไม่ใช่พวกกบฏเท่านั้นที่ก่อการจลาจล! คนส่วนใหญ่ในพื้นที่รวมถึงทหารของเราบางส่วนก็เริ่มโจมตีเช่นกัน!",
  ui_story_5053_50531301_123_dialog_content = "อะไรน่ะ...?!",
  ui_story_5053_50531301_124_dialog_content = "ดูเหมือนว่าพวกเขาจะสูญเสียการควบคุมร่างกายและจิตใจไปแล้ว ท่านลอร์ด พวกมันกำลังฟาดฟันสิ่งมีชีวิตใดๆ ก็ตามที่มันสามารถเข้าถึงได้ ไม่ว่าจะเป็นเพื่อนหรือศัตรู!",
  ui_story_5053_50531301_125_dialog_content = "แต่สิ่งที่น่ารำคาญที่สุดคือความบ้าคลั่งของพวกเขาดูเหมือนจะแพร่กระจายไปยังใครก็ตามที่พวกเขาสามารถทำร้ายได้! ราวกับว่า...",
  ui_story_5053_50531301_126_dialog_content = "ราวกับว่าพวกเขากำลังติดเชื้อและกลายเป็นศพเดินได้ใช่ไหม?",
  ui_story_5053_50531301_127_dialog_content = "P-แม่นยำ",
  ui_story_5053_50531301_128_dialog_content = "คุณดูเหมือนจะค่อนข้างรู้ถึงสถานการณ์ปัจจุบันของเรา",
  ui_story_5053_50531301_129_dialog_content = "เวลาไม่ได้อยู่ข้างเรา ดังนั้นบอกเราในสิ่งที่คุณรู้",
  ui_story_5053_50531301_130_dialog_content = "ฉัน...",
  ui_story_5053_50531301_131_dialog_content = "(ชวาร์ตษ์หนุ่มก็จ้องมาที่ฉันเหมือนกัน...)",
  ui_story_5053_50531301_132_dialog_content = "(ถ้าฉันไม่ให้คำอธิบายที่ดีพอ เขาจะไม่ปล่อยฉันไปง่ายๆ)",
  ui_story_5053_50531301_133_dialog_content = "(แต่หากฉันบอกความจริงกับเขาตอนนี้ก็มีแต่จะทำให้เขาสงสัยในตัวฉัน! ฉันต้องหาข้อแก้ตัวที่สมบูรณ์แบบ...)",
  ui_story_5053_50531301_134_dialog_content = "เจ้าลังเลที่จะเปิดเผยความจริงต่อหน้าข้างั้นหรือ?",
  ui_story_5053_50531301_135_dialog_content = "หรืออาจเป็นได้ว่าผู้ร้ายยืนอยู่ท่ามกลางคุณจากภายนอก—",
  ui_story_5053_50531301_136_dialog_content = "เหมือนสัตว์ประหลาดมีปีกตัวนั้น?",
  ui_story_5053_50531301_137_dialog_content = "กรุณาอย่าเรียกเธอว่า! เธอไม่ใช่สัตว์ประหลาด เธอคือ...",
  ui_story_5053_50531301_138_dialog_content = "บนนั้นมังกรกำลังเตรียมที่จะลงมาโจมตีอีกครั้ง",
  ui_story_5053_50531301_139_dialog_content = "ในขณะที่กองทัพของผู้ตายล้อมรอบเราจากเบื้องล่าง",
  ui_story_5053_50531301_140_dialog_content = "ฉันแน่ใจว่าคุณรู้ว่าอะไรมีความสำคัญกว่าในเวลาเช่นนี้ ใช่ไหม",
  ui_story_5053_50531301_141_dialog_content = "... แน่นอนฉันรู้.",
  ui_story_5053_50531301_142_dialog_content = "ผู้พิทักษ์ ติดต่อ Lachon และ Otto และบอกพวกเขาว่าตอนนี้ทหารในจัตุรัสอยู่ภายใต้การควบคุมของพวกเขาแล้ว",
  ui_story_5053_50531301_143_dialog_content = "บอกพวกเขาให้เสริมการป้องกันของอัฒจันทร์และนำผู้รอดชีวิตที่ไม่ติดเชื้อมาที่นี่",
  ui_story_5053_50531301_144_dialog_content = "ใช่เจ้านายของฉัน!",
  ui_story_5053_50531301_145_dialog_content = "(โชคดีที่ลอร์ดชวาร์ตษ์สามารถเอาตัวตนที่อายุน้อยกว่าออกจากหลังของฉันได้ เขาคงรู้ว่าฉันมีเหตุผลของฉันที่ไม่ยอมบอกความจริงกับเขา)",
  ui_story_5053_50531301_146_dialog_content = "(ฉันจะเสียเวลาอีกสักวินาทีไม่ได้ ไม่ได้หลังจากที่เรามาไกลขนาดนี้แล้ว ถึงเวลาที่เราจะต้องกลับไปที่ Schwartz Mansion แล้ว!)",
  ui_story_5053_50531301_147_dialog_content = "เวโรนิก้า... มันเรียกชื่อฉันทำไม?",
  ui_story_5053_50531301_148_dialog_content = "แค่รักษาระยะห่างจากเธอ คาร์ลีน",
  ui_story_5053_50531301_149_dialog_content = "เวโรนิก้า... คาร์ลีน... คุณ... เจ็บไหม...?",
  ui_story_5053_50531301_150_dialog_content = "คุณ... เจ็บไหม...?",
  ui_story_5053_50531301_151_dialog_content = "ฉันจะกอดเธอ...และร้องเพลง...",
  ui_story_5053_50531301_152_dialog_content = "ฮะ? ฉันสบายดี คาร์ลีนก็เช่นกัน",
  ui_story_5053_50531301_153_dialog_content = "ดังนั้นคุณจึงสามารถสื่อสารกับเราได้... คุณเป็นส่วนหนึ่งของแม่ใช่ไหม?",
  ui_story_5053_50531301_154_dialog_content = "แม่... หนูคือ.. แม่...",
  ui_story_5053_50531301_155_dialog_content = "ถ้าอย่างนั้นคุณช่วยหยุดโจมตีเราได้ไหม ได้โปรดหยุดพยายามทำร้ายพ่อได้ไหม?",
  ui_story_5053_50531301_156_dialog_content = "เวโรนิก้า... พ่อ? แดเนียล... แดเนียล...!!!",
  ui_story_5053_50531301_157_dialog_content = "Y-คุณไม่ต้องการให้เราเห็นคุณสองคนต่อสู้กัน!",
  ui_story_5053_50531301_158_dialog_content = "ไม่ว่าใช่มั้ย?",
  ui_story_5053_50531301_159_dialog_content = "...",
  ui_story_5053_50531301_160_dialog_content = "ไม่เอาแล้ว...ไม่สู้แล้ว...กลัวสาวๆ...",
  ui_story_5053_50531301_161_dialog_content = "ไม่สู้แล้ว...เวโรนิก้า...ไม่ต้องกลัว...",
  ui_story_5053_50531301_162_dialog_content = "ฉันรู้แม่ ขอบคุณ",
  ui_story_5053_50531301_163_dialog_content = "(แม่บอกว่าเทวทูตมืดเกิดมาจากเมล็ดพันธุ์ และเธอไม่ได้เป็นอะไรมากไปกว่าสัตว์ร้ายที่ไร้สติ)",
  ui_story_5053_50531301_164_dialog_content = "(แต่ไม่เพียงแต่ฉันจะสื่อสารกับเธอเท่านั้น... ฉันยังสัมผัสได้ถึงความเมตตาบางอย่างที่มาจากเธอด้วย)",
  ui_story_5053_50531301_165_dialog_content = "(น้ำใจที่แม่ไม่เคยได้รับจากแม่ที่คฤหาสน์ เกิดอะไรขึ้น...?)",
  ui_story_5053_50531301_166_dialog_content = "<size=30>เฮ้! นี่เวโรนิก้า!</size>",
  ui_story_5053_50531301_167_dialog_content = "PlayerName! พ่อ! คุณสองคนสบายดีไหม",
  ui_story_5053_50531301_168_dialog_content = "จุ๊ๆ! เก็บมันลง!",
  ui_story_5053_50531301_169_dialog_content = "ขณะที่ชวาร์ตษ์หนุ่มกำลังยุ่งอยู่กับการต่อสู้กับมังกร เราสามคนและดาร์กแองเจิลจำเป็นต้องจากไป",
  ui_story_5053_50531301_170_dialog_content = "ออกจาก? แต่จะที่ไหน? แล้วทำไม Dark Angel ต้องมากับเราด้วย?",
  ui_story_5053_50531301_171_dialog_content = "ถึงคฤหาสน์ชวาร์ตษ์ คาเลบและจาคีนกำลังตกอยู่ในอันตรายร้ายแรง",
  ui_story_5053_50531301_172_dialog_content = "ฮะ? ฉันขอโทษ ทั้งหมดนี้ทำให้เกิดความสับสน อะไรกันแน่...",
  ui_story_5053_50531301_173_dialog_content = "PlayerName ได้สัญญาว่าจะอธิบายทุกอย่างระหว่างทาง เราต้องไปในขณะที่เรายังมีโอกาส",
  ui_story_5053_50531301_174_dialog_content = "ย-ใช่แล้ว",
  ui_story_5053_50531301_175_dialog_content = "แดเนียล...",
  ui_story_5053_50531301_176_dialog_content = "และคุณแน่ใจว่าเธอจะไม่โจมตีฉันอีก PlayerName?",
  ui_story_5053_50531301_177_dialog_content = "เอ่อ ฉันค่อนข้างมั่นใจว่าตอนนี้คุณปลอดภัย...",
  ui_story_5053_50531301_178_dialog_content = "เธอไม่ทำหรอกพ่อ แม่สัญญาแล้วว่าจะไม่ทำใช่ไหม?",
  ui_story_5053_50531301_179_dialog_content = "ฉันสัญญา...",
  ui_story_5053_50531301_180_dialog_content = "... ดี.",
  ui_story_5053_50531301_181_dialog_content = "ด้านหลังของแท่นวางควรไม่มีผู้พบเห็น เราควรออกไปก่อนที่พวกเขาจะเสริมกำลังการป้องกันให้เสร็จ",
  ui_story_5053_50531301_182_dialog_content = "คุณจะไปไหน เวโรนิก้า?",
  ui_story_5053_50531301_183_dialog_content = "พ่อบอกให้พวกเราอยู่ที่นี่รอคุณร็อตพาพวกเราไปที่ปลอดภัย",
  ui_story_5053_50531301_184_dialog_content = "ฉันขอโทษ คาร์ลีน แต่ฉันอยู่ไม่ได้ มีบางสิ่งที่สำคัญมากที่ฉันต้องทำ",
  ui_story_5053_50531301_185_dialog_content = "แต่สาวใจกล้าอย่างเธอคงไม่มีปัญหาในการรอคุณร็อตคนเดียวใช่ไหม?",
  ui_story_5053_50531301_186_dialog_content = "ฉันจะสบายดี แต่ฉันเป็นห่วงคุณมากกว่า เวโรนิก้า",
  ui_story_5053_50531301_187_dialog_content = "ออกไปเองก็มักจะร้องไห้คนเดียว...",
  ui_story_5053_50531301_188_dialog_content = "แต่เธอไม่ต้องร้องไห้อีกแล้ว เวโรนิก้า! ฉันสัญญาว่าวันหนึ่งฉันจะแข็งแกร่งขึ้นและปกป้องคุณไม่ว่าจะเกิดอะไรขึ้น!",
  ui_story_5053_50531301_189_dialog_content = "ฮี่ฮี่... เจ้ากลายเป็นผู้กล้าหาญและเป็นผู้ใหญ่เสียนี่กระไร คาร์ลีน",
  ui_story_5053_50531301_190_dialog_content = "คุณไม่จำเป็นต้องกังวลเช่นกัน ฉันไม่อ่อนแอและหมดหนทางอย่างที่เคยเป็น",
  ui_story_5053_50531301_191_dialog_content = "พี่สาวของคุณจะสบายดี ฉันสัญญา",
  ui_story_5053_50531301_192_dialog_content = "ฉันรู้ว่าในอดีตฉันตามหลังคุณครึ่งก้าวเสมอ และทำให้ทุกคนลำบาก",
  ui_story_5053_50531301_193_dialog_content = "แต่จากนี้ไป ฉันจะทำงานหนักและกลายเป็นพี่ใหญ่ที่พึ่งพาได้ ที่จะช่วยคุณแบกรับภาระได้",
  ui_story_5053_50531301_194_dialog_content = "เวโรนิก้า...?",
  ui_story_5053_50531301_195_dialog_content = "ได้โปรดเชื่อฉันเถอะ",
  ui_story_5053_50531301_196_dialog_content = "ใช่. ฉันไว้ใจคุณ.",
  ui_story_5053_50531301_197_dialog_content = "ฮี่ฮี่ ขอบคุณค่ะ",
  ui_story_5053_50531301_198_dialog_content = "จนกว่าจะถึงคราวหน้า... คาร์ลีนน้อยผู้น่ารักของฉัน",
  ui_story_5053_50531302_1_dialog_content = "... นี่คือสถานการณ์ปัจจุบันในจัตุรัสกลาง",
  ui_story_5053_50531302_2_dialog_content = "ทุกทางเดินที่นำไปสู่จัตุรัสถูกปิดสนิท",
  ui_story_5053_50531302_3_dialog_content = "ภายใต้คำสั่งของลอร์ดชวาร์ตษ์ การจลาจลเริ่มอยู่ภายใต้การควบคุม ทำใจให้สบายได้แล้วฝ่าบาท",
  ui_story_5053_50531302_4_dialog_content = "... เข้าใจแล้ว คุณอาจจะออกไปตอนนี้",
  ui_story_5053_50531302_5_dialog_content = "ตามที่เธอปรารถนา",
  ui_story_5053_50531302_6_dialog_content = "ถ้าอย่างนั้น คุณจะเป็นที่รักและล็อคประตูให้เราได้ไหม จาคีน?",
  ui_story_5053_50531302_7_dialog_content = "แน่นอน! ท้ายที่สุด แม้แต่แม่กุญแจธรรมดาก็สร้างความปลอดภัยให้กับเราได้อย่างมหัศจรรย์!",
  ui_story_5053_50531302_8_dialog_content = "ให้ฉันถามคำถามคุณ คาเลบ ทำไมคุณถึงต้องการช่วยฉัน",
  ui_story_5053_50531302_9_dialog_content = "หา?",
  ui_story_5053_50531302_10_dialog_content = "อืม? เพราะคุณเป็นน้องสาวของฉันแน่นอน! พี่ชายคนไหนไม่อยากช่วยน้องสาวของตัวเอง?",
  ui_story_5053_50531302_11_dialog_content = "<color=#e8d9bb>ตุ๊ด ตุ๊ด ตุ๊ด ตุ๊ด!</color>",
  ui_story_5053_50531302_12_dialog_content = "เลดี้โจชัว ฉันมาคุ้มกันคุณให้ปลอดภัย ฉันขอเข้าไปได้ไหม",
  ui_story_5053_50531302_13_dialog_content = "แน่นอน แค่เข้ามาที่นี่!",
  ui_story_5053_50531302_14_dialog_content = "Jakine คุณลืมไปแล้วหรือว่าคุณเป็นแขกที่นี่? พี่สาวยังพูดไม่จบ!",
  ui_story_5053_50531302_15_dialog_content = "...",
  ui_story_5053_50531302_16_dialog_content = "ขออภัยที่ขัดจังหวะ...",
  ui_story_5053_50531302_17_dialog_content = "อะไรคะคุณร็อต?",
  ui_story_5053_50531302_18_dialog_content = "ฉันบอกว่าคุณไม่สบายวันนี้ ด้วยเหตุนี้ ลอร์ดชวาร์ตซ์จึงสั่งให้ข้าอยู่เคียงข้างท่านและรับรองความปลอดภัยของท่าน",
  ui_story_5053_50531302_19_dialog_content = "ด้วยความรุนแรงของสถานการณ์ ฉันต้องขอให้คุณติดตามฉันไปยังสถานที่อื่นที่ปลอดภัย",
  ui_story_5053_50531302_20_dialog_content = "เมื่อคุณหลบภัยได้แล้ว ฉันจะพาเจ้าหญิงคาร์ลีนไปที่ปลอดภัยด้วย รับรองฉันจะไม่ปล่อยให้เธอได้รับอันตรายใด ๆ",
  ui_story_5053_50531302_21_dialog_content = "ฉันเห็น. คุณใจดีแค่ไหน",
  ui_story_5053_50531302_22_dialog_content = "อย่างไรก็ตาม แขกของฉันและฉันปลอดภัยอย่างสมบูรณ์ที่นี่ ถ้ามีอะไร คุณควรจะกังวลเกี่ยวกับความปลอดภัยของคาร์ลีนให้มากขึ้นในตอนนี้",
  ui_story_5053_50531302_23_dialog_content = "ฉันเกรงว่าจะทำอย่างนั้นไม่ได้",
  ui_story_5053_50531302_24_dialog_content = "ถ้าฉันจะออกไปตอนนี้... คุณจะไม่มีปัญหาในการฆ่าแขกสองคนของคุณในขณะที่ฉันไม่อยู่",
  ui_story_5053_50531302_25_dialog_content = "M-ฆาตกรรม?!",
  ui_story_5053_50531302_26_dialog_content = "หมายความว่าไงคะคุณร็อต?! น้องสาวของฉันไม่เคยจะ...",
  ui_story_5053_50531302_27_dialog_content = "...โจชัว?",
  ui_story_5053_50531302_28_dialog_content = "ใช่ คาเลบ ฉันจะไม่ทำอะไรที่รุนแรงโหดร้าย",
  ui_story_5053_50531302_29_dialog_content = "ทำไมคุณถึงกล่าวหาฉันเรื่องนั้น คุณร็อต",
  ui_story_5053_50531302_30_dialog_content = "คุณสามารถจ่ายกับการกระทำ",
  ui_story_5053_50531302_31_dialog_content = "กริชซ่อนอยู่ที่ขาของคุณไม่ใช่เหรอ? วิธีการลอบสังหารสุดคลาสสิค",
  ui_story_5053_50531302_32_dialog_content = "ความสามารถในการปกปิดอาวุธของคุณนั้นไม่มีใครเทียบได้ แต่มือของคุณที่ลอยอยู่เหนือด้ามจับทำให้ความตั้งใจของคุณชัดเจนเกินไป",
  ui_story_5053_50531302_33_dialog_content = "...",
  ui_story_5053_50531302_34_dialog_content = "คุณเป็นนักฆ่าที่ได้รับการฝึกฝนมาอย่างดี และไม่ต้องสงสัยเลย",
  ui_story_5053_50531302_35_dialog_content = "คุณเป็นเหมือนเจ้านายของฉันมาก แต่คุณไม่ได้เป็นอะไรมากไปกว่านักต้มตุ๋นที่น่าสนใจอย่างยิ่ง",
  ui_story_5053_50531302_36_dialog_content = "นักต้มตุ๋น? B-แต่เสียงและรูปร่างหน้าตาของเธอ... ฉันไม่เคยคิดผิดเลย!",
  ui_story_5053_50531302_37_dialog_content = "เขาพูดถูก และ Crystal of Eternal Memory ก็แสดงให้เห็นอย่างชัดเจนว่าเธอเป็นคนที่มีลมหายใจเช่นกัน!",
  ui_story_5053_50531302_38_dialog_content = "เป็นไปได้ยังไงที่มีคนอื่นแอบอ้างเป็น Lady Joshua อยู่ที่นี่?!",
  ui_story_5053_50531302_39_dialog_content = "ฉันไม่รู้ว่าคุณสองคนเชื่อมโยงกับมือสังหารคนนี้ได้อย่างไร แต่เพื่อความปลอดภัยของคุณ ฉันขอแนะนำให้คุณอยู่ห่างจากเธอ",
  ui_story_5053_50531302_40_dialog_content = "ถ้าให้เดา คุณต้องเป็นคนที่เหลืออยู่ขององค์กรนั้น เป็นคนที่ฝึกศิลปะการฆ่าด้วย",
  ui_story_5053_50531302_41_dialog_content = "ท้ายที่สุด ความคล้ายคลึงกันระหว่างคุณกับเจ้านายเก่าของฉันนั้นช่างแปลกประหลาด",
  ui_story_5053_50531302_42_dialog_content = "ด้วยเหตุนี้คุณจึงไม่สามารถแทนที่เธอได้ เลดี้โจชัวในปัจจุบันเป็นภรรยาที่รัก เป็นแม่ที่ทะนุถนอม และน้องสาวผู้ห่วงใย",
  ui_story_5053_50531302_43_dialog_content = "ฉันพูดถูกต้องหรือไม่?",
  ui_story_5053_50531302_44_dialog_content = "...",
  ui_story_5053_50531302_45_dialog_content = "L-Lady Joshua มีกริชอยู่ในมือ! ห่าเธอดึงมันออกมาจากที่ไหนไม่ได้ ... ?",
  ui_story_5053_50531302_46_dialog_content = "อ๊ะ นั่นมัน! ลูกแก้วของฉันอยู่ไหน!",
  ui_story_5053_50531302_47_dialog_content = "ไม่ผิดแน่ Jakine... เธอคือน้องสาวของฉันจริงๆ แต่ทำไม... เป็นไปได้ไง!",
  ui_story_5053_50531302_48_dialog_content = "เลิกยืนเฉยได้แล้ว คาเลบ! ถ้าไม่สู้ก็หลบ!",
  ui_story_5053_50531302_49_dialog_content = "<size=45>อ๊าาาา—!</size>",
  ui_story_5053_50531302_50_dialog_content = "ฉัน-คือเธอ—!!",
  ui_story_5053_50531302_51_dialog_content = "มันคือดาร์คแองเจิ้ล!",
  ui_story_5053_50531302_52_dialog_content = "เทพบุตรรัตติกาล...?",
  ui_story_5053_50531302_53_dialog_content = "ห่างจาก... จาก Caleb...",
  ui_story_5053_50531302_54_dialog_content = "<size=45>ปล่อย... คาเลบ... คนเดียว!!!</size>",
  ui_story_5053_50531302_55_dialog_content = "คุณมานี่ได้ยังไงเนี่ย!?",
  ui_story_5053_50531302_56_dialog_content = "ไปให้พ้นฉัน ไอ้สารเลว!",
  ui_story_5053_50531302_57_dialog_content = "ไม่มีทางหนี!",
  ui_story_5053_50531302_58_dialog_content = "สุภาพสตรีหมายเลขหนึ่ง Joshua ต้องการจะฆ่าพวกเรา และตอนนี้ Dark Angel ก็ไล่เธอไป...",
  ui_story_5053_50531302_59_dialog_content = "ห-ห่า นี่มันเกิดอะไรขึ้นอีกแล้วเนี่ย?! มีคนต้องการอธิบายความยุ่งเหยิงนี้เดี๋ยวนี้!",
  ui_story_5053_50531302_60_dialog_content = "W-โอ้โฮ ฮิปโปคา! หยุด...!!",
  ui_story_5053_50531302_61_dialog_content = "ว้าว! และตอนนี้ ม้าแมงมุมยักษ์บินผ่านหน้าต่าง!!!",
  ui_story_5053_50531302_62_dialog_content = "รอ... PlayerName?! กับ Mia และ Lord Schwartz!",
  ui_story_5053_50531302_63_dialog_content = "ทำได้ดีมากมีอา ดูเหมือนว่าคุณจะมีพรสวรรค์ในการใช้ซัมมอน Lumina ของคุณเป็นพาหนะ",
  ui_story_5053_50531302_64_dialog_content = "*อ้าปากค้าง* พูดตามตรง... นั่นเป็นครั้งแรกที่ฉันใช้ฮิปโปคาแบบนั้น...",
  ui_story_5053_50531302_65_dialog_content = "ฮึ... เรากระโดดข้ามตึกมากมายบนหลังของฮิปโปคา... ฉันคิดว่าฉันคงจะป่วย...",
  ui_story_5053_50531302_66_dialog_content = "คุณสามคนเป็นอะไร...",
  ui_story_5053_50531302_67_dialog_content = "ดี ดูเหมือนว่า Caleb และ Jakine จะยังโอเค...",
  ui_story_5053_50531302_68_dialog_content = "ขอบคุณพระเจ้าที่พวกเรามาทันเวลา... เอิ๊ก...!",
  ui_story_5053_50531401_1_dialog_content = "นี่คุณกำลังบอกว่าปีศาจขาวกำลังเล่นงานพวกเราให้โง่เขลามาโดยตลอด",
  ui_story_5053_50531401_2_dialog_content = "และว่าเธอกับ Dark Angel ต่างเป็นส่วนหนึ่งของ Lady Joshua แต่พวกเขาไม่สามารถตกลงกันได้",
  ui_story_5053_50531401_3_dialog_content = "ดังนั้นแผนของเธอคือฆ่าพวกเราทั้งหมด ดูดซับ Lumina ของเรา และปลดปล่อยตัวเองไปกับมัน...",
  ui_story_5053_50531401_4_dialog_content = "แม้จะฟังดูไม่น่าเชื่อ แต่ฉันคิดว่าฉันเข้าใจสถานการณ์ของเธอ",
  ui_story_5053_50531401_5_dialog_content = "ปวดหัวจนแยกไม่ออก กลัวตัวตนอื่นของเธอ...",
  ui_story_5053_50531401_6_dialog_content = "แม้ว่าเราจะแตกต่างกันมาก แต่ฉันกับบาบายากะก็เป็นหนึ่งเดียวกัน",
  ui_story_5053_50531401_7_dialog_content = "และถ้าฉันสามารถเรียนรู้ที่จะอยู่ร่วมกับเธอได้ แม่ก็จะสามารถ...",
  ui_story_5053_50531401_8_dialog_content = "คุณคิดว่าเรายังมีโอกาสโน้มน้าว White Demon ให้เลิกแผนการบ้าๆ ของเธอไหม PlayerName?",
  ui_story_5053_50531401_9_dialog_content = "อืม... ฉันคิดว่ามีเพียง Lady Joshua ตัวจริงเท่านั้นที่รู้เรื่องนี้",
  ui_story_5053_50531401_10_dialog_content = "ทั้งหมดที่ฉันรู้ก็คือ Crystal of Eternal Memory ใกล้จะหมดจาก Lumina แล้ว",
  ui_story_5053_50531401_11_dialog_content = "นี่เป็นโอกาสสุดท้ายที่เราจะออกไปจากที่นี่ เราไม่สามารถเสียเวลาไปกับการคิดมาก",
  ui_story_5053_50531401_12_dialog_content = "โปรดยกโทษให้ฉัน แต่ฉันไม่สามารถปราบเลดี้โจชัวคนอื่นได้",
  ui_story_5053_50531401_13_dialog_content = "ยามเพิ่งแจ้งเตือนฉันว่าสถานการณ์ในจัตุรัสกลางตอนนี้อยู่ภายใต้การควบคุมแล้ว",
  ui_story_5053_50531401_14_dialog_content = "อย่างไรก็ตาม มังกรยังคงเป็นภัยคุกคามอย่างไม่หยุดยั้ง กองกำลังของเราจะไม่ยืนหยัดต่อสู้กับศัตรูที่ไร้เทียมทานแบบนี้ได้อีกต่อไป",
  ui_story_5053_50531401_15_dialog_content = "ขอบคุณสำหรับความช่วยเหลือ คุณร็อต คุณสามารถปล่อยให้ส่วนที่เหลือเป็นของเรา",
  ui_story_5053_50531401_16_dialog_content = "ฉันเกรงว่าจะต้องปฏิเสธ",
  ui_story_5053_50531401_17_dialog_content = "หน้าที่ของฉันคือปกป้อง House Schwartz และ Lumopolis ทั้งหมด",
  ui_story_5053_50531401_18_dialog_content = "ไม่ว่าฉันจะเป็นเพียงภาพลวงตาหรือไม่ก็ไม่มีผลต่อหน้าที่ของฉัน ฉันเป็นและจะเป็นตลอดไป Ms Rot",
  ui_story_5053_50531401_19_dialog_content = "แม้จะเผชิญกับวิกฤตอัตถิภาวนิยมที่สั่นสะเทือน ความสงบของคุณยังคงไม่สั่นคลอน",
  ui_story_5053_50531401_20_dialog_content = "เฮ่เฮ่... พูดตามตรง การตระหนักรู้นี้ทำให้ข้ารู้สึกโล่งใจ",
  ui_story_5053_50531401_21_dialog_content = "ตอนนี้ฉันรู้แล้วว่าไม่มีอนาคตสำหรับตัวเอง ฉันไม่มีเหตุผลที่จะต้องกังวลเกี่ยวกับเรื่องนี้ตลอดเวลา",
  ui_story_5053_50531401_22_dialog_content = "ถ้าใครเจ็บปวดจากความจริงตอนนี้ ก็คงจะเป็นคุณคาเลบ",
  ui_story_5053_50531401_23_dialog_content = "โจชัว... ไม่เคยต้องการให้ใครรู้ความจริงเกี่ยวกับอดีตของเธอ",
  ui_story_5053_50531401_24_dialog_content = "ในแง่หนึ่ง การเปิดเผยอดีตของเธอรังแต่จะเชิญชวนให้วิจารณ์มากขึ้น",
  ui_story_5053_50531401_25_dialog_content = "อย่างไรก็ตาม ฉันเชื่อว่าเหตุผลที่แท้จริงก็คือเธอไม่มีใจที่จะสารภาพเรื่องนี้กับน้องชายคนเล็กของเธอ",
  ui_story_5053_50531401_26_dialog_content = "ในทางหนึ่ง ความแข็งแกร่งและความใจดีที่เธอค้นพบในช่วงหลายปีที่ผ่านมาก็ก่อให้เกิดจุดอ่อนที่ยิ่งใหญ่ที่สุดของเธอเช่นกัน",
  ui_story_5053_50531401_27_dialog_content = "ฉันรู้ว่าคุณหมายถึงอะไร การที่เลดี้โจชัวได้เติบโตและมีประสบการณ์กับอารมณ์มากมายนั้นเป็นสิ่งที่ดี",
  ui_story_5053_50531401_28_dialog_content = "แต่บางครั้งปัญหาสามารถแก้ไขได้ด้วยการสื่อสารอย่างเปิดเผยและจริงใจเท่านั้น แม้ว่าการทำเช่นนั้นจะดูน่ากลัวก็ตาม",
  ui_story_5053_50531401_29_dialog_content = "เมื่อ Lady Joshua ฟื้นคืนชีพในโลกแห่งความเป็นจริงในที่สุด ฉันต้องขอให้คุณแบ่งปันความคิดที่จริงใจเหล่านี้กับเธอเช่นกัน",
  ui_story_5053_50531401_30_dialog_content = "มิฉะนั้นเธออาจโกรธจัดจนเสียสติอีกครั้ง",
  ui_story_5053_50531401_31_dialog_content = "...ผมจะจำทำ.",
  ui_story_5053_50531401_32_dialog_content = "เอ่อ ลอร์ดชวาร์ตซ์? คุณกับคุณร็อตคุยกันเสร็จแล้วหรือยัง? เรายังคงต้องคุยกันถึงแผนขั้นต่อไป",
  ui_story_5053_50531401_33_dialog_content = "ได้เลย",
  ui_story_5053_50531401_34_dialog_content = "...เดี๋ยวก่อน คาเลบอยู่ไหน? เขารู้สึกดีขึ้นหรือยัง?",
  ui_story_5053_50531401_35_dialog_content = "ปล่อยให้เขาเป็นตอนนี้",
  ui_story_5053_50531401_36_dialog_content = "...",
  ui_story_5053_50531401_37_dialog_content = "คุณคือ... น้องสาวของฉันจริงๆ... ?",
  ui_story_5053_50531401_38_dialog_content = "—!",
  ui_story_5053_50531401_39_dialog_content = "ทำไมคุณถึงซ่อนตัวจากฉัน",
  ui_story_5053_50531401_40_dialog_content = "ปีศาจขาวพูดความจริงหรือไม่? เป็นไปได้ไหมว่า...คุณไม่เคยเห็นฉันเป็นครอบครัวอย่างแท้จริง?",
  ui_story_5053_50531401_41_dialog_content = "... เลขที่...",
  ui_story_5053_50531401_42_dialog_content = "คาเลบ... ฉัน... กลัว...",
  ui_story_5053_50531401_43_dialog_content = "กลัวเหรอ",
  ui_story_5053_50531401_44_dialog_content = "คาเลบ... รักฉัน... เชื่อใจฉัน...",
  ui_story_5053_50531401_45_dialog_content = "หน้าอก... เจ็บ... ความดัน... หายใจไม่ออก...",
  ui_story_5053_50531401_46_dialog_content = "พ่อ.. ปล่อย... ตาย... เพื่อปกป้องฉัน... ทั้งหมด... ความผิดของฉัน...",
  ui_story_5053_50531401_47_dialog_content = "คุณหมายความว่าอย่างไร...?",
  ui_story_5053_50531401_48_dialog_content = "ส่วนอื่น ๆ ของคุณบอกว่าพ่อฆ่าตัวตายเพื่อรักษาความพยาบาทที่คุอยู่",
  ui_story_5053_50531401_49_dialog_content = "แต่คุณกำลังบอกว่าเขาปล่อยมันไป... ฉันบอกไม่ได้ว่าอะไรคือความจริงอีกต่อไป",
  ui_story_5053_50531401_50_dialog_content = "คุณสวมรอยเป็นน้องสาวของฉันตลอดหลายปีที่ผ่านมา เพื่อที่จะได้ลอบฆ่าพ่อของชวาร์ตซ์",
  ui_story_5053_50531401_51_dialog_content = "คุณเลี้ยงฉันและดูแลฉันเหมือนน้องสาวแท้ๆ... ไม่สิ เหมือนแม่ต่างหาก",
  ui_story_5053_50531401_52_dialog_content = "ตลอดเวลาหลายปีที่อดทนกับข้า... ความเครียดคงเกินทนแล้ว",
  ui_story_5053_50531401_53_dialog_content = "... แต่ตอนนี้มันไม่สำคัญแล้ว โจชัว ความสุขของคุณจะมีความสำคัญกับฉันเสมอ ในตอนนี้และตลอดไป",
  ui_story_5053_50531401_54_dialog_content = "เมื่อเรากลับไปสู่ความเป็นจริง หากเจ้าไม่เห็นข้าเป็นพี่ชายของเจ้าจริงๆ... ข้าจะไม่รบกวนเจ้าอีก ฉันต้องการให้คุณใช้ชีวิตอย่างอิสระและไม่เสียใจเหมือนที่คุณต้องการมาตลอด",
  ui_story_5053_50531401_55_dialog_content = "ไม่... ได้โปรด... อย่าทิ้งฉันไป... คาเลบ...",
  ui_story_5053_50531401_56_dialog_content = "ฉันผิด...ที่โกหก...แต่...ฉันกลัว...",
  ui_story_5053_50531401_57_dialog_content = "กลัว...เธอ...จะเกลียดฉัน...",
  ui_story_5053_50531401_58_dialog_content = "...",
  ui_story_5053_50531401_59_dialog_content = "ฉันไม่มีวันเกลียดคุณ โจชัว",
  ui_story_5053_50531401_60_dialog_content = "คุณเป็นน้องสาวที่สวยงามและอ่อนโยนที่สุดที่ใครๆ ก็ร้องขอ",
  ui_story_5053_50531401_61_dialog_content = "ฉันจะไม่พอใจคุณในทางใดทางหนึ่งได้อย่างไร?",
  ui_story_5053_50531401_62_dialog_content = "เอาล่ะ ให้ฉันอธิบายทุกอย่างเป็นครั้งสุดท้าย",
  ui_story_5053_50531401_63_dialog_content = "เราได้หยุดยั้งแผนก่อนหน้านี้ของ White Demon ที่จะฆ่าเรา",
  ui_story_5053_50531401_64_dialog_content = "เมื่อไม่มีที่ไป มีโอกาสที่ดีที่เธอจะใช้มังกรและเหล่าผู้ควบคุมจิตใจเพื่อเริ่มการโจมตีครั้งสุดท้ายที่สิ้นหวัง",
  ui_story_5053_50531401_65_dialog_content = "แม้ว่าตอนนี้เราจะได้เปรียบด้านตัวเลข แต่ Schwartz หนุ่มก็ยังปัดป้องเจ้ามังกรได้...",
  ui_story_5053_50531401_66_dialog_content = "เขาและกองกำลังของเขาจะไม่สามารถต่อสู้อย่างเต็มกำลังได้ ไม่ว่า Lumina จะเหลืออยู่ใน Crystal of Eternal Memory เพียงเล็กน้อยก็ตาม",
  ui_story_5053_50531401_67_dialog_content = "ไม่เพียงแค่นั้น เหลืออีกเพียงไม่กี่ชั่วโมงในแต่ละวัน",
  ui_story_5053_50531401_68_dialog_content = "เราต้องการวิธีที่ง่ายและมีประสิทธิภาพที่จะช่วยให้เราจัดการกับเบี้ยของ White Demon ทั้งหมดในระยะเวลาที่สั้นที่สุดเท่าที่จะเป็นไปได้",
  ui_story_5053_50531401_69_dialog_content = "เป็นทางเดียวที่เราจะจับเธอได้",
  ui_story_5053_50531401_70_dialog_content = "Crystal of Eternal Memory นั้นมีประโยชน์อย่างอื่นอีกไหม Jakine? เราสามารถใช้มันเพื่อจัดการกับภาพลวงตาอื่น ๆ เช่นเดียวกับ White Demon ได้หรือไม่?",
  ui_story_5053_50531401_71_dialog_content = "อืม... ไม่นะ! ด้วยจำนวน Lumina ที่เหลือเพียงน้อยนิด Crystal of Eternal Memory จึงไม่สามารถใช้ทำอย่างอื่นได้นอกจากรักษาโลกรอบตัวเรา",
  ui_story_5053_50531401_72_dialog_content = "นอกจากนี้ Crystal of Eternal Memory นี้เป็นเพียงอุปกรณ์ที่ไม่ปลอดภัย",
  ui_story_5053_50531401_73_dialog_content = "มันไม่ควรถูกใช้มากขนาดนี้ตั้งแต่แรก... เราได้แหกกฎมามากพอแล้วตั้งแต่ได้ลงมือทำ",
  ui_story_5053_50531401_74_dialog_content = "แต่ถ้าฉันรวบรวมคาถาได้ดีกว่าครั้งที่แล้ว...!",
  ui_story_5053_50531401_75_dialog_content = "ไม่นะ จาคีน สถานการณ์ของเราเลวร้ายเกินกว่าที่เราจะหันไปใช้คาถาชั่วคราวของคุณ",
  ui_story_5053_50531401_76_dialog_content = "หึหึหึหึหึหึ...",
  ui_story_5053_50531401_77_dialog_content = "ไม่จำเป็นหรอก",
  ui_story_5053_50531401_78_dialog_content = "สิ่งที่เราต้องทำคือปล่อยให้พวกมันทำลายตัวเอง",
  ui_story_5053_50531401_79_dialog_content = "ยินดีต้อนรับกลับมา คาเลบ! ร้องไห้กันหมดแล้วเหรอ?",
  ui_story_5053_50531401_80_dialog_content = "ฉันไม่ได้ร้องไห้! กล้าดียังไงมาทำกับฉันเหมือนเด็ก!",
  ui_story_5053_50531401_81_dialog_content = "คุณหมายถึงอะไรเคเลบ? ทำไมพวกเขาถึงทำลายตัวเองในเมื่อทั้งหมดอยู่ภายใต้การควบคุมของปีศาจขาว?",
  ui_story_5053_50531401_82_dialog_content = "มันง่ายจริงๆ",
  ui_story_5053_50531401_83_dialog_content = "การทำลายสมดุลของ Lumina ในร่างกายจะทำให้สูญเสียความสามารถในการควบคุมตนเอง อย่างเจ็บปวดฉันอาจเพิ่ม",
  ui_story_5053_50531401_84_dialog_content = "\"สมดุลแห่งลูมิน่า\"? ฉันไม่เคยได้ยินอะไรแบบนั้นมาก่อน",
  ui_story_5053_50531401_85_dialog_content = "ฮึ่ม ชาวออโรเรียนธรรมดาไม่มีวันเข้าใจ แต่ข้าเชื่อว่าสหายชาวคาเลสของเรารู้ดีว่าข้าพูดถึงอะไร ไม่ว่าใช่มั้ย?",
  ui_story_5053_50531401_86_dialog_content = "เอ็ม-มี? เอ่อ... ฉันสังเกตเห็นบางอย่างที่แตกต่างออกไปเกี่ยวกับเส้นแสงของพวกเขา...",
  ui_story_5053_50531401_87_dialog_content = "คำตอบที่น่าสงสัยของคุณคือ... ค่อนข้างน่าผิดหวัง",
  ui_story_5053_50531401_88_dialog_content = "<size=30>PlayerNameก่อนหน้านี้ฉันรู้สึกว่า Caleb เริ่มเป็นศัตรูกับเรามากขึ้น บางทีเขาอาจจะเป็นคนเน่าเฟะก็ได้นะ?</size>",
  ui_story_5053_50531401_89_dialog_content = "<size=30>อืม ไม่มีความคิดเห็น...</size>",
  ui_story_5053_50531401_90_dialog_content = "คุณสองคน! ห้ามคุยระหว่างเรียน!",
  ui_story_5053_50531401_91_dialog_content = "หลงกลมามากพอแล้ว คาเลบ บอกแผนของคุณให้เราทราบ",
  ui_story_5053_50531401_92_dialog_content = "ฉันสามารถเตรียมยาบางประเภทได้ ซึ่งเป็นยาที่ทำให้ลูมิน่าของผู้ใช้ไม่เสถียร คิดว่ามันเป็นพิษที่พุ่งเป้าไปที่ Lumina โดยตรง",
  ui_story_5053_50531401_93_dialog_content = "ทุกสิ่งภายใน Crystal of Eternal Memory ถูกสร้างขึ้นจากการผสมผสานระหว่าง Lumina ของ Joshua และน้ำของ Lake Mirror",
  ui_story_5053_50531401_94_dialog_content = "ด้วยเหตุนี้ ยานี้ควรพิสูจน์ได้ว่ามีประสิทธิภาพสูงในการต่อต้านศัตรูของเรา",
  ui_story_5053_50531401_95_dialog_content = "แต่ด้วยส่วนผสมที่มีอยู่น้อยนิด ฉันจึงเสนอให้เราใช้มันเพื่อต่อสู้กับมังกร",
  ui_story_5053_50531401_96_dialog_content = "หุ่นเชิดที่ควบคุมจิตใจของ White Demon ไม่มีอะไรมากไปกว่ามดที่เป็นอันตราย หากเรานำมังกรลงมาโจมตีพวกเขา...",
  ui_story_5053_50531401_97_dialog_content = "ความเจ็บปวดที่เกิดจากยาจะทำให้มันกระทืบและดิ้นไปกับพื้น บดขยี้ศัตรูของเราในกระบวนการนี้",
  ui_story_5053_50531401_98_dialog_content = "อะฮ่า! พูดอีกอย่างก็คือ ถ้าเราป้อนยาพิษให้มังกรได้ มันก็จะร่วงลงมาใส่หัวที่ไร้สติของพวกมัน!",
  ui_story_5053_50531401_99_dialog_content = "...ในลักษณะการพูดใช่.",
  ui_story_5053_50531401_100_dialog_content = "ฉันต้องบอกว่าแผนของคุณค่อนข้างบ่งบอกถึงสไตล์ปกติของคุณ คุณมักจะชอบเล่ห์เหลี่ยมที่เรียบง่ายแต่น่ากลัวเช่นนี้เสมอ",
  ui_story_5053_50531401_101_dialog_content = "ฉันแปลกใจที่นายยังจำได้ ถ้วยชาของฉันน่าจดจำจริงๆเหรอ?",
  ui_story_5053_50531401_102_dialog_content = "(เดี๋ยวก่อน... Caleb เคยวางยาลอร์ด Schwartz ในอดีตหรือเปล่า?!)",
  ui_story_5053_50531401_103_dialog_content = "<size=30>คุณไม่ใช่คนดีเลยจริงๆ Caleb!</size>",
  ui_story_5053_50531401_104_dialog_content = "ฟฟฟฟ...ฮิฮิฮิ...",
  ui_story_5053_50531401_105_dialog_content = "หยุดหัวเราะได้แล้ว มีอา",
  ui_story_5053_50531401_106_dialog_content = "ฉันขอโทษ ฉันช่วยไม่ได้... เดี๋ยวก่อน ฉันไม่ได้หมายความอย่างนั้น...",
  ui_story_5053_50531401_107_dialog_content = "ฉันมีวัตถุดิบเพียงพอสำหรับปรุงยามื้อเดียว ฉันต้องการใครสักคนที่ทรงพลังเพื่อปราบมังกรให้นานพอที่ฉันจะปรุงยาได้ คนอย่างคุณ.",
  ui_story_5053_50531401_108_dialog_content = "ฮ-ฮะ? ฉัน...?!",
  ui_story_5053_50531401_109_dialog_content = "ใช่คุณ. ตอนนี้ตามฉันมา",
  ui_story_5053_50531401_110_dialog_content = "ดะ-เดี๋ยวก่อนลุง...!",
  ui_story_5053_50531401_111_dialog_content = "หนีไปทำเรื่องของตัวเองอีกแล้ว! คิดว่าเราควรตามพวกเขาไหม?",
  ui_story_5053_50531401_112_dialog_content = "ฝากมังกรไว้กับคาเลบ ฉันเชื่อในตัวเขาเช่นเดียวกับมีอา",
  ui_story_5053_50531401_113_dialog_content = "ลอร์ดชวาตส์...",
  ui_story_5053_50531401_114_dialog_content = "ตามที่คุณบอก ฉันมักจะเอาชีวิตรอดจากแผนการของ White Demon จนถึงตอนจบ แต่ฉันไม่สามารถเปลี่ยนผลลัพธ์ได้",
  ui_story_5053_50531401_115_dialog_content = "ฮีโร่รุ่นเยาว์ของคุณมีความสามารถในการสร้างอนาคตได้มากกว่าที่ฉันเคยเป็น",
  ui_story_5053_50531401_116_dialog_content = "ฉันคิดเสมอว่าฉันสามารถปกป้องทุกสิ่งได้ด้วยสองมือของฉันเอง... แต่ดูเหมือนถึงเวลาแล้วที่จะต้องละทิ้งทิฐิอันดื้อรั้นของฉัน",
  ui_story_5053_50531401_117_dialog_content = "งั้นเราควรจะอยู่ที่นี่ต่อไปดีไหม?",
  ui_story_5053_50531401_118_dialog_content = "ครับ จาคีน เราจะอยู่ที่นี่เพื่อรวบรวมไหวพริบและกำลังของเรา",
  ui_story_5053_50531401_119_dialog_content = "เมื่อรู้จักปีศาจขาว เธอจะปรากฏตัวต่อหน้าเราในการต่อสู้ครั้งสุดท้ายหลังจากที่ไพ่ตายของเธอพ่ายแพ้",
  ui_story_5053_50531401_120_dialog_content = "นั่นคือคู่ต่อสู้ที่เหนียวแน่นที่เราเผชิญหน้า",
