  ui_story_5053_50531401_125_dialog_content = "เราจึงพบว่าตัวเองอยู่ที่นี่อีกครั้ง คุณและฉันยืนอยู่ที่โต๊ะนี้ในตอนเย็น",
  ui_story_5053_50531401_126_dialog_content = "...",
