  ui_story_5053_50531401_129_dialog_content = "แดกดันพอคุณยืนอยู่ต่อหน้าฉันตลอดเวลาและเห็นฉันเลวร้ายที่สุด ไม่น่าแปลกใจเลยที่คุณโกรธฉันมาก",
  ui_story_5053_50531401_130_dialog_content = "ง...ดาเนียล...",
  ui_story_5053_50531401_131_dialog_content = "คุณพูดถูก นี่เป็นความผิดของฉันทั้งหมด และความอาฆาตพยาบาทของคุณที่มีต่อฉันเป็นสิ่งที่ถูกต้อง อย่างไรก็ตาม คุณยังไม่สามารถฆ่าฉันได้",
  ui_story_5053_50531401_132_dialog_content = "เด็กพวกนี้ไร้เดียงสา ไม่สมควรตายในที่แห่งนี้",
