  ui_story_5053_50531401_140_dialog_content = "ใช่เพลงนั้นจริงๆ พูดตามตรง ฉันเตรียมของขวัญให้คุณเมื่อสิบสองปีที่แล้ว",
  ui_story_5053_50531401_141_dialog_content = "แต่ด้วยความร้อนใจ ฉันลืมมอบมันให้กับเธอ ถ้าจำไม่ผิด...น่าจะตรงนี้แหละ",
  ui_story_5053_50531401_142_dialog_content = "บันทึก?",
  ui_story_5053_50531401_143_dialog_content = "ถูกตัอง. ฉันมีคนบันทึกเวอร์ชันเต้นรำของเพลงเดียวกันนั้น คุณต้องการที่จะฟังมัน? มีเครื่องเล่นแผ่นเสียงอยู่ตรงนี้",
