  ui_story_5053_50531401_151_dialog_content = "ดา...แดเนียล...",
  ui_story_5053_50531401_152_dialog_content = "ว่ายังไง",
  ui_story_5053_50531401_153_dialog_content = "ทุกคน... สบายดีไหม...?",
  ui_story_5053_50531401_154_dialog_content = "...ใช่ ค่อนข้างดี",
  ui_story_5053_50531401_155_dialog_content = "ตอนนี้ Carleen เป็นหัวหน้าหน่วยพิทักษ์ของ Lumopolis และสั่งการทีมของผู้ใต้บังคับบัญชาที่เป็นแบบอย่าง ไม่เพียงแค่นั้น เธอยังได้เพื่อนที่ไว้ใจได้อีกมากมาย",
  ui_story_5053_50531401_156_dialog_content = "Mia ยังคงอยู่ภายใต้การดูแลและคำแนะนำของ Istvan อาการของเธอดีขึ้นอย่างมาก ฉันได้ยินมาว่าเธอสามารถออกไปข้างนอกและเล่นระหว่างวันได้แล้ว",
  ui_story_5053_50531401_157_dialog_content = "สำหรับ Caleb... ดูเหมือนว่าเขาจะทำได้ดีทีเดียวสำหรับตัวเขาเองใน Dawn Academy ฉันพนันได้เลยว่าเขาคิดถึงคุณอย่างสุดซึ้งยิ่งกว่าใครๆ ในโลก",
