  ui_story_5053_50531401_159_dialog_content = "หืม?",
  ui_story_5053_50531401_160_dialog_content = "เวลาของฉันหมดลงแล้ว โจชัว",
  ui_story_5053_50531401_161_dialog_content = "เมื่อก่อนฉันทำอะไรไม่ถูก และฉันทำผิดพลาดมากเกินกว่าจะนับได้ แต่ตอนนี้ บัดนี้ ลูกๆ ของเรายืนบนไหล่ของฉัน เอื้อมขึ้นไปสูงกว่าที่ฉันเคยรู้",
  ui_story_5053_50531401_162_dialog_content = "สิ่งที่เหลืออยู่ที่ฉันต้องทำคือยืนหยัดในที่แห่งนี้ สนับสนุนพวกเขาในขณะที่พวกเขามุ่งมั่นเพื่ออนาคตที่สดใส",
  ui_story_5053_50531401_163_dialog_content = "อนาคตในอุดมคติที่คุณและฉันใฝ่ฝันมาตลอด",
  ui_story_5053_50531401_164_dialog_content = "เมื่อเรากลับมา ฉันจะจัดการให้คุณพักฟื้นในที่ปลอดภัยและเป็นส่วนตัวในบ้านของ Caleb",
  ui_story_5053_50531401_165_dialog_content = "หลังจากนั้น ฉันจะให้เวโรนิกากลับไปกับคุณ และแบ่งปันข่าวดีกับคาร์ลีน อีกไม่นานครอบครัวของเราจะกลับมาสมบูรณ์อีกครั้ง",
  ui_story_5053_50531401_166_dialog_content = "แค่ตอนนี้... ก็อย่างที่คุณเห็น ฉันค่อนข้างแก่แล้ว ตอนนี้ฉันอาจไม่คู่ควรกับความเป็นเพื่อนของคุณด้วยซ้ำ แต่ฉันจะขอบคุณมากถ้าคุณอนุญาตให้ฉันไปเยี่ยมเป็นครั้งคราว จะไม่เป็นไรเหรอ?",
