  ui_story_5053_50531401_219_dialog_content = "\"ไม่กี่ครั้ง\" คุณพูด? ทำไมคุณถึงใช้ของกำนัลที่หายากและมีค่าเช่นนี้อย่างสุรุ่ยสุร่าย!",
