  ui_story_5053_50531401_232_dialog_content = "ซึ่งเป็นเหตุผลที่คุณไม่ควรฟังพวกเขาหรือพ่อของคุณ! ถ้าพวกเขาบอกคุณว่าอย่าทำอะไร นั่นคือเหตุผลที่คุณควรทำ! ชีวิตอัจฉริยะมีแต่อุปสรรค!!",
