  ui_story_5053_50531401_235_dialog_content = "คุณต้องปลดปล่อยพลังทุกออนซ์ของคุณที่นี่และเดี๋ยวนี้! ปล่อยให้มันไหลผ่านทุกเซลล์ในร่างกายของคุณและปลดปล่อยมันทั้งหมดในคราวเดียว!",
