  ui_story_5053_50531501_24_dialog_content = "Zzzzz...ห๊ะ? นั่นใคร?! เอามือออกจากคริสตัลของฉัน!!!",
  ui_story_5053_50531501_25_dialog_content = "H-เฮ้... เกิดอะไรขึ้นกับ Crystal of Eternal Memory?!",
  ui_story_5053_50531501_26_dialog_content = "ทะ...ทำไม...",
  ui_story_5053_50531501_27_dialog_content = "ทำไมคุณถึงเลือกเข้าข้างสิ่งมีชีวิตที่น่าขยะแขยงนั่น...?",
  ui_story_5053_50531501_28_dialog_content = "แม่...หน้าเธอ...",
  ui_story_5053_50531501_29_dialog_content = "ดูรอยแตกที่ปรากฏบนใบหน้าของเธอสิ! พวกมันมีสีเดียวกับ Dark Angel!",
  ui_story_5053_50531501_30_dialog_content = "ทำไมเธอไม่เลือกฉัน...?",
  ui_story_5053_50531501_31_dialog_content = "ทำไมไม่มีใครเข้าใจความสำคัญของอุดมคติของฉันเลย...?",
  ui_story_5053_50531501_32_dialog_content = "<size=45>ทำไม?!?</size>",
  ui_story_5053_50531501_33_dialog_content = "ช-เธอกำลังจะกลายร่างเป็นดาร์คแองเจิ้ล!!",
  ui_story_5053_50531501_34_dialog_content = "เมียหลวงพูดถูก! เขาสองคนเหมือนกัน...",
  ui_story_5053_50531501_35_dialog_content = "เดาว่าเราคงไม่มีเวลาคุยเรื่องการยอมจำนนของเธอเรื่องชาและคุกกี้! มารับเธอ!",
  ui_story_5053_50531501_36_dialog_content = "ม-แม่... ฉันขอโทษ!",
  ui_story_5053_50531501_37_dialog_content = "โจชัว...",
  ui_story_5053_50531501_38_dialog_content = "ตอนนี้คุณลังเลอยู่ตลอดเวลา Caleb?",
  ui_story_5053_50531501_39_dialog_content = "แม้แต่ลูกสาวคนโตของฉันก็ยังแสดงความกล้าหาญมากกว่าคุณในตอนนี้",
  ui_story_5053_50531501_40_dialog_content = "บันทึกไว้ ชวาร์ตษ์! เรื่องของน้องสาวฉัน คุณคนเดียวไม่มีสิทธิ์โทษใคร!",
  ui_story_5053_50531501_41_dialog_content = "รอจนกว่าเราจะกลับมาในโลกแห่งความเป็นจริง!",
  ui_story_5053_50531501_42_dialog_content = "(เด็กโง่ แม้จะผ่านมาหลายปี คุณก็ยังควบคุมอารมณ์ไม่ได้)",
  ui_story_5053_50531501_43_dialog_content = "...",
  ui_story_5053_50531502_1_dialog_content = "เอิ๊ก...!!",
  ui_story_5053_50531502_2_dialog_content = "จากิน!",
  ui_story_5053_50531502_3_dialog_content = "ทางข้างหน้าของคุณ !!",
  ui_story_5053_50531502_4_dialog_content = "S-อยู่ข้างหลัง...",
  ui_story_5053_50531502_5_dialog_content = "มันจบลงแล้ว โจชัว",
  ui_story_5053_50531502_6_dialog_content = "อย่าเข้ามานะ...!",
  ui_story_5053_50531502_7_dialog_content = "การดิ้นรนจะทำให้เจ็บปวดมากขึ้นเท่านั้น",
  ui_story_5053_50531502_8_dialog_content = "อยู่ให้ห่างฉัน!!!",
  ui_story_5053_50531502_9_dialog_content = "ท่านชวาร์ตษ์!",
  ui_story_5053_50531502_10_dialog_content = "<size=45>ใบมีดของจักรพรรดิ—</size>",
  ui_story_5053_50531502_11_dialog_content = "อู้วววว!!",
  ui_story_5053_50531502_12_dialog_content = "ทั้งหมดเป็นความผิดของคุณ...",
  ui_story_5053_50531502_13_dialog_content = "...",
  ui_story_5053_50531502_14_dialog_content = "คุณ...ทำให้ฉันอ่อนแอ...",
  ui_story_5053_50531502_15_dialog_content = "เวโรนิกากับคาร์ลีน... คาเลบกับบลองก์... และชวาร์ตษ์",
  ui_story_5053_50531502_16_dialog_content = "พวกมันเป็นสวะที่ทรยศ พวกมันทุกตัว!!",
  ui_story_5053_50531502_17_dialog_content = "คุณจะยอมมอบอุดมคติของคุณให้กับพวกเขาได้อย่างไร! เจ้าไร้ค่า คนโง่เขลาสิ้นดี—",
  ui_story_5053_50531502_18_dialog_content = "Mia ช่วยฉันทำสิ่งนี้ให้เสร็จ เราจะปล่อยให้น้องสาวของฉันทำร้ายตัวเองต่อไปไม่ได้",
  ui_story_5053_50531502_19_dialog_content = "ได้สิ...",
  ui_story_5053_50531502_20_dialog_content = "รอ! อย่าเข้าใกล้เธอ!",
  ui_story_5053_50531502_21_dialog_content = "หากเป็นเช่นนี้ก็ต้องจบลง...ก็ในนามของการล้างแค้น...",
  ui_story_5053_50531502_22_dialog_content = "ฉันสาบานว่าจะทำลายพวกนายทุกคนให้สิ้นซาก...",
  ui_story_5053_50531502_23_dialog_content = "...ฮะ? ลมอะไรเบอร์นี้",
  ui_story_5053_50531502_24_dialog_content = "ดู! เธอเริ่มดูดซับ Lumina ภายใน Crystal of Eternal Memory!",
  ui_story_5053_50531502_25_dialog_content = "นี่เธอ... พยายามจะดึงเราลงไปกับเธองั้นเหรอ?!",
  ui_story_5053_50531502_26_dialog_content = "Jakine เตรียมพาพวกเราออกไปจากที่นี่! พวกเจ้าที่เหลือ ช่วยข้าปราบนางด้วย!",
  ui_story_5053_50531502_27_dialog_content = "อะไร หมายถึงตอนนี้?!",
  ui_story_5053_50531502_28_dialog_content = "คุณวางแผนที่จะพาน้องสาวของฉันกลับมาในสภาพนี้?!",
  ui_story_5053_50531502_29_dialog_content = "ถ้าโยชูวาจะทำร้ายใครในพวกคุณ มันก็มีแต่จะทำให้หัวใจของเธอแตกสลาย",
  ui_story_5053_50531502_30_dialog_content = "ทุกคนที่ต่อต้านอุดมคติของฉันจะต้องพินาศ! ตายซะ ไอ้พวกทรยศ!!!",
  ui_story_5053_50531502_31_dialog_content = "ทำไมแม่ต้องมาเป็นอย่างนี้ เจ้ามีความเกลียดชังในใจต่อเรามากขนาดนี้จริงหรือ...?",
  ui_story_5053_50531502_32_dialog_content = "วอนนี่...อย่าเศร้าไป...",
  ui_story_5053_50531502_33_dialog_content = "ฝากสิ่งนี้...ไว้กับผม...",
  ui_story_5053_50531502_34_dialog_content = "แม่...?",
  ui_story_5053_50531502_35_dialog_content = "การโจมตีของเราไร้ประโยชน์! Mia หยุดยืนอยู่รอบ ๆ และมุ่งเน้นไปที่การต่อสู้!",
  ui_story_5053_50531502_36_dialog_content = "...โจชัว? เดี๋ยวนะ ทำอะไรน่ะ! อย่าเข้าใกล้อีกครึ่งหนึ่งของคุณ!!",
  ui_story_5053_50531502_37_dialog_content = "... เชื่อเธอ คาเลบ",
  ui_story_5053_50531502_38_dialog_content = "ปล่อยฉันนะ ชวาร์ตษ์! อย่าพยายามหยุดฉัน! โจชัว!!!",
  ui_story_5053_50531502_39_dialog_content = "ลมแรงเกินกว่าจะลืมตา! ฉันใช้คริสตัลแห่งความทรงจำชั่วนิรันดร์แบบนี้ไม่ได้!",
  ui_story_5053_50531502_40_dialog_content = "ฮ-ห๊ะ?! IIII กำลังปลิวไป! ช่วยฉันด้วย-",
  ui_story_5053_50531502_41_dialog_content = "จากิน!",
  ui_story_5053_50531502_42_dialog_content = "ต๊าย ขอบคุณ PlayerName...ห๊ะ?",
  ui_story_5053_50531502_43_dialog_content = "ไม่ต้องกลัว...เดี๋ยวมันก็ผ่านไป",
  ui_story_5053_50531502_44_dialog_content = "ครั้งนี้อย่าลืมจับมือกันไว้ให้แน่นๆ นะทุกคน",
  ui_story_5053_50531502_45_dialog_content = "เจ-โจชัว...?",
  ui_story_5053_50531502_46_dialog_content = "แม่... นี่เธอ...",
  ui_story_5053_50531502_47_dialog_content = "เลขที่! อยู่ด้านหลัง...",
  ui_story_5053_50531502_48_dialog_content = "พอแล้ว. ได้เวลาให้ทุกคนกลับบ้านแล้ว",
  ui_story_5053_50531502_49_dialog_content = "เลขที่! อย่ามาใกล้ฉัน... นุ๊ย!!!",
  ui_story_5053_50531502_50_dialog_content = "<size=50>โจชัว!!!</size>",
  ui_story_5053_50531601_1_dialog_content = "ในที่สุดฉันก็ได้พบคุณ",
  ui_story_5053_50531601_2_dialog_content = "เป็นคุณนั้นเอง...! เลขที่! อยู่ห่าง ๆ ฉันไว้!",
  ui_story_5053_50531601_3_dialog_content = "คุณรังเกียจฉันจริงๆเหรอ?",
  ui_story_5053_50531601_4_dialog_content = "แน่นอนฉัน! เมื่อเร็ว ๆ นี้คุณเห็นตัวเองในกระจกหรือไม่? ใครจะทนเห็นคนน่าเกลียดรักเขาน้อยกว่ากันเล่า!",
  ui_story_5053_50531601_5_dialog_content = "ฉัน... ฉันเองก็เคยรู้สึกแบบนั้นเหมือนกัน",
  ui_story_5053_50531601_6_dialog_content = "แต่เมื่อฉันเห็นว่าครอบครัวและเพื่อนๆ ห่วงใยฉันมากเพียงใด ฉันก็เริ่มมองข้ามความเกลียดชังในตัวเองและกลับมารักตัวเองอีกครั้ง",
  ui_story_5053_50531601_7_dialog_content = "น่ารังเกียจแค่ไหน...",
  ui_story_5053_50531601_8_dialog_content = "คุณเคยเห็นตัวเองในกระจกด้วยหรือไม่?",
  ui_story_5053_50531601_9_dialog_content = "ฉันมี. ฉันเคยฝึกควบคุมการแสดงออกหน้ากระจกเป็นเวลาสามชั่วโมงทุกวัน ฉันไม่มีเหตุผลที่จะต้องจ้องมองตัวเองอีกต่อไป",
  ui_story_5053_50531601_10_dialog_content = "ใช่แล้ว คุณเป็นนักรบที่กล้าหาญและไร้ความกลัวมาโดยตลอด เป็นคนที่ยอมทำทุกอย่างเพื่อให้อุดมคติของเธอเป็นจริง",
  ui_story_5053_50531601_11_dialog_content = "แต่ทุกคนมีสิ่งที่พวกเขากลัว และคุณก็ไม่มีข้อยกเว้น สำหรับคุณ...",
  ui_story_5053_50531601_12_dialog_content = "พ่อของคุณกำลังจะตาย",
  ui_story_5053_50531601_13_dialog_content = "?!",
  ui_story_5053_50531601_14_dialog_content = "มันเป็นลูกและพี่ชายของคุณเรียนรู้ความจริง",
  ui_story_5053_50531601_15_dialog_content = "หยุดนะ...",
  ui_story_5053_50531601_16_dialog_content = "สามีของคุณแยกทางกับคุณ",
  ui_story_5053_50531601_17_dialog_content = "ฉันบอกให้หยุด!!!",
  ui_story_5053_50531601_18_dialog_content = "คุณต่างหากที่กลัวเรื่องพวกนั้น...ไม่ใช่ฉัน! คุณเป็นคนหนึ่งที่ยืนกรานที่จะมีอารมณ์ไร้จุดหมายเหล่านั้น!",
  ui_story_5053_50531601_19_dialog_content = "ฉันไม่ต้องการมัน... ฉันไม่ต้องการครอบครัวหรือความรู้สึกเพื่อบรรลุความทะเยอทะยานของฉัน! ฉันต้องเสียสละตัวเองเท่านั้น!",
  ui_story_5053_50531601_20_dialog_content = "ฉันรู้. คุณต้องการใช้ชีวิตที่เรียบง่ายไม่ซับซ้อนเท่านั้น ด้วยวิธีนี้ คุณจะไม่ต้องพบกับความสุขหรือความเจ็บปวดจากการสูญเสีย",
  ui_story_5053_50531601_21_dialog_content = "มันเป็นความกลัวที่จะรับรู้ถึงอารมณ์เหล่านั้นที่ทำให้คุณบังคับให้ฉันออกจากร่างกายของคุณ",
  ui_story_5053_50531601_22_dialog_content = "หุบปาก...พอแล้ว...",
  ui_story_5053_50531601_23_dialog_content = "ฉันไม่สามารถไว้วางใจพวกเขา! พวกมันไม่ฟังข้า... พวกมันต้องการทรยศข้าเท่านั้น...",
  ui_story_5053_50531601_24_dialog_content = "คนไม่ใช่เครื่องจักร ทุกคนมีความคิดและความรู้สึกของตัวเอง",
  ui_story_5053_50531601_25_dialog_content = "“ตั้งแต่ที่ฉันบอกเลิกเธอวันนั้น ฉันคิดเรื่องนี้มาตลอด”",
  ui_story_5053_50531601_26_dialog_content = "\"ผิดไหมที่เราจะฝากความฝันไว้กับคนอื่น\"",
  ui_story_5053_50531601_27_dialog_content = "ดาเนียลเคยพูดไว้ครั้งก่อน จำได้ไหม?",
  ui_story_5053_50531601_28_dialog_content = "เขาไม่เป็นอะไรนอกจากคนโกหก...",
  ui_story_5053_50531601_29_dialog_content = "เราพึ่งพาเขามากเกินไป เราบังคับให้น้ำหนักของอุดมคติของเราอยู่บนบ่าของคนเพียงคนเดียว",
  ui_story_5053_50531601_30_dialog_content = "คุณรู้ดีกว่าฉันว่าครอบครัวของลอร์ดไม่สามารถสัมผัสกับความสุขของชีวิตธรรมดาได้... แต่ฉันก็ไม่เคยหยุดหวังที่จะได้มัน",
  ui_story_5053_50531601_31_dialog_content = "นักฆ่าผู้โหดเหี้ยม ภรรยาที่สมบูรณ์แบบของเจ้าเมือง...",
  ui_story_5053_50531601_32_dialog_content = "เราเปลี่ยนไปมาระหว่างตัวตนที่คนอื่นมอบให้เราอยู่ตลอดเวลา แต่ไม่มีตัวตนใดที่สะท้อนถึงตัวตนที่แท้จริงของเรา",
  ui_story_5053_50531601_33_dialog_content = "ยังไม่รู้ว่าแท้จริงแล้วเราเป็นใคร...",
  ui_story_5053_50531601_34_dialog_content = "...",
  ui_story_5053_50531601_35_dialog_content = "แต่สิ่งหนึ่งที่ฉันรู้ก็คือ ฉันไม่อยากสูญเสียคนที่ฉันรักไป นั่นจะสำคัญกว่าความจริงเสมอ",
  ui_story_5053_50531601_36_dialog_content = "ดังนั้นมากับฉัน ถึงเวลาที่จะหยุดการต่อสู้",
  ui_story_5053_50531601_37_dialog_content = "อ๊าก! มือของคุณ... รู้สึกเหมือนมีหนามปกคลุม! แตะนิดเดียวก็เจ็บมาก!",
  ui_story_5053_50531601_38_dialog_content = "แต่ถึงกระนั้นกลับรู้สึกอบอุ่นเหลือเกิน...ความรู้สึกนี้มันอะไรกัน?",
  ui_story_5053_50531601_39_dialog_content = "เป็นอย่างนี้นี่เอง <color=#FFB400>รัก</color> รู้สึก",
