  ui_story_5053_50531601_50_dialog_content = "อะบราคาดาบร้า!",
  ui_story_5053_50531601_51_dialog_content = "โจชัว! ฉันไม่ทิ้งนาย!! โจชัว!!!",
  ui_story_5053_50531601_52_dialog_content = "เจ้าสารเลวปากแข็ง... Jakine จับ Mia ไว้!",
  ui_story_5053_50531601_53_dialog_content = "อะ-คุณพูดว่าอะไรนะ? สายลมไม่ได้ยิน!!",
  ui_story_5053_50531601_54_dialog_content = "ฉันทนไม่ได้อีกต่อไป! PlayerName!!",
  ui_story_5053_50531601_55_dialog_content = "อ๊ากกก!!!",
  ui_story_5053_50531601_56_dialog_content = "แล้วจับฉันไว้",
  ui_story_5053_50531601_57_dialog_content = "เป็นคุณนั้นเอง...?",
  ui_story_5053_50531601_58_dialog_content = "\"... ฉันหวังว่าจดหมายฉบับนี้จะพบคุณโดยดี\"",
  ui_story_5053_50531601_59_dialog_content = "“ช่วงนี้คุณเป็นยังไงบ้าง? คนอื่นๆ และฉันสบายดี”",
  ui_story_5053_50531601_60_dialog_content = "เขียนจดหมายเหรอ? สำหรับใคร?",
  ui_story_5053_50531601_61_dialog_content = "ว้าว! เจ-จาคีน! คุณกลัวฉัน...",
  ui_story_5053_50531601_62_dialog_content = "ฮี่ฮี่ ขอโทษด้วย!",
  ui_story_5053_50531601_63_dialog_content = "สวัสดีตอนบ่าย PlayerName",
  ui_story_5053_50531601_64_dialog_content = "สวัสดีตอนบ่าย! พวกนายมาเร็วแน่ ฉันนึกว่าจาคีนจะมาสายซะอีก!",
  ui_story_5053_50531601_65_dialog_content = "เฮ้ มันไม่ใช่ความผิดของฉัน ที่ทุกคนอยากรู้เกี่ยวกับงานของฉัน! เป็นเรื่องยากที่จะจัดตารางเวลาเมื่อมีกลุ่มคนคอยตั้งคำถามกับคุณอยู่ตลอดเวลา...",
  ui_story_5053_50531601_66_dialog_content = "ใช่ ฉันแน่ใจว่าการเป็นคนดังที่ Dawn Academy จะต้องแย่มากสำหรับ Jakine \"Visiting Scholar\"",
  ui_story_5053_50531601_67_dialog_content = "ฮี่ฮี่ อย่าเรียกฉันแบบนั้นสิ! คุณจะทำให้ฉันหน้าแดง...",
  ui_story_5053_50531601_68_dialog_content = "ยังไงก็ตาม คุณจัดการเรื่องของคุณเรียบร้อยแล้วใช่ไหม มีอา?",
  ui_story_5053_50531601_69_dialog_content = "ได้! ทุกอย่างถูกพรากไป!",
  ui_story_5053_50531601_70_dialog_content = "น่าเสียดาย เรายุ่งมากจนไม่ได้มีโอกาสบอกลากัน...",
  ui_story_5053_50531601_71_dialog_content = "ไม่ต้องกังวล คุณสามารถมาหาเธอได้ที่ Colossus! ฉันจะแจ้งให้คุณทราบในครั้งต่อไปที่เธอขึ้นเครื่อง",
  ui_story_5053_50531601_72_dialog_content = "ไม่เป็นไร ไว้เจอกันใหม่เมื่อถึงเวลา",
  ui_story_5053_50531601_73_dialog_content = "อ่อ ค่ะ...",
  ui_story_5053_50531601_74_dialog_content = "\"ตั้งแต่นั้นเป็นต้นมา มีหลายอย่างเกิดขึ้นที่นี่ ผู้คนมากมายตัดสินใจโดยไม่คาดคิด\"",
  ui_story_5053_50531601_75_dialog_content = "\"ฉันสัญญาว่าจะจัดการเรื่องราวทั้งหมดให้คุณ ดังนั้นเรามาเริ่มกันตั้งแต่ต้น\"",
  ui_story_5053_50531601_76_dialog_content = "\"ในตอนนั้น เราออกจาก <color=#FFB400>คริสตัลแห่งความทรงจำนิรันดร์</color>\"",
  ui_story_5053_50531601_77_dialog_content = "\"ก่อนที่เราจะมีเวลาเพื่อให้แน่ใจว่าทุกคนไม่เป็นไร Caleb ก็ออกไปที่ประตูแล้วและรีบกลับบ้านของเขา\"",
  ui_story_5053_50531601_78_dialog_content = "\"ไม่นานนักเราก็ไล่ตามเขา... เพียงเพื่อจะพบเขากับเลดี้โจชัว ซึ่งเขาซ่อนตัวอยู่ในบ้านตลอดหลายปีที่ผ่านมา\"",
  ui_story_5053_50531601_79_dialog_content = "ตาแม่เพิ่งขยับ...!",
  ui_story_5053_50531601_80_dialog_content = "ส่งยานั่นมาให้ฉัน! ที่อยู่บนชั้นซ้ายมือ!",
  ui_story_5053_50531601_81_dialog_content = "W-เดี๋ยวก่อน ฉันยังหาผ้าก๊อซอยู่!",
  ui_story_5053_50531601_82_dialog_content = "ฉันมีที่นี่",
  ui_story_5053_50531601_83_dialog_content = "“หลังจากผ่านกระบวนการฉุกเฉินอันตึงเครียด ในที่สุด Lady Joshua ก็หายจากอาการวิกฤตแล้ว ไม่กี่วันต่อมา เธอก็ตื่นขึ้น”",
  ui_story_5053_50531601_84_dialog_content = "\"น่าเสียดาย... เธอสูญเสียความทรงจำทั้งหมดไป\"",
  ui_story_5053_50531601_85_dialog_content = "ยังไง... เรื่องนี้เกิดขึ้นได้อย่างไร? เธอนอนหมดสตินานเกินไปหรือเปล่า? หรือเป็นระเบิดครั้งก่อน?",
  ui_story_5053_50531601_86_dialog_content = "ไม่ว่าในกรณีใด ดูเหมือนว่าพี่สาวของฉันจะไม่มีอาการบุคลิกภาพแตกแยกอีกต่อไป แต่ยังไง...?",
  ui_story_5053_50531601_87_dialog_content = "มันอาจเกี่ยวข้องกับคริสตัลแห่งความทรงจำชั่วนิรันดร์ จาคีน?",
  ui_story_5053_50531601_88_dialog_content = "อืม... ฉันไม่ค่อยแน่ใจนัก",
  ui_story_5053_50531601_89_dialog_content = "และนั่นหมายความว่าอย่างไร มันร้ายแรงนะรู้ยัง!",
  ui_story_5053_50531601_90_dialog_content = "\"เพื่อซ่อมแซม Crystal of Eternal Memory รวมทั้งช่วยฟื้นคืนชีพของ Lady Joshua...\"",
  ui_story_5053_50531601_91_dialog_content = "\"จาคีนตัดสินใจอยู่ที่ลูโมโพลิสต่ออีกระยะหนึ่ง และเริ่มทำการวิจัยร่วมกับคาเลบ\"",
  ui_story_5053_50531601_92_dialog_content = "\"เขายังตั้งชื่อให้เธอว่า \"Visiting Scholar to the Dawn Academy\" เพียงเพื่อทำให้เธอมีความสุข\"",
  ui_story_5053_50531601_93_dialog_content = "\"ฉันไม่คิดว่าชื่อเรื่องมีอำนาจที่แท้จริง แต่ตราบใดที่ Jakine ไม่พบ ... \"",
  ui_story_5053_50531601_94_dialog_content = "ตอนนี้ สิ่งที่เรารู้ก็คือ ด้วยเหตุผลบางประการ ปีศาจขาวและเทพแห่งความมืดได้ติดต่อกันในตอนท้ายสุด",
  ui_story_5053_50531601_94X1_dialog_content = "เมื่อบุคลิกที่ขัดแย้งกันของทั้งคู่หายไป สภาพจิตใจของ Lady Joshua ก็กลับมาเป็นปกติ",
  ui_story_5053_50531601_95_dialog_content = "สำหรับเมล็ดพันธุ์นั้น เรายังคงต้องศึกษามันอย่างลึกซึ้ง แต่เราสามารถไว้วางใจ Caleb ได้เท่านั้น",
  ui_story_5053_50531601_96_dialog_content = "ทำได้ดีมาก ทูต Jakine แห่ง Northland ขอบคุณที่อยู่ใน Lumopolis หลายวันและช่วยเหลือ Caleb ในความพยายาม",
  ui_story_5053_50531601_97_dialog_content = "เป็นเกียรติของฉัน! ฉันไม่รู้สึกเหมือนเป็นคนนอกหลังจากที่เราผ่านอะไรมาด้วยกัน!",
  ui_story_5053_50531601_98_dialog_content = "ยิ่งไปกว่านั้น ฉันควรจะเติม Crystal of Eternal Memory ด้วยน้ำจาก Lake Mirror เพื่อไม่ให้มันแตก...",
  ui_story_5053_50531601_99_dialog_content = "อ้อ พูดถึงคริสตัลก็โดนจับได้! และตอนนี้ Lady Joshua กลับมาแล้ว คุณสามารถใช้งานได้ทุกเมื่อ!",
  ui_story_5053_50531601_100_dialog_content = "ขอบคุณ ฉันจะรักษามันให้ปลอดภัยเพื่อป้องกันไม่ให้คนอื่นเข้ามาโดยไม่ตั้งใจ",
  ui_story_5053_50531601_101_dialog_content = "ใช่... แต่จริงๆ แล้วฉันกังวลนิดหน่อยเกี่ยวกับคาเลบ ตั้งแต่ Lady Joshua ตื่นขึ้น เขาก็อยู่รอบตัวเธอตลอดเวลา!",
  ui_story_5053_50531601_102_dialog_content = "ฉันยังได้ยินมาว่าเขาต้องการลาออกจาก Dawn Academy เพื่ออยู่บ้านและดูแล Lady Joshua เต็มเวลา... สงสัยว่าเขาเข้าใจความหมายทั้งหมดหรือไม่",
  ui_story_5053_50531601_103_dialog_content = "ช่างอ่อนหัดตลอดกาลเสียจริง... ข้าได้ยินมาว่าท่านกำลังมองหาอัศวินที่ชื่อชาโรน่า เป็นเรื่องจริงหรือไม่?",
  ui_story_5053_50531601_104_dialog_content = "ฉัน. ฉันเห็นว่าเครือข่ายของคุณมีจมูกถึงพื้นแล้ว เจ้านายของฉัน! คุณช่วยแนะนำให้ฉันรู้จักเธอได้ไหม",
  ui_story_5053_50531601_105_dialog_content = "ฉันขอโทษ Jakine แต่ Sharona ออกจาก Lumopolis ไปสักพักแล้ว ฉันไม่สามารถทำตามคำขอของคุณได้",
  ui_story_5053_50531601_106_dialog_content = "อะไร แต่ความฝันของเธอที่จะเป็นอัศวินที่ทรงพลังที่สุดไม่ใช่เหรอ...?",
  ui_story_5053_50531601_107_dialog_content = "คุณสามารถตามหาเธอใน Illumina แต่อย่านำ Lumopolis มาให้ฉัน",
  ui_story_5053_50531601_108_dialog_content = "และอย่าลืมว่าสิ่งที่เกิดขึ้นในคริสตัลนั้นไม่ใช่เรื่องจริง ไม่ว่าสายสัมพันธ์ระหว่างคุณสองคนจะแน่นแฟ้นเพียงใด...",
  ui_story_5053_50531601_109_dialog_content = "มันเป็นเพียงความทะเยอทะยาน มีการเปลี่ยนแปลงมากมายในช่วงสิบสองปี",
  ui_story_5053_50531601_110_dialog_content = "ฉันเข้าใจแล้ว... ไม่เป็นไร ตราบใดที่เรายังซื่อสัตย์ต่อตัวตนของเรา เราก็ยังคงเป็นเพื่อนกันได้!",
  ui_story_5053_50531601_111_dialog_content = "อยู่กับความจริงว่าคุณเป็นใคร คุณบอกว่า... คุณพูดถูก",
  ui_story_5053_50531601_112_dialog_content = "“ฉันคิดว่าการที่เลดี้โจชัวสูญเสียความทรงจำจะทำให้ครอบครัวของเธอต้องโศกเศร้าอีกครั้ง”",
  ui_story_5053_50531601_113_dialog_content = "“นอกจากพวกเขาจะไม่รู้สึกว่าพ่ายแพ้ แต่กลับดีใจอย่างรวดเร็วในการรวมตัวอีกครั้งหลังจากผิดหวังชั่วครู่”",
  ui_story_5053_50531601_114_dialog_content = "\"ดีใจที่ได้เห็นครอบครัวมีความสุขและสมบูรณ์... ช่างเป็นสายสัมพันธ์ที่เรียบง่ายแต่ไร้ที่ติที่พวกเขาแบ่งปัน\"",
  ui_story_5053_50531601_115_dialog_content = "\"แต่ <color=#FFB400>เจ้าเมืองและครอบครัวของเขา</color> เป็นที่จับตามองมากเกินไปสำหรับพวกเขาที่จะเพลิดเพลินไปกับความสุขของครอบครัวปกติ",
  ui_story_5053_50531601_116_dialog_content = "<color=#e8d9bb>คฤหาสน์ Magnus บ้านของ Caleb</color>",
  ui_story_5053_50531601_117_dialog_content = "ฉันกลับมาแล้ว พี่สาว! ลองดู. เป็นชาผลไม้ใหม่ล่าสุดจาก Umbraton เดิมพันที่คุณจะรักมัน!",
  ui_story_5053_50531601_118_dialog_content = "กลับบ้านดีๆนะลุง",
  ui_story_5053_50531601_119_dialog_content = "ยินดีต้อนรับกลับ. เอ่อ วันนี้วันทำงานไม่ใช่เหรอ คุณไม่ทำงานเหรอ คาเลบ?",
  ui_story_5053_50531601_120_dialog_content = "ไม่มีงานใดสำคัญเท่ากับคุณ ฉันยื่นใบลาออกจากโรงเรียนดอว์นแล้ว ฉันจะอยู่กับคุณนับจากนี้",
  ui_story_5053_50531601_121_dialog_content = "อะไรคุณลาออก? คุณจะละทิ้งอาชีพและแรงบันดาลใจที่มีต่อฉันหรือไม่?",
  ui_story_5053_50531601_122_dialog_content = "อย่าพูดแบบนั้นสิพี่สาว ไม่มีอะไรจะยิ่งใหญ่เท่ากับการใช้ชีวิตอย่างมีความสุขกับครอบครัวของคุณ",
  ui_story_5053_50531601_123_dialog_content = "และมีอาก็อยากกลับไปหาครอบครัวของเธอที่ลูโมโพลิสเช่นกัน ใช่ไหม มิอา?",
  ui_story_5053_50531601_124_dialog_content = "ก็... ที่จริงฉันมาที่นี่เพื่อคุยกับแม่ ฉันอยากอยู่ในอัมบราตัน",
  ui_story_5053_50531601_125_dialog_content = "อะไร ทำไมคุณถึงคิดอย่างนั้นตอนนี้? Schwartz ขมวดคิ้วคุณอีกครั้งหรือไม่?",
  ui_story_5053_50531601_126_dialog_content = "ไม่ มันเป็นการตัดสินใจของฉันเอง พ่ออยู่ข้างหลังด้วย",
  ui_story_5053_50531601_127_dialog_content = "เมื่อก่อนฉันเคยอ่อนแอและโชคร้าย จำใจต้องจากไป ทนลำบาก...",
  ui_story_5053_50531601_128_dialog_content = "แต่ฉันก็ได้เห็นความจริงของโลกภายนอกลูโมโปลิสด้วย และนั่นทำให้ฉันเป็นฉันในทุกวันนี้ อย่างไรก็ตาม ฉันรู้สึกว่ายังไม่เพียงพอ",
  ui_story_5053_50531601_129_dialog_content = "ตอนนี้คุณน่าจะรู้แล้วว่าการที่คุณหยุดพักผ่อนเยอะๆ และผมไปไหนมาไหนด้วยผ้าคลุมหน้า ข่าวลือเริ่มแพร่สะพัดในสวนลุมโปลิส",
  ui_story_5053_50531601_130_dialog_content = "พ่อมาที่นี่เพื่อไปหาแม่ไม่ได้เพราะเหตุนั้น...ถึงเราจะปิดบังแม่",
  ui_story_5053_50531601_131_dialog_content = "ฉันรู้ว่า! และฉันได้มองหาวิธีแก้ปัญหา เลวร้ายยิ่งกว่านั้น แย่ที่สุด เราจะย้ายออกจากลูโมโปลิส!",
  ui_story_5053_50531601_132_dialog_content = "แล้วจะเป็นอย่างไรถ้าภรรยาของ City Lord ฟื้นขึ้นมาหลังจากหลายปีมานี้...",
  ui_story_5053_50531601_133_dialog_content = "คุณต้องการพลังที่แท้จริงเพื่อท้าทาย Schwartz! หวังพึ่งแต่การโกงกินทางการเมืองไม่ได้!",
  ui_story_5053_50531601_134_dialog_content = "ใช่ ฉันรู้ว่ามันไม่ใช่ความผิดของครอบครัว แต่ก็ยังเป็นสิ่งที่เราต้องอดทน",
  ui_story_5053_50531601_135_dialog_content = "ในที่สุดฉันก็เข้าใจว่าพ่อรู้สึกอย่างไรในตอนนี้... นั่นคือเหตุผลที่ฉันไม่ต้องการอ้อมกอดของแม่อีกต่อไป",
  ui_story_5053_50531601_136_dialog_content = "เนื่องจากฉันไม่สามารถอยู่รอดภายใต้แสงสปอตไลต์ใน Lumopolis ได้ ให้ฉันอยู่ในความมืดเหมือนเงา",
